/// TASK-103: `aida rebase` — detect → classify → execute → report.
/// The detection + classification live in `aida_core::rebase` (reusable
/// substrate); this handler owns the execute (auto/prompt/stash) and
/// report (human + `--json`) phases. trace:TASK-103 | ai:claude
fn handle_rebase_command(
    store_path: &std::path::Path,
    auto: bool,
    dry_run: bool,
    no_fetch: bool,
    no_stash: bool,
    json: bool,
    branch: Option<&str>,
) -> Result<()> {
    use aida_core::rebase::{self, DetectError};

    let project_root = store_path
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());

    // ---- Phase 1+2: detect + classify ----
    let detection = match rebase::detect(&project_root, branch, !no_fetch) {
        Ok(d) => d,
        Err(DetectError::NoUpstream(b)) => {
            // No upstream is a soft "nothing to rebase onto" — report
            // and exit 0 so scripts/skills can call this unconditionally.
            if json {
                println!(
                    "{}",
                    serde_json::json!({
                        "classification": "clean",
                        "branch": b,
                        "note": "no upstream configured",
                    })
                );
            } else {
                println!(
                    "{} branch {} has no upstream — nothing to rebase onto.",
                    "·".dimmed(),
                    b.cyan()
                );
                println!(
                    "  {}",
                    "Pass --branch <ref> to pick a target explicitly.".dimmed()
                );
            }
            return Ok(());
        }
        Err(e) => anyhow::bail!("rebase detection failed: {}", e),
    };
    let class = detection.class();

    // ---- Phase 3: execute ----
    let mut executed = false;
    let mut aborted_conflict = false;
    let mut conflicts: Vec<String> = Vec::new();
    let mut refused_dirty = false;

    let want_execute = !dry_run && class.needs_rebase();
    if want_execute {
        let interactive = std::io::IsTerminal::is_terminal(&std::io::stdin());
        // Safe cases run under --auto; risky cases always need a human.
        let proceed = if class.is_safe() {
            if auto {
                true
            } else if interactive {
                rebase_confirm(&format!(
                    "Rebase {} onto {} ({} behind)?",
                    detection.branch, detection.upstream, detection.behind
                ))
            } else {
                false // non-interactive, no --auto: report only
            }
        } else {
            // diverged-risky: surface the overlap, always prompt.
            if !json {
                eprintln!(
                    "{} {} file{} touched on BOTH sides — rebase may conflict:",
                    "⚠".yellow().bold(),
                    detection.overlap.len(),
                    if detection.overlap.len() == 1 {
                        ""
                    } else {
                        "s"
                    }
                );
                for f in detection.overlap.iter().take(10) {
                    eprintln!("    {}", f.dimmed());
                }
            }
            interactive
                && rebase_confirm(&format!(
                    "Rebase anyway ({} ahead, {} behind, overlap exists)?",
                    detection.ahead, detection.behind
                ))
        };

        if proceed {
            if !detection.working_tree_clean && no_stash {
                refused_dirty = true;
            } else {
                let stashed = !detection.working_tree_clean;
                if stashed {
                    let _ = std::process::Command::new("git")
                        .arg("-C")
                        .arg(&project_root)
                        .args(["stash", "push", "-u", "-m", "aida rebase auto-stash"])
                        .status();
                }
                let status = std::process::Command::new("git")
                    .arg("-C")
                    .arg(&project_root)
                    .args(["rebase", &detection.upstream])
                    .status();
                match status {
                    Ok(s) if s.success() => executed = true,
                    _ => {
                        // Conflict (or other failure): collect the
                        // conflicted paths, then abort to leave a clean
                        // state — `aida rebase` is a convenience verb,
                        // not a place to strand a half-finished rebase.
                        conflicts = std::process::Command::new("git")
                            .arg("-C")
                            .arg(&project_root)
                            .args(["diff", "--name-only", "--diff-filter=U"])
                            .output()
                            .ok()
                            .filter(|o| o.status.success())
                            .map(|o| {
                                String::from_utf8_lossy(&o.stdout)
                                    .lines()
                                    .map(|l| l.to_string())
                                    .collect()
                            })
                            .unwrap_or_default();
                        let _ = std::process::Command::new("git")
                            .arg("-C")
                            .arg(&project_root)
                            .args(["rebase", "--abort"])
                            .status();
                        aborted_conflict = true;
                    }
                }
                if stashed {
                    let _ = std::process::Command::new("git")
                        .arg("-C")
                        .arg(&project_root)
                        .args(["stash", "pop"])
                        .status();
                }
            }
        }
    }

    // ---- Phase 4: report ----
    rebase_report(
        &detection,
        class,
        executed,
        aborted_conflict,
        refused_dirty,
        &conflicts,
        json,
    );
    if aborted_conflict {
        anyhow::bail!("rebase hit conflicts and was aborted — resolve manually");
    }
    Ok(())
}

/// TASK-103: yes/no confirmation for the rebase execute phase.
fn rebase_confirm(question: &str) -> bool {
    use std::io::Write;
    eprint!("{} [y/N] ", question);
    let _ = std::io::stderr().flush();
    let mut answer = String::new();
    let _ = std::io::stdin().read_line(&mut answer);
    matches!(answer.trim().to_ascii_lowercase().as_str(), "y" | "yes")
}

/// TASK-103: render the rebase report — human-readable, or `--json`.
fn rebase_report(
    d: &aida_core::rebase::RebaseDetection,
    class: aida_core::rebase::RebaseClass,
    executed: bool,
    aborted_conflict: bool,
    refused_dirty: bool,
    conflicts: &[String],
    json: bool,
) {
    // Suggested follow-ups, classification + outcome aware.
    let mut followups: Vec<String> = Vec::new();
    if refused_dirty {
        followups.push("commit or stash your changes, then re-run `aida rebase`".to_string());
    } else if aborted_conflict {
        followups.push(format!(
            "git rebase {} — resolve conflicts manually",
            d.upstream
        ));
    } else if executed {
        if d.ahead > 0 {
            followups.push("aida push — publish the rebased commits".to_string());
        }
    } else {
        match class {
            aida_core::rebase::RebaseClass::AheadOnly => {
                followups.push("aida push — publish your local commits".to_string());
            }
            aida_core::rebase::RebaseClass::BehindOnly
            | aida_core::rebase::RebaseClass::DivergedSafe => {
                followups.push("aida rebase --auto — execute this safe rebase".to_string());
            }
            aida_core::rebase::RebaseClass::DivergedRisky => {
                followups.push(format!(
                    "review the {} overlapping file(s), then `aida rebase` to decide",
                    d.overlap.len()
                ));
            }
            aida_core::rebase::RebaseClass::Clean => {}
        }
    }

    if json {
        let obj = serde_json::json!({
            "branch": d.branch,
            "upstream": d.upstream,
            "fetched": d.fetched,
            "ahead": d.ahead,
            "behind": d.behind,
            "classification": class.label(),
            "overlap": d.overlap,
            "working_tree_clean": d.working_tree_clean,
            "executed": executed,
            "aborted_conflict": aborted_conflict,
            "refused_dirty": refused_dirty,
            "conflicts": conflicts,
            "followups": followups,
        });
        println!(
            "{}",
            serde_json::to_string_pretty(&obj).unwrap_or_else(|_| "{}".to_string())
        );
        return;
    }

    println!(
        "{} {} vs {}",
        "Rebase:".bold(),
        d.branch.cyan(),
        d.upstream.cyan()
    );
    println!(
        "  state      {} ahead · {} behind{}",
        d.ahead,
        d.behind,
        if d.fetched {
            ""
        } else {
            "  (--no-fetch: cached refs)"
        }
    );
    let class_colored = match class {
        aida_core::rebase::RebaseClass::Clean | aida_core::rebase::RebaseClass::AheadOnly => {
            class.label().green().to_string()
        }
        aida_core::rebase::RebaseClass::BehindOnly
        | aida_core::rebase::RebaseClass::DivergedSafe => class.label().cyan().to_string(),
        aida_core::rebase::RebaseClass::DivergedRisky => class.label().yellow().to_string(),
    };
    println!("  class      {}", class_colored);
    if !d.overlap.is_empty() {
        println!(
            "  overlap    {} file{} on both sides",
            d.overlap.len(),
            if d.overlap.len() == 1 { "" } else { "s" }
        );
        for f in d.overlap.iter().take(10) {
            println!("               {}", f.dimmed());
        }
    }
    if !d.working_tree_clean {
        println!(
            "  worktree   {} ({} dirty path(s))",
            "dirty".yellow(),
            d.dirty_files.len()
        );
    }
    if executed {
        println!("  {}", "rebase executed — branch is now up to date".green());
    } else if aborted_conflict {
        println!(
            "  {} ({} conflicted path(s)) — rebase aborted, working tree restored",
            "conflicts".red(),
            conflicts.len()
        );
        for f in conflicts.iter().take(10) {
            println!("               {}", f.dimmed());
        }
    } else if refused_dirty {
        println!(
            "  {}",
            "--no-stash and the working tree is dirty — not rebasing".yellow()
        );
    }
    if !followups.is_empty() {
        println!("  {}", "next:".bold());
        for f in &followups {
            println!("    {} {}", "·".dimmed(), f);
        }
    }
}

/// BUG-95: regression coverage for the claim that `aida pull --code-only`
/// skips the Done → Completed auto-bump. The bug-as-filed asserted the
/// conditional was nested in the wrong branch; the current structure has
/// the auto-bump correctly inside the code-pull block (gated by
/// `!store_only`), so `--code-only` (code_only=true, store_only=false)
/// reaches it. This test exercises that path end-to-end via
/// `handle_pull_command` and verifies the bump fires.
/// trace:BUG-95 | ai:claude
#[cfg(test)]
mod handle_pull_command_tests {
    use super::*;

    fn run_git_in(repo: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(args)
            .output()
            .expect("git binary on PATH");
        if !out.status.success() {
            panic!(
                "git {:?} (in {:?}) failed: stdout={} stderr={}",
                args,
                repo,
                String::from_utf8_lossy(&out.stdout),
                String::from_utf8_lossy(&out.stderr)
            );
        }
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// Build a bare "remote" repo that already has one initial commit so
    /// `--ff-only` has a valid base, plus a "clone" project repo
    /// configured with `origin` pointing at it. Returns the temp guards
    /// plus the bare-repo path and the project path.
    fn make_remote_and_clone() -> (
        tempfile::TempDir,
        tempfile::TempDir,
        std::path::PathBuf,
        std::path::PathBuf,
    ) {
        let bare_tmp = tempfile::TempDir::new().unwrap();
        let bare = bare_tmp.path().to_path_buf();
        run_git_in(
            &bare,
            &["init", "--bare", "--initial-branch=main", "--quiet"],
        );

        // Seed the bare repo via a temp clone, then drop it; the project
        // clone below will fetch this initial commit.
        let seed_tmp = tempfile::TempDir::new().unwrap();
        let seed = seed_tmp.path().to_path_buf();
        run_git_in(
            &seed,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                seed.to_str().unwrap(),
            ],
        );
        run_git_in(&seed, &["config", "user.email", "test@example.com"]);
        run_git_in(&seed, &["config", "user.name", "Test"]);
        std::fs::write(seed.join("README.md"), "init\n").unwrap();
        run_git_in(&seed, &["add", "README.md"]);
        run_git_in(&seed, &["commit", "-m", "chore: init"]);
        run_git_in(&seed, &["push", "origin", "main", "--quiet"]);

        // Now make the actual project clone the test will operate on.
        let proj_tmp = tempfile::TempDir::new().unwrap();
        let proj = proj_tmp.path().to_path_buf();
        run_git_in(
            &proj,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                proj.to_str().unwrap(),
            ],
        );
        run_git_in(&proj, &["config", "user.email", "test@example.com"]);
        run_git_in(&proj, &["config", "user.name", "Test"]);

        (bare_tmp, proj_tmp, bare, proj)
    }

    /// Push a new commit referencing `spec_id` to the bare remote so a
    /// subsequent `git pull --ff-only` from the project clone fast-forwards
    /// to it. Done via a fresh temp clone to avoid touching the project
    /// repo under test.
    fn push_remote_commit_referencing(bare: &std::path::Path, spec_id: &str) {
        let tmp = tempfile::TempDir::new().unwrap();
        let work = tmp.path().to_path_buf();
        run_git_in(
            &work,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                work.to_str().unwrap(),
            ],
        );
        run_git_in(&work, &["config", "user.email", "test@example.com"]);
        run_git_in(&work, &["config", "user.name", "Test"]);
        std::fs::write(work.join("landed.txt"), "x\n").unwrap();
        run_git_in(&work, &["add", "landed.txt"]);
        run_git_in(
            &work,
            &[
                "commit",
                "-m",
                &format!("feat: teammate work ({})", spec_id),
            ],
        );
        run_git_in(&work, &["push", "origin", "main", "--quiet"]);
    }

    /// BUG-254: like `push_remote_commit_referencing`, but lets the test
    /// choose the filename + content so it can set up an untracked-file
    /// conflict on the local clone. trace:BUG-254 | ai:claude
    fn push_remote_file(bare: &std::path::Path, name: &str, content: &str, spec_id: &str) {
        let tmp = tempfile::TempDir::new().unwrap();
        let work = tmp.path().to_path_buf();
        run_git_in(
            &work,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                work.to_str().unwrap(),
            ],
        );
        run_git_in(&work, &["config", "user.email", "test@example.com"]);
        run_git_in(&work, &["config", "user.name", "Test"]);
        std::fs::write(work.join(name), content).unwrap();
        run_git_in(&work, &["add", name]);
        run_git_in(
            &work,
            &["commit", "-m", &format!("feat: add {} ({})", name, spec_id)],
        );
        run_git_in(&work, &["push", "origin", "main", "--quiet"]);
    }

    fn seed_done_spec_at(store_path: &std::path::Path, spec_id: &str) {
        let storage = Storage::new(store_path.to_path_buf());
        let mut store = storage.load().unwrap_or_default();
        let mut req = aida_core::Requirement::new(format!("test-{}", spec_id), String::new());
        req.spec_id = Some(spec_id.to_string());
        req.set_status_from_str("Done");
        store.requirements.push(req);
        storage.save(&store).unwrap();
    }

    /// BUG-95: `aida pull --code-only` (code_only=true, store_only=false)
    /// must trigger the auto-bump on the just-pulled commits. Regression
    /// guard against the bug-as-filed (claimed the conditional was in the
    /// wrong block). trace:BUG-95 | ai:claude
    #[test]
    fn pull_code_only_triggers_auto_bump() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        let storage = Storage::new(store_path.clone());
        storage
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        let spec_id = "STORY-9501".to_string();
        seed_done_spec_at(&store_path, &spec_id);

        // Remote gets the merge; our local doesn't have it yet.
        push_remote_commit_referencing(&bare, &spec_id);

        // The actual call under test: code_only=true skips the store
        // leg entirely, but the code leg + auto-bump must still run.
        handle_pull_command(&store_path, true, false, true, true, false).unwrap();

        let after = storage.load().unwrap();
        let req = after.get_requirement_by_spec_id(&spec_id).unwrap();
        assert!(
            matches!(req.status, RequirementStatus::Completed),
            "BUG-95: --code-only should have auto-bumped {} to Completed, was {:?}",
            spec_id,
            req.status
        );
    }

    /// BUG-404: when local main was already advanced to the merge commit
    /// before the pull runs — exactly what `aida pr ship` step 3
    /// (`gh pr merge --squash`) does before step 4's pull — the pull is a
    /// no-op ("Already up to date") and the narrow `pre..HEAD` range is
    /// empty, so the merged spec never bumped (it stayed Done until a manual
    /// `reconcile-status`). The fix: a no-op pull falls back to the wide
    /// scan, so a main advanced outside this pull is still covered.
    /// trace:BUG-404 | ai:claude
    #[test]
    fn pull_noop_still_auto_bumps_externally_advanced_main() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        let storage = Storage::new(store_path.clone());
        storage
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        let spec_id = "STORY-9601".to_string();
        seed_done_spec_at(&store_path, &spec_id);

        // The merge lands on the remote...
        push_remote_commit_referencing(&bare, &spec_id);
        // ...and local main is fast-forwarded to it via a RAW git pull (no
        // auto-bump) — standing in for `gh pr merge` advancing local main.
        // The spec is still Done at this point.
        run_git_in(&project_root, &["pull", "--ff-only", "origin", "main"]);

        // Now the command under test: its `git pull` is a no-op
        // ("Already up to date"), so the narrow range is empty. The BUG-404
        // fallback must still scan and bump.
        handle_pull_command(&store_path, true, false, true, true, false).unwrap();

        let after = storage.load().unwrap();
        let req = after.get_requirement_by_spec_id(&spec_id).unwrap();
        assert!(
            matches!(req.status, RequirementStatus::Completed),
            "BUG-404: a no-op pull over an externally-advanced main should still \
             auto-bump {} to Completed, was {:?}",
            spec_id,
            req.status
        );
    }

    /// BUG-254: when the code-leg `git pull --ff-only` fails (here: an
    /// untracked file would be overwritten by the merge), `handle_pull_command`
    /// must return Err so `aida pull` exits non-zero — the orchestrator's
    /// phase 5 then halts instead of falsely announcing `✓ phase 5 complete`
    /// over a stale tree (which used to break phase 6 with confusing
    /// missing-file errors). trace:BUG-254 | ai:claude
    #[test]
    fn pull_code_leg_failure_returns_err() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        let storage = Storage::new(store_path.clone());
        storage
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        // Remote adds `conflict.txt`. Locally we leave an untracked
        // `conflict.txt` with different content — `git pull --ff-only`
        // refuses (`The following untracked working tree files would be
        // overwritten by merge`).
        let spec_id = "STORY-99254".to_string();
        seed_done_spec_at(&store_path, &spec_id);
        push_remote_file(&bare, "conflict.txt", "from remote\n", &spec_id);
        std::fs::write(project_root.join("conflict.txt"), "from local untracked\n").unwrap();

        // code_only=true isolates the code leg so the test can't be
        // rescued by a successful store leg masking the code failure.
        let result = handle_pull_command(&store_path, true, false, true, true, false);
        let err = result
            .expect_err("BUG-254: handle_pull_command must return Err when code-leg ff-only fails");
        let msg = format!("{err}");
        assert!(
            msg.contains("code leg"),
            "BUG-254: error message should name the code leg, got: {msg}"
        );

        // Defensive: the Done spec must NOT have been auto-bumped — the
        // commit referencing it never landed locally.
        let after = storage.load().unwrap();
        let req = after.get_requirement_by_spec_id(&spec_id).unwrap();
        assert!(
            matches!(req.status, RequirementStatus::Done),
            "BUG-254: failed code leg must not auto-bump; status was {:?}",
            req.status
        );
    }

    /// BUG-95 mirror: `aida pull --store-only` should NOT touch the code
    /// branch (no code pull happens), so the auto-bump correctly does
    /// not fire — even if there's a Done spec that a separate code pull
    /// would have bumped. Defensive guard against an over-broad fix.
    /// trace:BUG-95 | ai:claude
    #[test]
    fn pull_store_only_does_not_run_auto_bump() {
        let (_bare_tmp, _proj_tmp, _bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        let storage = Storage::new(store_path.clone());
        storage
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        // Lay down a local code commit that references the Done spec
        // (simulating a state where the code is already at the merge —
        // but `--store-only` shouldn't scan it).
        let spec_id = "STORY-9502".to_string();
        seed_done_spec_at(&store_path, &spec_id);
        std::fs::write(project_root.join("local.txt"), "x\n").unwrap();
        run_git_in(&project_root, &["add", "local.txt"]);
        run_git_in(
            &project_root,
            &["commit", "-m", &format!("feat: x ({})", spec_id)],
        );

        // store_only=true; no orphan store configured → store-pull branch
        // prints a note + returns Ok(()). Code leg is skipped → no auto-bump.
        handle_pull_command(&store_path, false, true, true, true, false).unwrap();

        let after = storage.load().unwrap();
        let req = after.get_requirement_by_spec_id(&spec_id).unwrap();
        assert!(
            matches!(req.status, RequirementStatus::Done),
            "--store-only should NOT have auto-bumped, status was {:?}",
            req.status
        );
    }
}

/// TASK-106: coverage for the `aida push` / `aida pull` scope flags —
/// all four combinations (default / --code-only / --store-only / both)
/// at the clap-parse layer, the `AIDA_PUSH_DEFAULT` env-var override,
/// and the mutual-exclusion guard. trace:TASK-106 | ai:claude
#[cfg(test)]
mod push_pull_scope_tests {
    use super::*;
    use clap::Parser;

    /// Default: neither flag, no env → both legs.
    #[test]
    fn resolve_scope_default_is_both() {
        assert_eq!(resolve_push_scope(false, false, None), (false, false));
    }

    /// Explicit flags pass straight through.
    #[test]
    fn resolve_scope_explicit_flags() {
        assert_eq!(resolve_push_scope(true, false, None), (true, false));
        assert_eq!(resolve_push_scope(false, true, None), (false, true));
    }

    /// AIDA_PUSH_DEFAULT flips the default when no flag is passed.
    #[test]
    fn resolve_scope_env_override() {
        assert_eq!(
            resolve_push_scope(false, false, Some("code")),
            (true, false)
        );
        assert_eq!(
            resolve_push_scope(false, false, Some("code-only")),
            (true, false)
        );
        assert_eq!(
            resolve_push_scope(false, false, Some("store")),
            (false, true)
        );
        assert_eq!(
            resolve_push_scope(false, false, Some("STORE-ONLY")),
            (false, true)
        );
        // Unrecognized / explicit "both" → historical default.
        assert_eq!(
            resolve_push_scope(false, false, Some("both")),
            (false, false)
        );
        assert_eq!(
            resolve_push_scope(false, false, Some("xyz")),
            (false, false)
        );
    }

    /// An explicit flag always wins over the env var.
    #[test]
    fn resolve_scope_explicit_beats_env() {
        assert_eq!(
            resolve_push_scope(true, false, Some("store")),
            (true, false)
        );
        assert_eq!(resolve_push_scope(false, true, Some("code")), (false, true));
    }

    /// All four parse combinations for `aida push`.
    #[test]
    fn push_flag_combinations_parse() {
        // default
        let cli = Cli::try_parse_from(["aida", "push"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Push {
                code_only: false,
                store_only: false,
                ..
            }
        ));
        // --code-only
        let cli = Cli::try_parse_from(["aida", "push", "--code-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Push {
                code_only: true,
                store_only: false,
                ..
            }
        ));
        // --store-only
        let cli = Cli::try_parse_from(["aida", "push", "--store-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Push {
                code_only: false,
                store_only: true,
                ..
            }
        ));
        // both → clap rejects via conflicts_with
        assert!(Cli::try_parse_from(["aida", "push", "--code-only", "--store-only"]).is_err());
    }

    /// Same four combinations for `aida pull`.
    #[test]
    fn pull_flag_combinations_parse() {
        let cli = Cli::try_parse_from(["aida", "pull"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Pull {
                code_only: false,
                store_only: false,
                ..
            }
        ));
        let cli = Cli::try_parse_from(["aida", "pull", "--code-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Pull {
                code_only: true,
                store_only: false,
                ..
            }
        ));
        let cli = Cli::try_parse_from(["aida", "pull", "--store-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Pull {
                code_only: false,
                store_only: true,
                ..
            }
        ));
        assert!(Cli::try_parse_from(["aida", "pull", "--code-only", "--store-only"]).is_err());
    }

    /// TASK-108: --dry-run and --json parse for both verbs and compose
    /// with the scope flags.
    #[test]
    fn dry_run_flags_parse() {
        let cli = Cli::try_parse_from(["aida", "push", "--dry-run"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Push {
                dry_run: true,
                json: false,
                ..
            }
        ));
        let cli = Cli::try_parse_from(["aida", "push", "--json", "--code-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Push {
                json: true,
                code_only: true,
                ..
            }
        ));
        let cli = Cli::try_parse_from(["aida", "pull", "--dry-run", "--store-only"]).unwrap();
        assert!(matches!(
            cli.command,
            Command::Pull {
                dry_run: true,
                store_only: true,
                ..
            }
        ));
        let cli = Cli::try_parse_from(["aida", "pull", "--json"]).unwrap();
        assert!(matches!(cli.command, Command::Pull { json: true, .. }));
    }
}

/// TASK-234 / TASK-241: integration coverage for the git-state
/// classifiers behind `aida queue list`'s "Done — awaiting merge"
/// section and `aida show`'s git-linkage section. Both extracted
/// helpers (`classify_in_flight_specs`, `collect_git_linkage`) are
/// gh-free — they only run `git` — so a temp repo with hand-built
/// commits exercises every branch without a GitHub round-trip.
/// trace:TASK-234 TASK-241 | ai:claude
#[cfg(test)]
mod in_flight_linkage_integration_tests {
    use super::*;

    fn git(repo: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(args)
            .output()
            .expect("git on PATH");
        assert!(
            out.status.success(),
            "git {:?} failed: {}",
            args,
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// A fresh repo on `main` with one initial commit.
    fn init_repo() -> (tempfile::TempDir, std::path::PathBuf) {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path().to_path_buf();
        git(&root, &["init", "--initial-branch=main", "--quiet"]);
        git(&root, &["config", "user.email", "t@example.com"]);
        git(&root, &["config", "user.name", "Test"]);
        std::fs::write(root.join("README.md"), "init\n").unwrap();
        git(&root, &["add", "."]);
        git(&root, &["commit", "-q", "-m", "chore: init"]);
        (tmp, root)
    }

    fn commit(root: &std::path::Path, file: &str, body: &str, subject: &str) {
        std::fs::write(root.join(file), body).unwrap();
        git(root, &["add", "."]);
        git(root, &["commit", "-q", "-m", subject]);
    }

    fn req(spec_id: &str) -> aida_core::Requirement {
        let mut r = aida_core::Requirement::new(format!("test {spec_id}"), String::new());
        r.spec_id = Some(spec_id.to_string());
        r
    }

    /// TASK-234: a mixed-state queue — one spec merged to main, one on a
    /// feature branch, one with no commit — buckets into stuck /
    /// awaiting / no_commit. Pure git, no gh.
    #[test]
    fn classify_buckets_mixed_state_queue() {
        let (_tmp, root) = init_repo();
        // STUCK: a commit on main referencing the spec.
        commit(&root, "a.txt", "x", "feat: stuck work (TASK-801) (#7)");
        // AWAITING: a commit on a feature branch, not merged to main.
        git(&root, &["checkout", "-q", "-b", "feature/x"]);
        commit(&root, "b.txt", "y", "feat: in-flight work (TASK-802)");
        git(&root, &["checkout", "-q", "main"]);

        let specs = [req("TASK-801"), req("TASK-802"), req("TASK-803")];
        let refs: Vec<&aida_core::Requirement> = specs.iter().collect();
        let b = classify_in_flight_specs(&refs, &root);

        assert_eq!(b.stuck.len(), 1, "one stuck spec");
        assert_eq!(b.stuck[0].0, "TASK-801");
        assert_eq!(b.stuck[0].1, Some(7), "squash PR parsed for the stuck spec");

        assert_eq!(
            b.awaiting.get("feature/x").map(|v| v.as_slice()),
            Some(&["TASK-802".to_string()][..])
        );

        assert_eq!(b.no_commit, vec!["TASK-803".to_string()]);
    }

    /// BUG-229: a Done spec whose referencing commit lives on BOTH the
    /// reviewer-worktree snapshot branch (`pr-71`, left by `git fetch
    /// origin pull/71/head:pr-71`) and the real PR-source branch
    /// (`task-282`). The classifier must bucket it under the real
    /// branch — picking the `pr-N` snapshot is what mis-rendered the row
    /// as "no PR opened yet" while the PR was under review.
    /// trace:BUG-229 | ai:claude
    #[test]
    fn classify_prefers_pr_source_branch_over_reviewer_snapshot() {
        let (_tmp, root) = init_repo();
        git(&root, &["checkout", "-q", "-b", "task-282"]);
        commit(&root, "feature.txt", "work", "feat: ship it (TASK-282)");
        // The reviewer snapshot branch points at the SAME commit.
        git(&root, &["branch", "pr-71"]);
        git(&root, &["checkout", "-q", "main"]);

        let specs = [req("TASK-282")];
        let refs: Vec<&aida_core::Requirement> = specs.iter().collect();
        let b = classify_in_flight_specs(&refs, &root);

        assert_eq!(
            b.awaiting.get("task-282").map(|v| v.as_slice()),
            Some(&["TASK-282".to_string()][..]),
            "bucketed under the real PR-source branch, not the pr-N snapshot"
        );
        assert!(
            !b.awaiting.contains_key("pr-71"),
            "the `pr-71` reviewer snapshot must not drive the bucket key"
        );
    }

    /// BUG-229: when the ONLY branch containing the commit is a `pr-N`
    /// reviewer snapshot (the real PR-source branch was pruned), the
    /// classifier falls back to it rather than losing the spec — a
    /// degraded but honest key, better than `(branch unknown)`.
    /// trace:BUG-229 | ai:claude
    #[test]
    fn classify_falls_back_to_pr_n_when_it_is_the_only_branch() {
        let (_tmp, root) = init_repo();
        git(&root, &["checkout", "-q", "-b", "pr-71"]);
        commit(&root, "snap.txt", "work", "feat: snapshot (TASK-283)");
        git(&root, &["checkout", "-q", "main"]);

        let specs = [req("TASK-283")];
        let refs: Vec<&aida_core::Requirement> = specs.iter().collect();
        let b = classify_in_flight_specs(&refs, &root);

        assert_eq!(
            b.awaiting.get("pr-71").map(|v| v.as_slice()),
            Some(&["TASK-283".to_string()][..]),
            "falls back to the pr-N branch when no real branch contains the commit"
        );
    }

    /// TASK-234: an empty queue yields three empty buckets — the
    /// no-Done-items path.
    #[test]
    fn classify_handles_no_done_items() {
        let (_tmp, root) = init_repo();
        let b = classify_in_flight_specs(&[], &root);
        assert!(b.stuck.is_empty() && b.awaiting.is_empty() && b.no_commit.is_empty());
    }

    /// TASK-241: a spec nothing references — no commits, no trace files.
    #[test]
    fn linkage_for_never_touched_spec_is_empty() {
        let (_tmp, root) = init_repo();
        let l = collect_git_linkage(&root, &["TASK-804".to_string()]);
        assert!(l.commits.is_empty(), "no commits reference the spec");
        assert!(l.files.is_empty(), "no trace files reference the spec");
        assert!(!l.shipped);
    }

    /// TASK-241: a shipped spec — commit on main + a squash `(#NN)`
    /// subject + a trace comment in a source file.
    #[test]
    fn linkage_for_shipped_spec() {
        let (_tmp, root) = init_repo();
        std::fs::write(root.join("touched.rs"), "// trace:TASK-805\nfn ship() {}\n").unwrap();
        commit(
            &root,
            "touched.rs",
            "// trace:TASK-805\nfn ship() {}\n",
            "feat: ship it (TASK-805) (#42)",
        );

        let l = collect_git_linkage(&root, &["TASK-805".to_string()]);
        assert_eq!(l.commits.len(), 1, "one referencing commit");
        assert!(l.shipped, "commit is an ancestor of main");
        assert_eq!(
            l.shipped_pr,
            Some(42),
            "PR number parsed from squash subject"
        );
        assert_eq!(l.files.len(), 1, "the trace comment was found");
        assert_eq!(l.files[0].0, "touched.rs");
    }

    /// TASK-241: an in-flight spec — commit on a feature branch, not on
    /// main; the feature branch is reported and `shipped` is false.
    #[test]
    fn linkage_for_in_flight_spec() {
        let (_tmp, root) = init_repo();
        git(&root, &["checkout", "-q", "-b", "feature/y"]);
        commit(&root, "c.txt", "z", "feat: flying (TASK-806)");
        git(&root, &["checkout", "-q", "main"]);

        let l = collect_git_linkage(&root, &["TASK-806".to_string()]);
        assert_eq!(l.commits.len(), 1);
        assert!(!l.shipped, "commit is not on main");
        assert_eq!(l.branch.as_deref(), Some("feature/y"));
    }

    /// A fresh repo with `--initial-branch=<name>` and one initial
    /// commit — used for the BUG-380 master-default coverage.
    fn init_repo_on(branch: &str) -> (tempfile::TempDir, std::path::PathBuf) {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path().to_path_buf();
        git(
            &root,
            &["init", &format!("--initial-branch={}", branch), "--quiet"],
        );
        git(&root, &["config", "user.email", "t@example.com"]);
        git(&root, &["config", "user.name", "Test"]);
        std::fs::write(root.join("README.md"), "init\n").unwrap();
        git(&root, &["add", "."]);
        git(&root, &["commit", "-q", "-m", "chore: init"]);
        (tmp, root)
    }

    /// BUG-380: a repo whose default branch is `master` (no `main`
    /// exists). The ancestor check must use `master`, not splice
    /// `fatal: Not a valid object name 'main'` to stderr — and the
    /// shipped commit must still be detected.
    #[test]
    fn linkage_for_shipped_spec_on_master_default_repo() {
        let (_tmp, root) = init_repo_on("master");
        commit(
            &root,
            "touched.rs",
            "// trace:BUG-380\nfn ship() {}\n",
            "fix: master default branch (BUG-380) (#380)",
        );

        let l = collect_git_linkage(&root, &["BUG-380".to_string()]);
        assert_eq!(l.commits.len(), 1, "one referencing commit");
        assert!(
            l.shipped,
            "commit on master should be shipped when master is the default branch"
        );
        assert_eq!(l.shipped_pr, Some(380));
    }

    /// BUG-380: regression — a `main`-default repo must keep working
    /// the way it did before the resolver landed.
    #[test]
    fn linkage_for_shipped_spec_on_main_default_repo_unchanged() {
        let (_tmp, root) = init_repo_on("main");
        commit(
            &root,
            "touched.rs",
            "// trace:BUG-380\nfn ship() {}\n",
            "fix: main default still works (BUG-380) (#381)",
        );

        let l = collect_git_linkage(&root, &["BUG-380".to_string()]);
        assert_eq!(l.commits.len(), 1);
        assert!(l.shipped);
        assert_eq!(l.shipped_pr, Some(381));
    }

    /// BUG-380: the resolver picks the master ref when only master
    /// exists, so the caller never passes a literal `"main"` to
    /// `git merge-base --is-ancestor`.
    #[test]
    fn resolve_default_branch_picks_master_when_main_absent() {
        let (_tmp, root) = init_repo_on("master");
        assert_eq!(resolve_default_branch_ref(&root).as_deref(), Some("master"));
    }

    /// BUG-380: the resolver picks `main` on a main-default repo.
    #[test]
    fn resolve_default_branch_picks_main_when_present() {
        let (_tmp, root) = init_repo_on("main");
        assert_eq!(resolve_default_branch_ref(&root).as_deref(), Some("main"));
    }
}

/// TASK-241: coverage for the squash-merge PR-number parser that
/// `aida show`'s git-linkage section uses to point shipped specs at
/// their merged PR. trace:TASK-241 | ai:claude
#[cfg(test)]
mod git_linkage_tests {
    use super::*;

    #[test]
    fn squash_merge_subject_yields_pr_number() {
        assert_eq!(
            parse_squash_pr_number("EPIC-24 batch:plan-tooling — plan lifecycle (7 specs) (#29)"),
            Some(29)
        );
        assert_eq!(parse_squash_pr_number("feat: thing (#1234)"), Some(1234));
        // Trailing whitespace is tolerated.
        assert_eq!(parse_squash_pr_number("fix: y (#7)  "), Some(7));
    }

    #[test]
    fn aida_format_subject_has_no_pr_number() {
        // The `(SPEC-ID)` AIDA commit format must NOT be mistaken for a
        // PR pointer — only `(#NN)` counts.
        assert_eq!(
            parse_squash_pr_number("[AI:claude] feat(cli): aida rebase (TASK-103)"),
            None
        );
        assert_eq!(parse_squash_pr_number("chore: bump deps"), None);
    }

    #[test]
    fn malformed_pr_suffix_is_rejected() {
        assert_eq!(parse_squash_pr_number("feat: x (#notanumber)"), None);
        assert_eq!(parse_squash_pr_number("feat: x (#12"), None);
        assert_eq!(parse_squash_pr_number(""), None);
    }
}

/// TASK-238: coverage for the queue-list tag surfacing — the inline
/// chip formatter and the `--by-batch` group key. trace:TASK-238
#[cfg(test)]
mod queue_tag_tests {
    use super::*;
    use std::collections::HashSet;

    fn tags(items: &[&str]) -> HashSet<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn no_tags_yields_no_chip() {
        assert_eq!(format_tag_chip(&HashSet::new()), None);
    }

    #[test]
    fn single_tag_chip() {
        assert_eq!(format_tag_chip(&tags(&["ux"])), Some("ux".to_string()));
    }

    #[test]
    fn multi_tag_chip_caps_plain_tags_and_keeps_all_batch() {
        // 1 batch tag + 5 plain → batch shown, 3 plain shown, "+2".
        let chip = format_tag_chip(&tags(&[
            "batch:display-polish",
            "ux",
            "queue",
            "tags",
            "visibility",
            "display",
        ]))
        .unwrap();
        assert!(
            chip.starts_with("batch:display-polish"),
            "batch tag first: {chip}"
        );
        assert!(chip.ends_with("+2"), "overflow marker: {chip}");
        // batch + 3 plain + overflow = 5 comma-separated segments.
        assert_eq!(chip.split(", ").count(), 5, "{chip}");
    }

    #[test]
    fn tag_chip_hoists_lifecycle_tags_after_batch_tags() {
        let chip = format_tag_chip(&tags(&[
            "ux",
            "lifecycle:no-review",
            "batch:overnight",
            "lifecycle:no-build",
        ]))
        .unwrap();
        assert_eq!(
            chip,
            "batch:overnight, lifecycle:no-build, lifecycle:no-review, ux"
        );
    }

    #[test]
    fn tag_chip_always_shows_lifecycle_tags_before_plain_overflow() {
        let chip = format_tag_chip(&tags(&["lifecycle:trivial", "a", "b", "c", "d", "e"])).unwrap();
        assert!(
            chip.starts_with("lifecycle:trivial"),
            "lifecycle tag first: {chip}"
        );
        assert!(chip.ends_with("+2"), "plain overflow marker: {chip}");
        assert_eq!(chip.split(", ").count(), 5, "{chip}");
    }

    #[test]
    fn batch_tag_of_finds_the_batch_tag() {
        assert_eq!(
            batch_tag_of(&tags(&["ux", "batch:plan-tooling", "queue"])),
            Some("batch:plan-tooling")
        );
        assert_eq!(batch_tag_of(&tags(&["ux", "queue"])), None);
        assert_eq!(batch_tag_of(&HashSet::new()), None);
    }

    #[test]
    fn tag_exact_match_is_case_insensitive() {
        let t = tags(&["batch:plan-tooling", "ux"]);
        assert!(tag_matches_exact(&t, "ux"));
        assert!(tag_matches_exact(&t, "UX"));
        assert!(tag_matches_exact(&t, "batch:plan-tooling"));
        // Exact, not substring: a prefix is not an exact match.
        assert!(!tag_matches_exact(&t, "batch:plan"));
        assert!(!tag_matches_exact(&t, "queue"));
        assert!(!tag_matches_exact(&HashSet::new(), "ux"));
    }

    #[test]
    fn tag_prefix_match_is_case_insensitive() {
        let t = tags(&["batch:plan-tooling", "ux"]);
        assert!(tag_matches_prefix(&t, "batch:"));
        assert!(tag_matches_prefix(&t, "BATCH:"));
        assert!(tag_matches_prefix(&t, "batch:plan"));
        assert!(tag_matches_prefix(&t, "u"));
        assert!(!tag_matches_prefix(&t, "integration:"));
        assert!(!tag_matches_prefix(&HashSet::new(), "batch:"));
    }
}

/// TASK-107: regression coverage for `aida fetch`. The behaviors we
/// pin: (1) code-leg fetch updates origin/<branch> without touching the
/// worktree, (2) cache-invalidation hook fires after the store leg
/// (best-effort, off the real `~/.aida` since `AIDA_HOME` overrides it
/// for tests), (3) `--code-only` / `--store-only` route correctly,
/// (4) the auto-bump does NOT fire on fetch — that's a pull-only
/// behavior. trace:TASK-107 | ai:claude
#[cfg(test)]
mod handle_fetch_command_tests {
    use super::*;

    fn run_git_in(repo: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(args)
            .output()
            .expect("git binary on PATH");
        if !out.status.success() {
            panic!(
                "git {:?} (in {:?}) failed: stdout={} stderr={}",
                args,
                repo,
                String::from_utf8_lossy(&out.stdout),
                String::from_utf8_lossy(&out.stderr)
            );
        }
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// Bare remote + a project clone with one initial commit. Mirrors the
    /// `handle_pull_command_tests::make_remote_and_clone` helper so tests
    /// stay symmetric across the pull/fetch pair.
    fn make_remote_and_clone() -> (
        tempfile::TempDir,
        tempfile::TempDir,
        std::path::PathBuf,
        std::path::PathBuf,
    ) {
        let bare_tmp = tempfile::TempDir::new().unwrap();
        let bare = bare_tmp.path().to_path_buf();
        run_git_in(
            &bare,
            &["init", "--bare", "--initial-branch=main", "--quiet"],
        );

        let seed_tmp = tempfile::TempDir::new().unwrap();
        let seed = seed_tmp.path().to_path_buf();
        run_git_in(
            &seed,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                seed.to_str().unwrap(),
            ],
        );
        run_git_in(&seed, &["config", "user.email", "test@example.com"]);
        run_git_in(&seed, &["config", "user.name", "Test"]);
        std::fs::write(seed.join("README.md"), "init\n").unwrap();
        run_git_in(&seed, &["add", "README.md"]);
        run_git_in(&seed, &["commit", "-m", "chore: init"]);
        run_git_in(&seed, &["push", "origin", "main", "--quiet"]);

        let proj_tmp = tempfile::TempDir::new().unwrap();
        let proj = proj_tmp.path().to_path_buf();
        run_git_in(
            &proj,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                proj.to_str().unwrap(),
            ],
        );
        run_git_in(&proj, &["config", "user.email", "test@example.com"]);
        run_git_in(&proj, &["config", "user.name", "Test"]);

        (bare_tmp, proj_tmp, bare, proj)
    }

    fn push_remote_commit(bare: &std::path::Path, msg: &str) -> String {
        let tmp = tempfile::TempDir::new().unwrap();
        let work = tmp.path().to_path_buf();
        run_git_in(
            &work,
            &[
                "clone",
                "--quiet",
                bare.to_str().unwrap(),
                work.to_str().unwrap(),
            ],
        );
        run_git_in(&work, &["config", "user.email", "test@example.com"]);
        run_git_in(&work, &["config", "user.name", "Test"]);
        std::fs::write(work.join("landed.txt"), msg).unwrap();
        run_git_in(&work, &["add", "landed.txt"]);
        run_git_in(&work, &["commit", "-m", msg]);
        run_git_in(&work, &["push", "origin", "main", "--quiet"]);
        run_git_in(&work, &["rev-parse", "HEAD"])
    }

    fn seed_done_spec_at(store_path: &std::path::Path, spec_id: &str) {
        let storage = Storage::new(store_path.to_path_buf());
        let mut store = storage.load().unwrap_or_default();
        let mut req = aida_core::Requirement::new(format!("test-{}", spec_id), String::new());
        req.spec_id = Some(spec_id.to_string());
        req.set_status_from_str("Done");
        store.requirements.push(req);
        storage.save(&store).unwrap();
    }

    /// `aida fetch --code-only` advances `origin/main` to the remote tip
    /// but does NOT advance the local working `main` (no merge, no
    /// rebase). The worktree file added in the remote commit must NOT
    /// appear in the local working tree.
    #[test]
    fn fetch_code_only_advances_origin_without_touching_worktree() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        Storage::new(store_path.clone())
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        let pre_origin = run_git_in(&project_root, &["rev-parse", "origin/main"]);
        let pre_local = run_git_in(&project_root, &["rev-parse", "HEAD"]);

        let new_sha = push_remote_commit(&bare, "feat: remote landed");

        // store_path doesn't exist as a worktree — store leg will skip
        // cleanly. code_only=true makes that skip the intended path.
        handle_fetch_command(&store_path, true, false, true).unwrap();

        let post_origin = run_git_in(&project_root, &["rev-parse", "origin/main"]);
        let post_local = run_git_in(&project_root, &["rev-parse", "HEAD"]);

        assert_eq!(
            post_origin, new_sha,
            "origin/main should advance after fetch"
        );
        assert_ne!(post_origin, pre_origin, "origin/main must have moved");
        assert_eq!(post_local, pre_local, "local HEAD must NOT move on fetch");
        assert!(
            !project_root.join("landed.txt").exists(),
            "fetch must not touch the worktree"
        );
    }

    /// `aida fetch` MUST NOT trigger the Done → Completed auto-bump.
    /// That's pull-only behavior — fetch is read-only. Regression guard
    /// against accidentally inheriting auto-bump from a shared helper.
    #[test]
    fn fetch_does_not_auto_bump() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        let storage = Storage::new(store_path.clone());
        storage
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        let spec_id = "STORY-9510".to_string();
        seed_done_spec_at(&store_path, &spec_id);
        push_remote_commit(&bare, &format!("feat: teammate work ({})", spec_id));

        handle_fetch_command(&store_path, true, false, true).unwrap();

        let after = storage.load().unwrap();
        let req = after.get_requirement_by_spec_id(&spec_id).unwrap();
        assert!(
            matches!(req.status, RequirementStatus::Done),
            "fetch must NOT auto-bump (that's pull's job), status was {:?}",
            req.status
        );
    }

    /// `aida fetch --store-only` skips the code leg even when there are
    /// new commits on origin/main. origin/main stays at its pre-fetch SHA.
    #[test]
    fn fetch_store_only_skips_code_leg() {
        let (_bare_tmp, _proj_tmp, bare, project_root) = make_remote_and_clone();
        let store_path = project_root.join("requirements.yaml");
        Storage::new(store_path.clone())
            .save(&aida_core::RequirementsStore::default())
            .unwrap();

        let pre_origin = run_git_in(&project_root, &["rev-parse", "origin/main"]);
        push_remote_commit(&bare, "feat: new on remote");

        // store_only=true → code leg skipped entirely.
        handle_fetch_command(&store_path, false, true, true).unwrap();

        let post_origin = run_git_in(&project_root, &["rev-parse", "origin/main"]);
        assert_eq!(
            pre_origin, post_origin,
            "--store-only must NOT fetch the code leg"
        );
    }
}

#[cfg(test)]
mod derive_parent_epic_label_tests {
    use super::*;
    use aida_core::{Relationship, Requirement, RequirementType, RequirementsStore};
    use uuid::Uuid;

    /// Build a Requirement via the canonical `::new()` constructor and
    /// patch the fields the helper inspects: spec_id, agreed_id, type.
    fn req(spec_id: &str, agreed: Option<&str>, t: RequirementType) -> Requirement {
        let mut r = Requirement::new(spec_id.to_string(), String::new());
        r.spec_id = Some(spec_id.into());
        r.agreed_id = agreed.map(String::from);
        r.req_type = t;
        r
    }

    fn rel(target: Uuid, t: RelationshipType) -> Relationship {
        Relationship {
            rel_type: t,
            target_id: target,
            created_at: Some(chrono::Utc::now()),
            created_by: Some("t".into()),
        }
    }

    /// Child edge into an Epic → derives that Epic's spec_id.
    /// trace:TASK-44 | ai:claude
    #[test]
    fn child_into_epic_derives_label() {
        let epic = req("EPIC-20", None, RequirementType::Epic);
        let mut task = req("TASK-44", None, RequirementType::Task);
        task.relationships
            .push(rel(epic.id, RelationshipType::Child));
        let store = RequirementsStore {
            requirements: vec![epic, task.clone()],
            ..Default::default()
        };
        assert_eq!(
            derive_parent_epic_label(&task, &store),
            Some("EPIC-20".to_string())
        );
    }

    /// Child edge into a non-Epic (Story) → None.
    #[test]
    fn child_into_non_epic_returns_none() {
        let story = req("STORY-9", None, RequirementType::Story);
        let mut task = req("TASK-44", None, RequirementType::Task);
        task.relationships
            .push(rel(story.id, RelationshipType::Child));
        let store = RequirementsStore {
            requirements: vec![story, task.clone()],
            ..Default::default()
        };
        assert_eq!(derive_parent_epic_label(&task, &store), None);
    }

    /// No relationships → None (the orphan-TASK case).
    #[test]
    fn no_relationships_returns_none() {
        let task = req("TASK-42", None, RequirementType::Task);
        let store = RequirementsStore {
            requirements: vec![task.clone()],
            ..Default::default()
        };
        assert_eq!(derive_parent_epic_label(&task, &store), None);
    }

    /// Parent edge (the inverse direction) is NOT what we want — a Parent
    /// rel on `req` means `req` is the parent of something else. We
    /// only derive from Child edges. trace:TASK-44 | ai:claude
    #[test]
    fn parent_edge_does_not_derive() {
        let epic = req("EPIC-20", None, RequirementType::Epic);
        let mut task = req("TASK-44", None, RequirementType::Task);
        // Wrong direction: TASK has a Parent edge pointing at EPIC
        // (semantically: TASK is parent of EPIC — nonsense, but the
        // helper shouldn't be fooled by it).
        task.relationships
            .push(rel(epic.id, RelationshipType::Parent));
        let store = RequirementsStore {
            requirements: vec![epic, task.clone()],
            ..Default::default()
        };
        assert_eq!(derive_parent_epic_label(&task, &store), None);
    }

    /// Dangling target (parent UUID not in store) → None, no panic.
    #[test]
    fn dangling_target_returns_none() {
        let mut task = req("TASK-44", None, RequirementType::Task);
        task.relationships
            .push(rel(Uuid::now_v7(), RelationshipType::Child));
        let store = RequirementsStore {
            requirements: vec![task.clone()],
            ..Default::default()
        };
        assert_eq!(derive_parent_epic_label(&task, &store), None);
    }

    /// agreed_id wins over spec_id when both are present — the
    /// merge-gate-canonical short form is what users recognize.
    #[test]
    fn prefers_agreed_id_over_spec_id() {
        let epic = req("EPIC-7-001", Some("EPIC-20"), RequirementType::Epic);
        let mut task = req("TASK-44", None, RequirementType::Task);
        task.relationships
            .push(rel(epic.id, RelationshipType::Child));
        let store = RequirementsStore {
            requirements: vec![epic, task.clone()],
            ..Default::default()
        };
        assert_eq!(
            derive_parent_epic_label(&task, &store),
            Some("EPIC-20".to_string())
        );
    }

    /// Multiple Child edges, only one of which points to an Epic → that
    /// one wins. Order is "first match" so a stable ordering isn't
    /// guaranteed for multi-Epic cases (uncommon).
    #[test]
    fn mixed_child_edges_picks_epic() {
        let epic = req("EPIC-20", None, RequirementType::Epic);
        let story = req("STORY-9", None, RequirementType::Story);
        let mut task = req("TASK-44", None, RequirementType::Task);
        task.relationships
            .push(rel(story.id, RelationshipType::Child));
        task.relationships
            .push(rel(epic.id, RelationshipType::Child));
        let store = RequirementsStore {
            requirements: vec![epic, story, task.clone()],
            ..Default::default()
        };
        assert_eq!(
            derive_parent_epic_label(&task, &store),
            Some("EPIC-20".to_string())
        );
    }
}

#[cfg(test)]
mod format_review_story_display_tests {
    use super::*;

    /// TASK-91: a synthetic `Review PR-15: ...` title produces a
    /// PR-prominent display tuple, with the STORY-NNN as parenthetical.
    #[test]
    fn rewrites_synthetic_review_story_title() {
        let result =
            format_review_story_display("STORY-108", "Review PR-15: EPIC-23 batch wrap-up");
        assert_eq!(
            result,
            Some((
                "PR-15 (STORY-108)".to_string(),
                "EPIC-23 batch wrap-up".to_string()
            ))
        );
    }

    /// agreed_id wins over spec_id at the call site; this helper is
    /// id-agnostic — whatever display id the caller passes ends up in
    /// the parenthetical.
    #[test]
    fn passes_through_agreed_id_when_present() {
        let result = format_review_story_display("STORY-7", "Review PR-2: tiny fix");
        assert_eq!(
            result,
            Some(("PR-2 (STORY-7)".to_string(), "tiny fix".to_string()))
        );
    }

    /// Non-review titles return None so the caller falls back to the
    /// untransformed (display_id, title) pair.
    #[test]
    fn returns_none_for_non_review_title() {
        assert_eq!(
            format_review_story_display("STORY-50", "Add OAuth provider"),
            None
        );
    }

    /// Defensive: `Review PR-` followed by non-digits isn't the
    /// auto-queue pattern; don't claim it.
    #[test]
    fn returns_none_when_pr_number_not_digits() {
        assert_eq!(
            format_review_story_display("STORY-99", "Review PR-abc: malformed title"),
            None
        );
    }

    /// A title that mentions PR-N but doesn't use the auto-queue
    /// prefix shouldn't be rewritten.
    #[test]
    fn returns_none_for_partial_match() {
        assert_eq!(
            format_review_story_display("STORY-99", "Reviewer should look at PR-7 carefully"),
            None
        );
    }

    /// Edge case: empty after-colon (theoretical — auto-queue always
    /// includes a title). Should still produce a tuple, just with an
    /// empty trimmed-title.
    #[test]
    fn handles_empty_title_after_colon() {
        let result = format_review_story_display("STORY-1", "Review PR-99:");
        assert_eq!(result, Some(("PR-99 (STORY-1)".to_string(), String::new())));
    }

    /// BUG-91: the `Review PR-` prefix matches case-insensitively (aligning
    /// with the case-insensitive `review_title_matches` router), and the
    /// after-colon title keeps its original case.
    #[test]
    fn matches_review_prefix_case_insensitively() {
        let result = format_review_story_display("STORY-15", "review pr-15: Foo Bar");
        assert_eq!(
            result,
            Some(("PR-15 (STORY-15)".to_string(), "Foo Bar".to_string()))
        );
        let result = format_review_story_display("STORY-3", "REVIEW PR-3: keep CASE");
        assert_eq!(
            result,
            Some(("PR-3 (STORY-3)".to_string(), "keep CASE".to_string()))
        );
    }
}

#[cfg(test)]
mod auto_branch_tests {
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    fn init_repo() -> TempDir {
        let tmp = TempDir::new().unwrap();
        Command::new("git")
            .arg("-C")
            .arg(tmp.path())
            .args(["init", "--initial-branch=main", "--quiet"])
            .status()
            .unwrap();
        // Need at least one commit so subsequent branch creates work.
        Command::new("git")
            .arg("-C")
            .arg(tmp.path())
            .args(["commit", "--allow-empty", "-m", "init", "--quiet"])
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .status()
            .unwrap();
        tmp
    }

    fn create_branch(repo: &std::path::Path, name: &str) {
        Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(["branch", name])
            .status()
            .unwrap();
    }

    /// First call returns the slug as-is. trace:STORY-65 | ai:claude
    #[test]
    fn auto_branch_slug_when_free() {
        let tmp = init_repo();
        let got = resolve_session_branch(tmp.path(), "epic-20", "auto").unwrap();
        assert_eq!(got, "epic-20");
    }

    /// Slug taken → `-2`. trace:STORY-65 | ai:claude
    #[test]
    fn auto_branch_appends_2_on_first_collision() {
        let tmp = init_repo();
        create_branch(tmp.path(), "epic-20");
        let got = resolve_session_branch(tmp.path(), "epic-20", "auto").unwrap();
        assert_eq!(got, "epic-20-2");
    }

    /// Slug + slug-2..-10 all taken → falls through to dated form.
    /// trace:STORY-65 | ai:claude
    #[test]
    fn auto_branch_falls_back_to_dated_form() {
        let tmp = init_repo();
        create_branch(tmp.path(), "epic-20");
        for n in 2..=10 {
            create_branch(tmp.path(), &format!("epic-20-{}", n));
        }
        let got = resolve_session_branch(tmp.path(), "epic-20", "auto").unwrap();
        let today = chrono::Local::now().format("%Y-%m-%d").to_string();
        assert_eq!(got, format!("epic-20-{}", today));
    }

    /// `--branch-style date` skips the slug attempt and goes straight to
    /// the dated form. trace:STORY-65 | ai:claude
    #[test]
    fn date_branch_style_uses_date_form_even_when_slug_free() {
        let tmp = init_repo();
        let got = resolve_session_branch(tmp.path(), "epic-20", "date").unwrap();
        let today = chrono::Local::now().format("%Y-%m-%d").to_string();
        assert_eq!(got, format!("epic-20-{}", today));
    }

    /// Unknown style errors clearly. trace:STORY-65 | ai:claude
    #[test]
    fn unknown_branch_style_errors() {
        let tmp = init_repo();
        let err = resolve_session_branch(tmp.path(), "epic-20", "wat").unwrap_err();
        assert!(err.to_string().contains("unknown --branch-style"));
    }
}

#[cfg(test)]
mod worktree_dirty_entries_tests {
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    /// Init a real git repo with one commit and a `.gitignore` that
    /// excludes `target/` and `.aida/cache.db` — the two canonical
    /// "disposable" patterns from BUG-67's acceptance.
    fn init_repo_with_gitignore() -> TempDir {
        let tmp = TempDir::new().unwrap();
        let p = tmp.path();
        Command::new("git")
            .arg("-C")
            .arg(p)
            .args(["init", "--initial-branch=main", "--quiet"])
            .status()
            .unwrap();
        std::fs::write(p.join(".gitignore"), "target/\n.aida/cache.db\n").unwrap();
        Command::new("git")
            .arg("-C")
            .arg(p)
            .args(["add", ".gitignore"])
            .status()
            .unwrap();
        Command::new("git")
            .arg("-C")
            .arg(p)
            .args(["commit", "-m", "init", "--quiet"])
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .status()
            .unwrap();
        tmp
    }

    /// Clean worktree → empty vec. trace:BUG-67 | ai:claude
    #[test]
    fn clean_worktree_is_clean() {
        let tmp = init_repo_with_gitignore();
        assert!(worktree_dirty_entries(tmp.path()).is_empty());
    }

    /// Build artifacts under `target/` are gitignored → no entries.
    /// This is the headline case from BUG-67: every reviewer session
    /// builds with cargo before reviewing. trace:BUG-67 | ai:claude
    #[test]
    fn gitignored_target_dir_is_clean() {
        let tmp = init_repo_with_gitignore();
        std::fs::create_dir_all(tmp.path().join("target/release")).unwrap();
        std::fs::write(tmp.path().join("target/release/aida"), b"binary").unwrap();
        assert!(worktree_dirty_entries(tmp.path()).is_empty());
    }

    /// `.aida/cache.db` is gitignored → no entries. trace:BUG-67 | ai:claude
    #[test]
    fn gitignored_cache_db_is_clean() {
        let tmp = init_repo_with_gitignore();
        std::fs::create_dir_all(tmp.path().join(".aida")).unwrap();
        std::fs::write(tmp.path().join(".aida/cache.db"), b"sqlite").unwrap();
        assert!(worktree_dirty_entries(tmp.path()).is_empty());
    }

    /// A modified tracked file shows up. trace:BUG-67 | ai:claude
    #[test]
    fn tracked_modified_file_is_dirty() {
        let tmp = init_repo_with_gitignore();
        // Modify the tracked .gitignore so it shows as "M".
        std::fs::write(
            tmp.path().join(".gitignore"),
            "target/\n.aida/cache.db\n# touched\n",
        )
        .unwrap();
        let entries = worktree_dirty_entries(tmp.path());
        assert_eq!(entries.len(), 1, "{:?}", entries);
        assert!(entries[0].contains(".gitignore"), "{:?}", entries);
    }

    /// Untracked-but-not-ignored file shows up. trace:BUG-67 | ai:claude
    #[test]
    fn untracked_unignored_file_is_dirty() {
        let tmp = init_repo_with_gitignore();
        std::fs::write(tmp.path().join("scratch.rs"), b"// notes").unwrap();
        let entries = worktree_dirty_entries(tmp.path());
        assert_eq!(entries.len(), 1, "{:?}", entries);
        assert!(entries[0].contains("scratch.rs"), "{:?}", entries);
    }

    /// Mix: gitignored build output is hidden, real changes show.
    /// trace:BUG-67 | ai:claude
    #[test]
    fn mixed_only_real_changes_show() {
        let tmp = init_repo_with_gitignore();
        std::fs::create_dir_all(tmp.path().join("target")).unwrap();
        std::fs::write(tmp.path().join("target/foo"), b"x").unwrap();
        std::fs::write(tmp.path().join("scratch.rs"), b"// notes").unwrap();
        let entries = worktree_dirty_entries(tmp.path());
        assert_eq!(entries.len(), 1, "{:?}", entries);
        assert!(entries[0].contains("scratch.rs"), "{:?}", entries);
        assert!(
            !entries.iter().any(|e| e.contains("target")),
            "{:?}",
            entries
        );
    }

    /// Non-git path → empty vec (git errors, we treat as clean and let
    /// the downstream remove --force produce the real error).
    /// trace:BUG-67 | ai:claude
    #[test]
    fn non_git_path_is_clean() {
        let tmp = TempDir::new().unwrap();
        assert!(worktree_dirty_entries(tmp.path()).is_empty());
    }
}

#[cfg(test)]
mod add_aida_gitignore_entries_tests {
    use super::*;
    use tempfile::TempDir;

    /// Fresh project (no .gitignore) → file is created with both blocks.
    /// Returns Ok(false) per the contract (a brand-new file isn't an
    /// "update"). trace:BUG-73 | ai:claude
    #[test]
    fn creates_gitignore_with_both_blocks() {
        let tmp = TempDir::new().unwrap();
        let updated = add_aida_gitignore_entries(tmp.path(), ".aida-store").unwrap();
        assert!(!updated, "creation isn't an update");
        let content = std::fs::read_to_string(tmp.path().join(".gitignore")).unwrap();
        assert!(content.contains(".aida-store/"), "{}", content);
        assert!(has_aida_runtime_deny_pattern(&content), "{}", content);
        assert!(content.contains("!.aida/config.toml"), "{}", content);
    }

    /// Existing .gitignore that already covers ALL five blocks (store,
    /// runtime, CLAUDE.local.md, rules/aida-specs/, docs/plans/_draft/) → no
    /// write, returns Ok(false). The third block (CLAUDE.local.md) was added in
    /// commit bf50e7c0 for TASK-572. The fourth (.claude/rules/aida-specs/) was
    /// added by SPIKE-31. The fifth (docs/plans/_draft/) by TASK-383.
    /// trace:BUG-73 trace:TASK-572 trace:SPIKE-31 trace:TASK-383 | ai:claude
    #[test]
    fn idempotent_when_both_blocks_present() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join(".gitignore");
        let original = "target/\n.aida-store/\n.aida/*\n!.aida/config.toml\nCLAUDE.local.md\n.claude/rules/aida-specs/\ndocs/plans/_draft/\n";
        std::fs::write(&path, original).unwrap();
        let updated = add_aida_gitignore_entries(tmp.path(), ".aida-store").unwrap();
        assert!(
            !updated,
            "all five blocks already present → expected no append"
        );
        let content = std::fs::read_to_string(&path).unwrap();
        assert_eq!(content, original);
    }

    /// Legacy .gitignore (has `.aida-store/` but pre-BUG-73 per-file ignores)
    /// → the deny block is appended; the old per-file lines are left in place
    /// (harmless but redundant). Migration path for existing projects.
    /// trace:BUG-73 | ai:claude
    #[test]
    fn appends_deny_block_when_only_legacy_per_file_entries() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join(".gitignore");
        std::fs::write(
            &path,
            "target/\n.aida-store/\n.aida/session-env.sh\n.aida/sessions/\n",
        )
        .unwrap();
        let updated = add_aida_gitignore_entries(tmp.path(), ".aida-store").unwrap();
        assert!(updated, "deny block missing → expected an append");
        let content = std::fs::read_to_string(&path).unwrap();
        assert!(has_aida_runtime_deny_pattern(&content));
        assert!(content.contains("!.aida/config.toml"));
        // Legacy entries preserved
        assert!(content.starts_with("target/\n.aida-store/\n.aida/session-env.sh\n"));
    }

    /// .gitignore exists but no AIDA blocks → both get appended.
    /// trace:BUG-73 | ai:claude
    #[test]
    fn appends_both_when_neither_present() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join(".gitignore");
        std::fs::write(&path, "target/\n").unwrap();
        let updated = add_aida_gitignore_entries(tmp.path(), ".aida-store").unwrap();
        assert!(updated);
        let content = std::fs::read_to_string(&path).unwrap();
        assert!(content.contains(".aida-store/"));
        assert!(has_aida_runtime_deny_pattern(&content));
        assert!(content.contains("!.aida/config.toml"));
    }

    /// Detection helper: matches a bare `.aida/*` line, ignores comments
    /// that mention the string, ignores leading/trailing whitespace.
    /// trace:BUG-73 | ai:claude
    #[test]
    fn deny_pattern_detection() {
        assert!(has_aida_runtime_deny_pattern(".aida/*\n"));
        assert!(has_aida_runtime_deny_pattern("foo\n  .aida/*  \nbar\n"));
        assert!(!has_aida_runtime_deny_pattern("# .aida/* is a comment\n"));
        assert!(!has_aida_runtime_deny_pattern(".aida/session-env.sh\n"));
        assert!(!has_aida_runtime_deny_pattern(""));
    }
}

#[cfg(test)]
mod recent_files_for_branch_tests {
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    /// Init a git repo on `branch_name` with `files` committed across N
    /// commits (one commit per file). trace:TASK-53 | ai:claude
    fn init_repo_with_files(branch_name: &str, files: &[&str]) -> TempDir {
        let tmp = TempDir::new().unwrap();
        let p = tmp.path();
        let run = |args: &[&str]| {
            Command::new("git")
                .arg("-C")
                .arg(p)
                .args(args)
                .env("GIT_AUTHOR_NAME", "t")
                .env("GIT_AUTHOR_EMAIL", "t@t")
                .env("GIT_COMMITTER_NAME", "t")
                .env("GIT_COMMITTER_EMAIL", "t@t")
                .status()
                .unwrap();
        };
        run(&[
            "init",
            &format!("--initial-branch={}", branch_name),
            "--quiet",
        ]);
        for (i, f) in files.iter().enumerate() {
            // Create the file (with subdirs if needed) and commit it.
            let path = p.join(f);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent).unwrap();
            }
            std::fs::write(&path, format!("v{}", i)).unwrap();
            run(&["add", f]);
            run(&["commit", "-m", &format!("commit {}: {}", i, f), "--quiet"]);
        }
        tmp
    }

    /// Branch with recent commits → returns the touched files (deduped,
    /// sorted by BTreeSet ordering). trace:TASK-53 | ai:claude
    #[test]
    fn returns_committed_files() {
        let tmp = init_repo_with_files("feat-x", &["a.rs", "b.rs", "c.rs"]);
        let files = recent_files_for_branch(tmp.path(), "feat-x", "14 days ago", 10);
        assert_eq!(files, vec!["a.rs", "b.rs", "c.rs"]);
    }

    /// Max cap respected — a busy branch only surfaces the first N
    /// unique files so the warning stays scannable.
    #[test]
    fn respects_max_cap() {
        let many = ["a.rs", "b.rs", "c.rs", "d.rs", "e.rs", "f.rs"];
        let tmp = init_repo_with_files("feat-x", &many);
        let files = recent_files_for_branch(tmp.path(), "feat-x", "14 days ago", 3);
        assert_eq!(files.len(), 3);
    }

    /// Same file touched in multiple commits → deduped.
    #[test]
    fn dedupes_repeated_files() {
        let tmp = init_repo_with_files("feat-x", &["a.rs", "a.rs", "b.rs"]);
        let files = recent_files_for_branch(tmp.path(), "feat-x", "14 days ago", 10);
        assert_eq!(files, vec!["a.rs", "b.rs"]);
    }

    /// Unknown branch → empty vec (git errors, we treat as no signal).
    #[test]
    fn unknown_branch_returns_empty() {
        let tmp = init_repo_with_files("feat-x", &["a.rs"]);
        let files = recent_files_for_branch(tmp.path(), "ghost-branch", "14 days ago", 10);
        assert!(files.is_empty());
    }

    /// Non-git path → empty vec.
    #[test]
    fn non_git_path_returns_empty() {
        let tmp = TempDir::new().unwrap();
        let files = recent_files_for_branch(tmp.path(), "main", "14 days ago", 10);
        assert!(files.is_empty());
    }
}

#[cfg(test)]
mod branch_behind_main_tests {
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    /// Init a repo with `main` and a feature branch in one of three
    /// configurations: behind / ahead / diverged / equal.
    fn fixture(feat_ahead: u32, main_ahead: u32) -> (TempDir, &'static str) {
        let tmp = TempDir::new().unwrap();
        let p = tmp.path();
        let run = |args: &[&str]| {
            let r = Command::new("git")
                .arg("-C")
                .arg(p)
                .args(args)
                .env("GIT_AUTHOR_NAME", "t")
                .env("GIT_AUTHOR_EMAIL", "t@t")
                .env("GIT_COMMITTER_NAME", "t")
                .env("GIT_COMMITTER_EMAIL", "t@t")
                .output()
                .unwrap();
            assert!(
                r.status.success(),
                "git {:?} failed: {}",
                args,
                String::from_utf8_lossy(&r.stderr)
            );
        };
        run(&["init", "--initial-branch=main", "--quiet"]);
        run(&["commit", "--allow-empty", "-m", "root", "--quiet"]);
        run(&["checkout", "-q", "-b", "feat-x"]);
        for i in 0..feat_ahead {
            run(&[
                "commit",
                "--allow-empty",
                "-m",
                &format!("feat{}", i),
                "--quiet",
            ]);
        }
        run(&["checkout", "-q", "main"]);
        for i in 0..main_ahead {
            run(&[
                "commit",
                "--allow-empty",
                "-m",
                &format!("main{}", i),
                "--quiet",
            ]);
        }
        run(&["checkout", "-q", "feat-x"]);
        (tmp, "feat-x")
    }

    /// Feature branch equal-to main → None (no rebase needed).
    #[test]
    fn equal_to_main_returns_none() {
        let (tmp, branch) = fixture(0, 0);
        assert!(branch_behind_main(tmp.path(), branch).is_none());
    }

    /// Feature strictly ahead → None (push, don't rebase).
    #[test]
    fn ahead_of_main_returns_none() {
        let (tmp, branch) = fixture(3, 0);
        assert!(branch_behind_main(tmp.path(), branch).is_none());
    }

    /// Feature behind main → Some(count, samples).
    #[test]
    fn behind_main_returns_count() {
        let (tmp, branch) = fixture(0, 2);
        let result = branch_behind_main(tmp.path(), branch);
        assert!(result.is_some());
        let (count, sample) = result.unwrap();
        assert_eq!(count, 2);
        assert_eq!(sample.len(), 2);
    }

    /// Diverged (both ahead) → Some — origin still has stuff we don't.
    #[test]
    fn diverged_returns_count() {
        let (tmp, branch) = fixture(1, 3);
        let result = branch_behind_main(tmp.path(), branch);
        assert!(result.is_some());
        assert_eq!(result.unwrap().0, 3);
    }

    /// On main itself → None (nothing to rebase onto).
    #[test]
    fn on_main_returns_none() {
        let (tmp, _) = fixture(0, 1);
        assert!(branch_behind_main(tmp.path(), "main").is_none());
    }

    /// No `main` branch at all → None.
    #[test]
    fn missing_main_returns_none() {
        let tmp = TempDir::new().unwrap();
        let p = tmp.path();
        Command::new("git")
            .arg("-C")
            .arg(p)
            .args(["init", "--initial-branch=trunk", "--quiet"])
            .status()
            .unwrap();
        Command::new("git")
            .arg("-C")
            .arg(p)
            .args(["commit", "--allow-empty", "-m", "x", "--quiet"])
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .status()
            .unwrap();
        assert!(branch_behind_main(p, "trunk").is_none());
    }
}

#[cfg(all(test, unix))]
mod resolve_gh_binary_tests {
    use super::*;
    use std::os::unix::fs::PermissionsExt;
    use std::sync::Mutex;
    use tempfile::TempDir;

    // Serialize PATH-mutating tests against each other. Prepending (vs
    // replacing) PATH means other parallel tests keep finding `git` and
    // friends, but two concurrent PATH mutators still need to serialize
    // so they don't restore the wrong predecessor value. trace:BUG-79
    static PATH_LOCK: Mutex<()> = Mutex::new(());

    /// Acquire the PATH lock and prepend `dir` to PATH for the test's
    /// duration. Returns an RAII guard that restores PATH on drop.
    /// Prepending (instead of overwriting) keeps system `git` reachable
    /// from any parallel test that spawns subprocesses.
    fn scoped_prepend_path(dir: &std::path::Path) -> impl Drop {
        struct G {
            _lock: std::sync::MutexGuard<'static, ()>,
            prev: Option<String>,
        }
        impl Drop for G {
            fn drop(&mut self) {
                match &self.prev {
                    Some(v) => std::env::set_var("PATH", v),
                    None => std::env::remove_var("PATH"),
                }
            }
        }
        let lock = PATH_LOCK.lock().unwrap_or_else(|p| p.into_inner());
        let prev = std::env::var("PATH").ok();
        let new = match &prev {
            Some(v) => format!("{}:{}", dir.display(), v),
            None => format!("{}", dir.display()),
        };
        std::env::set_var("PATH", &new);
        G { _lock: lock, prev }
    }

    fn make_executable(path: &std::path::Path) {
        std::fs::write(path, "#!/bin/sh\necho gh fake\n").unwrap();
        let mut perms = std::fs::metadata(path).unwrap().permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(path, perms).unwrap();
    }

    fn make_non_executable(path: &std::path::Path) {
        std::fs::write(path, "not executable\n").unwrap();
        let mut perms = std::fs::metadata(path).unwrap().permissions();
        perms.set_mode(0o644);
        std::fs::set_permissions(path, perms).unwrap();
    }

    /// PATH walk picks up gh even when the system gh isn't on PATH.
    /// Critical regression guard for BUG-74. trace:BUG-74 | ai:claude
    #[test]
    fn finds_gh_via_path() {
        let tmp = TempDir::new().unwrap();
        let gh = tmp.path().join("gh");
        make_executable(&gh);
        let _g = scoped_prepend_path(tmp.path());
        let resolved = resolve_gh_binary().expect("expected to find fake gh on PATH");
        assert_eq!(
            std::fs::canonicalize(&resolved).unwrap(),
            std::fs::canonicalize(&gh).unwrap()
        );
    }

    /// PATH walk ignores non-executable files named gh. trace:BUG-74
    #[test]
    fn rejects_non_executable() {
        let tmp = TempDir::new().unwrap();
        let gh = tmp.path().join("gh");
        make_non_executable(&gh);
        let _g = scoped_prepend_path(tmp.path());
        let resolved = resolve_gh_binary();
        drop(_g);
        // We may still pick up a real system gh via the absolute-path
        // fallback — but we should NOT have picked up our broken fake.
        if let Some(p) = resolved {
            assert_ne!(
                std::fs::canonicalize(&p).unwrap(),
                std::fs::canonicalize(&gh).unwrap()
            );
        }
    }

    #[test]
    fn is_executable_checks_perm_bit() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join("x");
        make_executable(&path);
        assert!(is_executable(&path));
        make_non_executable(&path);
        assert!(!is_executable(&path));
    }

    #[test]
    fn is_executable_rejects_dirs() {
        let tmp = TempDir::new().unwrap();
        assert!(!is_executable(tmp.path()));
    }

    #[test]
    fn is_executable_rejects_missing() {
        let tmp = TempDir::new().unwrap();
        assert!(!is_executable(&tmp.path().join("nope")));
    }

    /// BUG-79: a file that passes is_executable but whose spawn fails
    /// (broken interpreter line) is not returned — we fall back to the
    /// next candidate or return None. trace:BUG-79 | ai:claude
    #[test]
    fn rejects_is_executable_but_spawn_fails() {
        let tmp = TempDir::new().unwrap();
        let bad = tmp.path().join("gh");
        // Shebang points at a non-existent interpreter, so spawn errors
        // with ENOENT even though is_executable returns true.
        std::fs::write(
            &bad,
            "#!/this/interpreter/does/not/exist\necho should never run\n",
        )
        .unwrap();
        let mut perms = std::fs::metadata(&bad).unwrap().permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(&bad, perms).unwrap();
        assert!(is_executable(&bad));

        let _g = scoped_prepend_path(tmp.path());
        let resolved = resolve_gh_binary();
        drop(_g);
        // Either None (no other gh) or some other path — never the broken one.
        if let Some(p) = resolved {
            assert_ne!(
                std::fs::canonicalize(&p).unwrap(),
                std::fs::canonicalize(&bad).unwrap()
            );
        }
    }

    /// BUG-79: when PATH has a broken candidate followed by a working one,
    /// the working one wins. trace:BUG-79 | ai:claude
    #[test]
    fn falls_back_past_broken_to_working() {
        let broken_dir = TempDir::new().unwrap();
        let good_dir = TempDir::new().unwrap();

        let broken = broken_dir.path().join("gh");
        std::fs::write(&broken, "#!/this/does/not/exist\n").unwrap();
        let mut p = std::fs::metadata(&broken).unwrap().permissions();
        p.set_mode(0o755);
        std::fs::set_permissions(&broken, p).unwrap();

        let good = good_dir.path().join("gh");
        make_executable(&good);

        // Prepend BOTH dirs so the broken one is hit first, then the good
        // one. Order matters: broken_dir wins on lookup order.
        let combined = std::path::PathBuf::from(format!(
            "{}:{}",
            broken_dir.path().display(),
            good_dir.path().display()
        ));
        let _g = scoped_prepend_path(&combined);
        let resolved = resolve_gh_binary().expect("should fall back to the working gh");
        drop(_g);
        assert_eq!(
            std::fs::canonicalize(&resolved).unwrap(),
            std::fs::canonicalize(&good).unwrap()
        );
    }
}

#[cfg(test)]
mod session_root_resolution_tests {
    //! trace:BUG-75 BUG-76 | ai:claude
    use super::*;
    use std::process::Command;
    use tempfile::TempDir;

    fn git(p: &std::path::Path, args: &[&str]) {
        let o = Command::new("git")
            .arg("-C")
            .arg(p)
            .args(args)
            .env("GIT_AUTHOR_NAME", "t")
            .env("GIT_AUTHOR_EMAIL", "t@t")
            .env("GIT_COMMITTER_NAME", "t")
            .env("GIT_COMMITTER_EMAIL", "t@t")
            .output()
            .unwrap();
        assert!(o.status.success(), "git {:?} failed", args);
    }

    fn fixture_with_linked_worktree() -> (TempDir, std::path::PathBuf, std::path::PathBuf) {
        let tmp = TempDir::new().unwrap();
        let main = tmp.path().join("repo");
        std::fs::create_dir_all(&main).unwrap();
        git(&main, &["init", "--initial-branch=main", "--quiet"]);
        std::fs::write(main.join("a.txt"), "x").unwrap();
        git(&main, &["add", "a.txt"]);
        git(&main, &["commit", "-m", "base", "--quiet"]);
        git(&main, &["checkout", "-b", "feature", "--quiet"]);
        std::fs::write(main.join("a.txt"), "y").unwrap();
        git(&main, &["add", "a.txt"]);
        git(&main, &["commit", "-m", "feature", "--quiet"]);
        git(&main, &["checkout", "main", "--quiet"]);

        let linked = tmp.path().join("repo-feature");
        git(
            &main,
            &[
                "worktree",
                "add",
                linked.to_str().unwrap(),
                "feature",
                "--quiet",
            ],
        );
        (tmp, main, linked)
    }

    /// BUG-75: from inside a linked worktree, main_worktree_root_from
    /// returns the MAIN worktree path, not the linked one.
    #[test]
    fn main_worktree_root_resolves_from_linked() {
        let (_tmp, main, linked) = fixture_with_linked_worktree();
        let resolved = main_worktree_root_from(&linked);
        assert_eq!(
            std::fs::canonicalize(&resolved).unwrap(),
            std::fs::canonicalize(&main).unwrap(),
            "expected main worktree, got {}",
            resolved.display()
        );
    }

    /// BUG-75: from the main worktree, the helper returns the same path
    /// (no regression).
    #[test]
    fn main_worktree_root_returns_main_unchanged() {
        let (_tmp, main, _linked) = fixture_with_linked_worktree();
        let resolved = main_worktree_root_from(&main);
        assert_eq!(
            std::fs::canonicalize(&resolved).unwrap(),
            std::fs::canonicalize(&main).unwrap()
        );
    }

    /// BUG-76: detect_default_branch_ref picks origin/main when present,
    /// falls back to local main, returns None when neither exists.
    #[test]
    fn default_branch_ref_prefers_origin_main() {
        // Origin-less repo with a local main → falls back to local.
        let (_tmp, main, _linked) = fixture_with_linked_worktree();
        let resolved = detect_default_branch_ref(&main);
        assert_eq!(resolved.as_deref(), Some("main"));
    }

    /// BUG-76: current_branch_at returns the branch checked out at path.
    #[test]
    fn current_branch_at_returns_branch_name() {
        let (_tmp, main, linked) = fixture_with_linked_worktree();
        assert_eq!(current_branch_at(&main).as_deref(), Some("main"));
        assert_eq!(current_branch_at(&linked).as_deref(), Some("feature"));
    }
}

/// Apply the user's `--color=auto|always|never` choice to the colored
/// crate's global override. `auto` is the colored crate's default
/// behavior — it uses `isatty(stdout)` and respects `NO_COLOR`.
/// trace:FR-1-041 | ai:claude
fn apply_color_mode(mode: &str) {
    match mode {
        "always" => colored::control::set_override(true),
        "never" => colored::control::set_override(false),
        _ => {} // "auto" — let colored crate decide via tty detection
    }
}

/// Count queue entries in the user's queue file that pass the role filter.
/// When `role` is `Some`, returns the count of entries with `for_role`
/// matching exactly. When `role` is `None`, returns the total entry
/// count (no role filter).
///
/// Reads `<project>/.aida-store/registry/queues/<user>.yaml` directly —
/// keeps statusline off the heavier Storage::load() path so the sub-50ms
/// budget holds even when the orphan store has hundreds of objects.
/// Returns `None` if the file is missing or unreadable.
/// trace:FR-1-041 | ai:claude
/// TASK-648 (ADR-3): non-archived draft count from the cache, read-only and
/// fast (same SQLite-without-Cache::open pattern as the statusline freshness
/// probe — no migration, no write lock on the prompt hot path). The advisor's
/// statusline shows this as the draft-inbox depth to triage. Returns 0 when
/// the cache is absent or unreadable rather than erroring the prompt.
fn read_draft_inbox_depth(cache_path: &std::path::Path) -> usize {
    if !cache_path.exists() {
        return 0;
    }
    let conn = match rusqlite::Connection::open_with_flags(
        cache_path,
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    ) {
        Ok(c) => c,
        Err(_) => return 0,
    };
    conn.query_row(
        "SELECT COUNT(*) FROM requirements_cache WHERE archived = 0 AND LOWER(status) = 'draft'",
        [],
        |row| row.get::<_, i64>(0),
    )
    .map(|n| n.max(0) as usize)
    .unwrap_or(0)
}

fn read_queue_depth(project_root: &std::path::Path, role: Option<&str>) -> Option<usize> {
    // BUG-89: route through the canonical helper so the statusline depth
    // counts the same queue file `aida queue list` reads from in this
    // shell. trace:BUG-89 | ai:claude
    let user = current_user_id(None);

    let queue_path = project_root
        .join(".aida-store/registry/queues")
        .join(format!("{}.yaml", user));

    let content = std::fs::read_to_string(&queue_path).ok()?;
    let entries: Vec<serde_yaml::Value> = serde_yaml::from_str(&content).ok()?;

    let count = match role {
        Some(want) => entries
            .iter()
            .filter(|e| {
                e.get("for_role")
                    .and_then(serde_yaml::Value::as_str)
                    .map(|r| r == want)
                    .unwrap_or(false)
            })
            .count(),
        None => entries.len(),
    };
    Some(count)
}

/// TASK-244: read `[statusline] role_mismatch_warning` from
/// `.aida/config.toml`. Defaults to `true` (warn on mismatch) when the
/// key, section, or file is absent. trace:TASK-244 | ai:claude
fn statusline_role_mismatch_enabled(project_dir: &std::path::Path) -> bool {
    let Ok(content) = std::fs::read_to_string(project_dir.join(".aida").join("config.toml")) else {
        return true;
    };
    let mut in_section = false;
    for raw in content.lines() {
        let line = strip_toml_inline_comment(raw).trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix('[') {
            in_section = rest.trim_end_matches(']').trim() == "statusline";
            continue;
        }
        if !in_section {
            continue;
        }
        if let Some(rest) = line.strip_prefix("role_mismatch_warning") {
            if let Some(val) = rest.split('=').nth(1) {
                let v = val
                    .trim()
                    .trim_matches('"')
                    .trim_matches('\'')
                    .to_ascii_lowercase();
                return !matches!(v.as_str(), "false" | "0" | "no" | "off");
            }
        }
    }
    true
}

/// TASK-244: render the statusline `role:` segment, surfacing a mismatch
/// between the shell-persistent role (`$AIDA_SESSION_ROLE`, set by `aida
/// role enter`) and the active AIDA session's role (the lease). When
/// TASK-645: the one place "what role am I" is answered. An unset (or
/// blank) `AIDA_SESSION_ROLE` resolves to `implementer` — the read-side
/// default — so no command ever faces a roleless session. The env var is
/// never written by this path; it stays unset until the user explicitly
/// `eval "$(aida role enter <role>)"`s a different role.
fn effective_role() -> String {
    effective_role_resolved().0
}

/// Same resolution as [`effective_role`], but also reports whether the
/// result is the implicit default (`true`) versus an explicitly-entered
/// role (`false`). Callers that want to *show* the default-ness (e.g. the
/// statusline marking `implementer (default)`) use the flag. Pure over the
/// passed-in value so it is unit-testable without touching the process env.
fn resolve_effective_role(raw: Option<&str>) -> (String, bool) {
    match raw.map(str::trim).filter(|s| !s.is_empty()) {
        Some(r) => (canonical_role_name(r), false),
        None => ("implementer".to_string(), true),
    }
}

fn effective_role_resolved() -> (String, bool) {
    resolve_effective_role(std::env::var("AIDA_SESSION_ROLE").ok().as_deref())
}

/// TASK-647 (ADR-3): a status whose *production* requires advisor authority —
/// anything that places a spec into the active execution pipeline (Approved
/// and beyond). Draft / Rejected / NeedsAttention don't gate (they are not
/// "approved work" a non-advisor could smuggle past triage).
fn status_requires_advisor_authority(status: &RequirementStatus) -> bool {
    matches!(
        status,
        RequirementStatus::Approved
            | RequirementStatus::Planned
            | RequirementStatus::InProgress
            | RequirementStatus::Done
            | RequirementStatus::Completed
    )
}

/// TASK-647 (ADR-3): "advisor authority" — permission to produce approved+
/// specs and queue work for execution. Held by an explicit advisor role OR a
/// human at an interactive terminal (stdin is a TTY). Headless `claude -p`,
/// spawned agents, and drain/auto captures have neither, so their intake
/// lands `draft` for advisor triage. This is the hard gate (substrate-as-
/// bouncer): a soft default would be bypassed by `--status approved`.
///
/// NB: the MCP server runs non-TTY but may inherit an advisor `AIDA_SESSION_ROLE`
/// from the launching shell — it therefore does NOT use this helper and gates
/// unconditionally (see `tool_add_requirement`).
/// Pure core of [`has_advisor_authority`] (BUG-460): advisor authority is held
/// by an advisor role, an interactive (TTY) session, OR an operation that is
/// corroborated as running under a live orchestrator. The orchestrator case is
/// the fix: the drain's own auto-queue and its headless implementer/reviewer
/// phases are *workflow system actions* (advancing a spec through its
/// lifecycle), not a bare agent self-advancing — and corroboration requires a
/// token matching the live drain-state run, which a bare agent cannot forge, so
/// the TASK-647/ADR-3 gate still blocks an un-orchestrated agent.
/// trace:BUG-460 trace:TASK-647 | ai:claude
fn advisor_authority_from(role: &str, is_tty: bool, orchestrated: bool) -> bool {
    role == "advisor" || is_tty || orchestrated
}

fn has_advisor_authority() -> bool {
    // BUG-460: a CLI op spawned by (or under) a live --auto-complete drain
    // inherits AIDA_AUTO_COMPLETE + the run token, so `orchestrator::detect`
    // corroborates it against the drain-state file. Grant it authority so
    // --no-human drains can auto-queue the review + let the phase children
    // mutate; a bare headless agent (no live orchestrator) stays gated.
    let orchestrated = find_main_worktree_root()
        .map(|root| {
            matches!(
                orchestrator::detect(&root),
                orchestrator::OrchestratorContext::Orchestrated
            )
        })
        .unwrap_or(false);
    advisor_authority_from(
        &effective_role(),
        std::io::stdin().is_terminal(),
        orchestrated,
    )
}

/// they disagree — and the warning is enabled — both are shown with a
/// `⚠` glyph so three-way role confusion (shell vs session vs resumed
/// conversation) is visible at a glance. Returns `(text, is_mismatch)`
/// so the caller picks the colour. Pure — unit-tested independent of
/// the statusline IO. trace:TASK-244 | ai:claude
fn role_segment_text(
    shell_role: &str,
    session_role: Option<&str>,
    warn_enabled: bool,
) -> (String, bool) {
    let mismatch = warn_enabled
        && session_role
            .map(|s| !s.eq_ignore_ascii_case(shell_role))
            .unwrap_or(false);
    if mismatch {
        (
            format!("role:{} ⚠ session:{}", shell_role, session_role.unwrap()),
            true,
        )
    } else {
        (format!("role:{}", shell_role), false)
    }
}

fn handle_statusline_command(color: &str) -> Result<()> {
    // trace:FR-1-041 | ai:claude
    apply_color_mode(color);

    let project_root = statusline_project_root();
    let project_name = project_root
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "?".into());

    // Try to read project name from store metadata (fall back to dir name).
    let store_name = std::fs::read_to_string(project_root.join("aida-store/metadata.yaml"))
        .or_else(|_| std::fs::read_to_string(project_root.join(".aida-store/metadata.yaml")))
        .ok()
        .and_then(|content| {
            content
                .lines()
                .find_map(|l| {
                    l.strip_prefix("name:")
                        .map(|v| v.trim().trim_matches('"').trim_matches('\'').to_string())
                })
                .filter(|s| !s.is_empty())
        });
    let project_label = store_name.unwrap_or(project_name);

    // TASK-645: resolve through the one role resolver. An unset/blank
    // env var becomes the implementer default (marked below) so the
    // statusline never shows a roleless `(none)`/blank segment.
    let raw_role = std::env::var("AIDA_SESSION_ROLE")
        .ok()
        .filter(|s| !s.trim().is_empty());
    let (effective_role_name, role_is_default) = resolve_effective_role(raw_role.as_deref());

    // STORY-79: opportunistic background fetch. Fire-and-forget; uses
    // current state for this render, refreshed state next render.
    // trace:STORY-79 | ai:claude
    {
        let store_path = if project_root.join(".aida-store").exists() {
            project_root.join(".aida-store")
        } else {
            project_root.join("aida-store")
        };
        if store_path.exists() {
            maybe_spawn_bg_fetch(&project_root, &store_path);
        }
    }

    // Cache freshness state. Folds two axes (cache vs local, local vs
    // origin) into one severity-ordered label. None when there's no
    // cache.db yet (fresh `aida init` with no reads). Render contract
    // below: skip `Fresh`, surface everything else.
    // trace:STORY-78 | ai:claude
    let cache_path = project_root.join(".aida/cache.db");
    let cache_freshness = if cache_path.exists() {
        match rusqlite::Connection::open_with_flags(
            &cache_path,
            rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
        ) {
            Ok(conn) => {
                let recorded_sha: Option<String> = conn
                    .query_row(
                        "SELECT value FROM cache_meta WHERE key = 'source_head_sha'",
                        [],
                        |r| r.get(0),
                    )
                    .ok();
                let local_sha = aida_core::git_ops::head_sha(&project_root.join(".aida-store"))
                    .ok()
                    .or_else(|| aida_core::git_ops::head_sha(&project_root.join("aida-store")).ok())
                    .unwrap_or_default();
                let origin_sha = rev_parse_origin_aida_store(&project_root);
                let last_fetch_age = read_last_fetch_age_secs(&project_root);
                // Resolve direction (local behind / equal / ahead /
                // unknown) before passing to the pure classifier, so
                // unpushed-local-commits don't false-positive as
                // "behind". trace:STORY-78 | ai:claude
                let store_path = if project_root.join(".aida-store").exists() {
                    project_root.join(".aida-store")
                } else {
                    project_root.join("aida-store")
                };
                let local_behind = match (&local_sha, origin_sha.as_deref()) {
                    (l, Some(o)) if !l.is_empty() => local_lags_origin(&store_path, l, o),
                    _ => None,
                };
                Some(classify_cache_freshness(
                    recorded_sha.as_deref(),
                    &local_sha,
                    local_behind,
                    last_fetch_age,
                    cache_freshness_threshold_secs(),
                ))
            }
            Err(_) => None,
        }
    } else {
        None
    };

    // Queue depth — count entries in the user's queue routed to the
    // active role (or all entries when no role is set). Reads the orphan
    // store's queues/<user>.yaml file directly to keep this off the
    // backend's heavier load() path.
    // TASK-645: depth for the effective role (implementer when unset), so
    // the default sees its own queue rather than the all-entries view.
    let queue_depth =
        read_queue_depth(&project_root, Some(effective_role_name.as_str())).unwrap_or(0);

    let separator = " · ".dimmed().to_string();
    // Brand anchor: Greek transliteration of "AIDA". Same 4-column
    // footprint as the prior literal "aida"; the δ is the only
    // unmistakably-Greek glyph, so the prefix carries a quiet identity
    // marker without looking foreign. trace:TASK-1-048 | ai:claude
    let mut parts: Vec<String> = vec![
        "αιδα".dimmed().to_string(),
        project_label.green().bold().to_string(),
    ];
    // TASK-306: orchestrator-context badge. When this interactive session is
    // a corroborated phase of an `--auto-complete` run, surface the phase
    // index, the `--no-human` scope, and a loud `pause-here` cue — so a user
    // who kicked off `--no-human` expecting to walk away sees that phase 1
    // still needs them. Placed right after the project label so it reads
    // before the role/queue segments. The orchestrator's `.aida/` lives in
    // the main worktree (a phase child runs in a sibling worktree), so
    // corroboration resolves the main root. trace:TASK-306 | ai:claude
    {
        let orch_root = find_main_worktree_root()
            .ok()
            .unwrap_or_else(|| project_root.clone());
        if orchestrator::detect(&orch_root).is_orchestrated() {
            let phase = std::env::var(orchestrator::PHASE_ENV)
                .ok()
                .and_then(|v| v.trim().parse::<u8>().ok());
            let no_human = std::env::var(orchestrator::NO_HUMAN_MODE_ENV)
                .ok()
                .filter(|v| !v.is_empty());
            let badge = OrchestratorBadge::build(phase, no_human.as_deref());
            parts.push(badge.phase.cyan().bold().to_string());
            if let Some(nh) = &badge.no_human {
                parts.push(nh.clone().yellow().bold().to_string());
            }
            parts.push(badge.pause.red().bold().to_string());
        }
    }
    // Resolve the active session lease once: both the @SPEC fallback and
    // the dedicated sess: segment use it, and we want a single canonicalize
    // + read-dir per render. trace:STORY-53 | ai:claude
    let lease = std::env::current_dir()
        .ok()
        .and_then(|cwd| active_lease_for_cwd(&project_root, &cwd));

    {
        let r = &effective_role_name;
        // TASK-244: surface a shell-role vs active-session-role mismatch
        // (e.g. shell persists `implementer` while the only active
        // session is `reviewer`). trace:TASK-244 | ai:claude
        // TASK-645: a *defaulted* (unset) role can't meaningfully mismatch a
        // session lease — suppress the warning and tag the segment
        // `(default)` so the implicit role is visible but unalarming.
        let session_role = lease.as_ref().and_then(|l| l.role.as_deref());
        let warn_enabled = !role_is_default && statusline_role_mismatch_enabled(&project_root);
        let (role_text, role_mismatch) = role_segment_text(r, session_role, warn_enabled);
        let role_text = if role_is_default {
            format!("{} (default)", role_text)
        } else {
            role_text
        };
        let role_segment = if role_mismatch {
            role_text.red().bold().to_string()
        } else {
            role_text.yellow().bold().to_string()
        };
        parts.push(role_segment);
        // @SPEC segment. Default: newest activity entry the active role
        // touched. Source preference: the session-local activity log when
        // cwd is inside an active session lease (STORY-56), else the
        // project-level role's activity stream. Override: with a session
        // active but no role activity yet inside it, fall back to
        // `@<scope>` so the prompt advertises the session anchor instead
        // of a pre-session spec. trace:STORY-55 | ai:claude
        let session_latest: Option<RoleActivity> = lease.as_ref().and_then(|l| {
            load_session_activity(&project_root, &l.id)
                .entries
                .into_iter()
                .find(|e| e.role == *r)
                .map(|e| RoleActivity {
                    spec_id: e.spec_id,
                    action: e.action,
                    at: e.at,
                })
        });
        let role_state = load_role(&project_root, r).ok().map(|(s, _)| s);
        let project_latest = role_state
            .as_ref()
            .and_then(|s| s.activity.first())
            .cloned();
        let latest: Option<RoleActivity> = match (lease.as_ref(), session_latest, project_latest) {
            // In-session: prefer session log; only consider project-level
            // entries that are newer than the lease (i.e. a freshly
            // promoted entry from a prior `session end`).
            (Some(l), Some(s), _) => Some(s).filter(|s| s.at >= l.started_at),
            (Some(l), None, p) => p.filter(|p| p.at >= l.started_at),
            (None, _, p) => p,
        };
        // Raw (untruncated) @SPEC value — the scope/spec the active role
        // is anchored to. Kept raw so the TASK-282 redundancy check
        // compares scopes, not their truncated display forms (a long
        // scope truncated to SCOPE_LABEL_MAX vs SESS_LABEL_MAX would
        // otherwise false-positive as divergence). trace:STORY-55 | ai:claude
        let at_spec: Option<String> = match (latest, lease.as_ref()) {
            (Some(act), Some(l)) if act.at >= l.started_at => Some(act.spec_id.clone()),
            (_, Some(l)) => Some(l.scope.clone()),
            (Some(act), None) => Some(act.spec_id.clone()),
            (None, None) => None,
        };
        if let Some(at_spec) = &at_spec {
            let mut segment = format!("@{}", truncate(at_spec, SCOPE_LABEL_MAX))
                .cyan()
                .bold()
                .to_string();
            // TASK-282: fold the session anchor into the @SPEC segment.
            // When the anchor is redundant with @<scope> — same scope and
            // no batch suffix, the common case — nothing is appended; on
            // divergence it appends ` [sess:<anchor>]` so the prompt still
            // names the owning session. trace:TASK-282 | ai:claude
            if let Some(l) = lease.as_ref() {
                let suffix = derive_session_branch_suffix(&l.scope, &l.branch);
                if let Some(anno) = sess_anchor_annotation(at_spec, &l.scope, &suffix) {
                    segment.push(' ');
                    segment.push_str(&anno.yellow().bold().to_string());
                }
            }
            parts.push(segment);
        }
    }
    if queue_depth > 0 {
        parts.push(format!("q:{}", queue_depth));
    }
    // TASK-648 (ADR-3): the advisor seat owns intake triage, so its statusline
    // surfaces the draft-inbox depth (untriaged drafts to disposition). Only
    // for the advisor — other roles don't clear this queue — and only when
    // non-empty, so a clear inbox stays quiet. trace:TASK-648 | ai:claude
    if effective_role_name == "advisor" {
        let inbox_depth = read_draft_inbox_depth(&cache_path);
        if inbox_depth > 0 {
            parts.push(format!("inbox:{}", inbox_depth).cyan().to_string());
        }
    }
    // Cache freshness: only surface non-fresh states. Fresh is the boring
    // default; rendering it on every prompt is noise.
    //   stale  → red    (cache lags local; next read rebuilds — slow)
    //   behind → red    (local lags origin; run `aida db sync --pull`)
    //   ?      → yellow (origin freshness unknown — STORY-79 not run lately
    //                    or no origin/aida-store ref; informational, not red)
    // trace:STORY-78 | ai:claude
    if let Some(f) = cache_freshness {
        if let Some(label) = f.label() {
            let colored = match f {
                CacheFreshness::Unknown => format!("cache:{}", label).yellow().to_string(),
                _ => format!("cache:{}", label).red().to_string(),
            };
            parts.push(colored);
        }
    }
    // sess:<scope> segment — emitted when cwd resolves into an active
    // session lease's worktree. TASK-282: this standalone segment now
    // renders only when there is NO @SPEC segment to fold into (no active
    // role). With a role active, the session anchor lives inside
    // `@<scope> [sess:…]` (rendered above) and a separate `sess:` segment
    // would just repeat it. The TASK-60 batch/branch suffix is preserved
    // either way — without it, three sessions on EPIC-20 (batch3, batch4,
    // batch5) would all render `sess:EPIC-20`, losing the only thing
    // distinguishing them. trace:STORY-53 trace:TASK-60 trace:TASK-282 | ai:claude
    // TASK-645: `role_is_default` is the old `role.is_none()` — no explicit
    // role entered, so the @<scope> role segment carried no session anchor
    // and the standalone `sess:` segment still earns its place.
    if role_is_default {
        if let Some(l) = lease.as_ref() {
            let suffix = derive_session_branch_suffix(&l.scope, &l.branch);
            let label = sess_label_with_suffix(&l.scope, &suffix, SESS_LABEL_MAX);
            parts.push(format!("sess:{}", label).yellow().bold().to_string());
        }
    }
    // wt:<name> segment — emitted only when the session worktree's
    // directory name diverges from the scope-derived slug. `aida session
    // start` auto-names worktrees `<repo>-<slug>`, so the common case
    // renders nothing rather than echoing @<scope>; an explicit `--path`
    // that names the worktree something else is the divergence this
    // segment exists to surface. trace:TASK-282 | ai:claude
    if let Some(l) = lease.as_ref() {
        if let Some(seg) = wt_divergence_segment(&l.worktree_path, &l.slug) {
            parts.push(seg.yellow().bold().to_string());
        }
    }
    println!("{}", parts.join(&separator));
    Ok(())
}

/// TASK-60: pure function deciding what (if anything) to append to
/// the `sess:` segment given the lease scope and branch. Returns an
/// empty string when the branch already matches the slugified scope
/// (no point repeating "epic-20" after "EPIC-20"). Otherwise either
/// `#<suffix>` (when branch shares the scope's slug prefix — the
/// common `epic-N-batchM` pattern) or `@<branch>` (free-form).
/// trace:TASK-60 | ai:claude
fn derive_session_branch_suffix(scope: &str, branch: &str) -> String {
    let scope_slug = slugify(scope);
    if scope_slug.is_empty() || branch == scope_slug {
        return String::new();
    }
    let prefix = format!("{}-", scope_slug);
    if let Some(rest) = branch.strip_prefix(&prefix) {
        if !rest.is_empty() {
            return format!("#{}", rest);
        }
    }
    format!("@{}", branch)
}

/// TASK-60: assemble the `sess:` label, fitting scope + suffix into
/// `max_total` characters. Scope is truncated first if the combined
/// length overflows. trace:TASK-60 | ai:claude
fn sess_label_with_suffix(scope: &str, suffix: &str, max_total: usize) -> String {
    if suffix.is_empty() {
        return truncate(scope, max_total).to_string();
    }
    let suffix_len = suffix.chars().count();
    if suffix_len >= max_total {
        // Pathological — suffix alone overflows. Render scope-truncated
        // anyway so the segment still shows context.
        return truncate(scope, max_total).to_string();
    }
    let scope_budget = max_total - suffix_len;
    let scope_part = truncate(scope, scope_budget);
    format!("{}{}", scope_part, suffix)
}

/// TASK-282: the `[sess:<anchor>]` annotation folded into the `@SPEC`
/// statusline segment. Returns `None` when the session anchor is
/// redundant with the `@<scope>` label — identical scope AND no
/// batch/branch suffix, the boring common case where a separate `sess:`
/// segment would only repeat `@`. Returns `Some("[sess:<label>]")` on
/// divergence: a child-spec `@` (current scope ≠ session anchor) or a
/// batch suffix the bare `@<scope>` can't carry. Keeping the suffix as a
/// divergence trigger preserves TASK-60's batch disambiguation (three
/// EPIC-20 batches stay distinguishable even when `@` equals the scope).
/// trace:TASK-282 | ai:claude
fn sess_anchor_annotation(at_spec: &str, sess_scope: &str, suffix: &str) -> Option<String> {
    if at_spec == sess_scope && suffix.is_empty() {
        return None;
    }
    let label = sess_label_with_suffix(sess_scope, suffix, SESS_LABEL_MAX);
    Some(format!("[sess:{}]", label))
}

/// TASK-282: the `wt:<name>` statusline segment. Returns `Some` only when
/// the session worktree's directory name diverges from the scope slug.
/// `aida session start` auto-names worktrees `<repo>-<slug>` (and a bare
/// `<slug>` dir also counts as matching), so the common case renders
/// nothing rather than echoing `@<scope>`. An explicit `--path` that
/// names the worktree something else (e.g. `hot-fix`) is the divergence
/// the segment exists to surface. The matched name is truncated to the
/// `sess:` budget so a long path doesn't blow the line width.
/// trace:TASK-282 | ai:claude
fn wt_divergence_segment(worktree_path: &std::path::Path, slug: &str) -> Option<String> {
    let basename = worktree_path.file_name().and_then(|s| s.to_str())?;
    if slug.is_empty() {
        return None;
    }
    let matches = basename == slug || basename.ends_with(&format!("-{}", slug));
    if matches {
        None
    } else {
        Some(format!("wt:{}", truncate(basename, SESS_LABEL_MAX)))
    }
}

/// TASK-306: the orchestrator-context badge for the statusline. Built for a
/// corroborated `--auto-complete` phase session; the caller colors the
/// fields. `phase` is the 1-based phase index (`AIDA_AUTO_COMPLETE_PHASE`),
/// `no_human_mode` the `--no-human` scope slug (`AIDA_NO_HUMAN_MODE`).
/// trace:TASK-306 | ai:claude
struct OrchestratorBadge {
    /// `auto:N/6 <phase-name>` — the phase indicator. `auto:?/6` when the
    /// phase env var is missing or unparseable (defensive — the orchestrator
    /// always sets it on the children it spawns).
    phase: String,
    /// `no-human:<mode>` — present only when `--no-human` is in effect.
    no_human: Option<String>,
    /// `pause-here` — the cue that the user is expected to act in this phase.
    /// A statusline only renders for an interactive session, so an
    /// orchestrated badge always carries it.
    pause: &'static str,
}

impl OrchestratorBadge {
    fn build(phase: Option<u8>, no_human_mode: Option<&str>) -> Self {
        let phase = match phase {
            Some(n) => match auto_complete::Phase::from_index(n as i32) {
                Some(p) => format!("auto:{n}/6 {}", p.slug()),
                None => format!("auto:{n}/6"),
            },
            None => "auto:?/6".to_string(),
        };
        OrchestratorBadge {
            phase,
            no_human: no_human_mode.map(|m| format!("no-human:{m}")),
            pause: "pause-here",
        }
    }
}

// ============================================================================
// `aida plan verify` — lint a docs/plans/ file against the structured
// template (TASK-92). Reports drifted line refs, missing files, and absent
// required sections; exits non-zero on any hard failure so it can run as a
// pre-commit hook. trace:TASK-93 | ai:claude
// ============================================================================

/// One section the structured plan template expects. `hard` sections are
/// errors when absent; the rest are warnings. Matched by case-insensitive
/// substring against the plan's `##` headers.
struct PlanSectionSpec {
    keyword: &'static str,
    /// If set, a header matching `keyword` is rejected when it also
    /// contains this string (disambiguates "Files" from "Critical Files").
    exclude: Option<&'static str>,
    label: &'static str,
    hard: bool,
}

const PLAN_SECTIONS: &[PlanSectionSpec] = &[
    PlanSectionSpec {
        keyword: "approach",
        exclude: None,
        label: "Approach",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "decision",
        exclude: None,
        label: "Decisions",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "files",
        exclude: Some("critical"),
        label: "Files",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "critical files",
        exclude: None,
        label: "Critical Files",
        hard: true,
    },
    PlanSectionSpec {
        keyword: "reusable helper",
        exclude: None,
        label: "Reusable helpers",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "risk",
        exclude: None,
        label: "Risks + gotchas",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "test",
        exclude: None,
        label: "Tests",
        hard: false,
    },
    PlanSectionSpec {
        keyword: "verification",
        exclude: None,
        label: "Verification",
        hard: true,
    },
    PlanSectionSpec {
        keyword: "followup",
        exclude: None,
        label: "Followups",
        hard: true,
    },
    PlanSectionSpec {
        keyword: "related",
        exclude: None,
        label: "Related",
        hard: false,
    },
];

/// Source-file extensions a `path:line` ref or bare path is expected to use.
/// Filters out commands (`aida pull`) and prose from the path heuristics.
const PLAN_SOURCE_EXTS: &[&str] = &[
    "rs", "ts", "tsx", "js", "jsx", "py", "toml", "md", "sh", "json", "yaml", "yml", "lock", "css",
    "html",
];

#[derive(PartialEq)]
enum PlanFindingLevel {
    Ok,
    Warn,
    Error,
}

struct PlanFinding {
    level: PlanFindingLevel,
    msg: String,
}

/// A confirmed drifted line ref queued for `--fix` rewriting.
struct PlanRefFix {
    line_idx: usize,
    old: String,
    new: String,
}

fn handle_plan_command(cmd: &PlanCommand) -> Result<()> {
    match cmd {
        PlanCommand::Verify { file, fix, quiet } => verify_plan(file, *fix, *quiet),
        PlanCommand::Helpers { spec, append } => plan_helpers(spec, append.as_deref()),
    }
}

/// Dispatch `aida changelog <generate|refresh|preview>`. The whole engine
/// lives in `crate::changelog`; this just maps the subcommand variant to a
/// `ChangelogOptions` and calls `changelog::run`. trace:TASK-299 | ai:claude
fn handle_changelog_command(cmd: &cli::ChangelogCommand) -> Result<()> {
    let project_root = find_project_root().unwrap_or_else(|_| std::path::PathBuf::from("."));
    let opts = match cmd {
        cli::ChangelogCommand::Generate { since, until, out } => changelog::ChangelogOptions {
            window: if since.is_some() || until.is_some() {
                changelog::Window::Range {
                    since: since.clone(),
                    until: until.clone(),
                }
            } else {
                changelog::Window::All
            },
            sink: match out {
                Some(p) => changelog::Sink::File(p.clone()),
                None => changelog::Sink::Stdout,
            },
            released_as: None,
        },
        cli::ChangelogCommand::Refresh { released_as, out } => changelog::ChangelogOptions {
            window: changelog::Window::All,
            sink: match out {
                Some(p) => changelog::Sink::File(p.clone()),
                None => changelog::Sink::File(project_root.join("CHANGELOG.md")),
            },
            released_as: released_as.clone(),
        },
        cli::ChangelogCommand::Preview => changelog::ChangelogOptions {
            window: changelog::Window::Unreleased,
            sink: changelog::Sink::Stdout,
            released_as: None,
        },
    };
    changelog::run(opts, &project_root)
}

/// Walk up from the plan file to the enclosing git repo root. Paths inside
/// a plan are repo-relative, so this is what we resolve them against. Falls
/// back to the current directory when no `.git` is found.
fn plan_repo_root(plan_file: &std::path::Path) -> std::path::PathBuf {
    let start = plan_file
        .canonicalize()
        .ok()
        .and_then(|p| p.parent().map(std::path::Path::to_path_buf));
    let mut dir = match start {
        Some(d) => d,
        None => return std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from(".")),
    };
    loop {
        if dir.join(".git").exists() {
            return dir;
        }
        match dir.parent() {
            Some(p) => dir = p.to_path_buf(),
            None => {
                return std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."))
            }
        }
    }
}

/// True when `tok` looks like a placeholder rather than a real path:
/// template stand-ins (`path/to/file.rs`, `<STORY-N>`) and globs (`*.md`).
fn is_plan_placeholder_path(tok: &str) -> bool {
    tok.contains('<')
        || tok.contains('>')
        || tok.contains('*')
        || tok.starts_with("path/to/")
        || tok.contains("...")
        || tok.contains("NNN")
}

/// True when `tok` (already stripped of any `:line` suffix) has a known
/// source-file extension.
fn has_plan_source_ext(tok: &str) -> bool {
    match tok.rsplit_once('.') {
        Some((_, ext)) => PLAN_SOURCE_EXTS.contains(&ext.to_ascii_lowercase().as_str()),
        None => false,
    }
}

/// Locate the 1-based line where `symbol` is *defined* in `content`.
/// Recognises Rust item kinds and the common TypeScript/JS forms. Returns
/// the first definition found. A `::`-qualified name is reduced to its
/// final segment before searching.
fn locate_symbol_line(content: &str, symbol: &str) -> Option<usize> {
    use regex::Regex;
    let bare = symbol.rsplit("::").next().unwrap_or(symbol);
    if bare.is_empty() || !bare.chars().all(|c| c.is_alphanumeric() || c == '_') {
        return None;
    }
    let esc = regex::escape(bare);
    // Leading indent must be `[ \t]*`, never `\s*` — `\s` matches `\n`, so a
    // greedy `^\s*` would start the match on the *preceding* blank line and
    // throw the reported line number off by one.
    let rust_item = format!(
        r#"^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?(?:default[ \t]+)?(?:async[ \t]+)?(?:unsafe[ \t]+)?(?:extern[ \t]+(?:"[^"]*"[ \t]+)?)?(?:fn|struct|enum|trait|type|union|mod|const|static)[ \t]+{esc}\b"#
    );
    let pat = format!(
        r"(?m){rust_item}|^[ \t]*macro_rules![ \t]+{esc}\b|^[ \t]*(?:export[ \t]+)?(?:default[ \t]+)?(?:abstract[ \t]+)?(?:async[ \t]+)?(?:function|class|interface)[ \t]+{esc}\b|^[ \t]*(?:export[ \t]+)?(?:const|let|var)[ \t]+{esc}\b"
    );
    let re = Regex::new(&pat).ok()?;
    let m = re.find(content)?;
    Some(content[..m.start()].bytes().filter(|&b| b == b'\n').count() + 1)
}

/// Pull backtick-quoted identifiers that look like code symbols off a line
/// of plan prose: `` `fn foo` `` → `foo`, `` `Storage::update` `` → kept as
/// `Storage::update` (the locator reduces it). Leading item keywords are
/// stripped. Also catches an un-backticked `fn name`.
fn plan_symbols_on_line(line: &str) -> Vec<String> {
    use regex::Regex;
    let mut out = Vec::new();
    let backtick = Regex::new(r"`([^`]+)`").unwrap();
    for cap in backtick.captures_iter(line) {
        let span = cap[1].trim();
        // Drop a leading item keyword: "fn foo" -> "foo".
        let ident = span
            .strip_prefix("fn ")
            .or_else(|| span.strip_prefix("struct "))
            .or_else(|| span.strip_prefix("enum "))
            .or_else(|| span.strip_prefix("trait "))
            .or_else(|| span.strip_prefix("impl "))
            .or_else(|| span.strip_prefix("type "))
            .or_else(|| span.strip_prefix("macro_rules! "))
            .unwrap_or(span)
            .trim();
        // Keep plausible identifiers (optionally `::`-qualified). Reject
        // paths, prose, commands.
        let core = ident.split('(').next().unwrap_or(ident).trim();
        if !core.is_empty()
            && !core.contains(' ')
            && !core.contains('/')
            && !core.contains('.')
            && core
                .chars()
                .all(|c| c.is_alphanumeric() || c == '_' || c == ':')
        {
            out.push(core.to_string());
        }
    }
    let unq = Regex::new(r"\bfn\s+([a-z_][A-Za-z0-9_]*)").unwrap();
    for cap in unq.captures_iter(line) {
        out.push(cap[1].to_string());
    }
    out.sort();
    out.dedup();
    out
}

fn verify_plan(plan_file: &std::path::Path, fix: bool, quiet: bool) -> Result<()> {
    use regex::Regex;
    let content = std::fs::read_to_string(plan_file)
        .with_context(|| format!("could not read plan file {}", plan_file.display()))?;
    let root = plan_repo_root(plan_file);
    let lines: Vec<&str> = content.lines().collect();

    let mut section_findings: Vec<PlanFinding> = Vec::new();
    let mut file_findings: Vec<PlanFinding> = Vec::new();
    let mut ref_findings: Vec<PlanFinding> = Vec::new();
    let mut fixes: Vec<PlanRefFix> = Vec::new();

    // --- Section pass: collect `##` headers, track section membership. ---
    let mut headers_lower: Vec<String> = Vec::new();
    let mut files_section_paths: Vec<String> = Vec::new();
    let mut critical_section_paths: HashSet<String> = HashSet::new();
    let mut in_fence = false;
    let mut in_html_comment = false;
    let mut current_section = String::new();

    let path_ref_re = Regex::new(r"([A-Za-z0-9_][A-Za-z0-9_./\-]*\.[A-Za-z0-9]+):(\d+)").unwrap();
    let bare_path_re = Regex::new(r"`([A-Za-z0-9_][A-Za-z0-9_./\-]*\.[A-Za-z0-9]+)`").unwrap();
    let sym_ref_re = Regex::new(r"\b([a-z_][A-Za-z0-9_]*):(\d+)\b").unwrap();

    for line in &lines {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        if in_fence {
            continue;
        }
        // Skip `<!-- ... -->` regions — meta-commentary, not plan content
        // (the template's own guidance cites an example bad ref there).
        if in_html_comment {
            if line.contains("-->") {
                in_html_comment = false;
            }
            continue;
        }
        if let Some(pos) = line.find("<!--") {
            if !line[pos..].contains("-->") {
                in_html_comment = true;
            }
            continue;
        }
        if let Some(h) = trimmed.strip_prefix("## ") {
            if !trimmed.starts_with("### ") {
                current_section = h.trim().to_ascii_lowercase();
                headers_lower.push(current_section.clone());
            }
        }
        if let Some(h) = trimmed.strip_prefix("### ") {
            // `### `path/to/file.rs` — purpose` names a build-order file.
            if let Some(cap) = bare_path_re.captures(h) {
                let p = cap[1].to_string();
                if current_section.contains("files") && !current_section.contains("critical") {
                    files_section_paths.push(p);
                }
            }
        }
        if current_section.contains("critical files") {
            for cap in bare_path_re.captures_iter(line) {
                critical_section_paths.insert(cap[1].to_string());
            }
        }
    }

    for spec in PLAN_SECTIONS {
        let present = headers_lower
            .iter()
            .any(|h| h.contains(spec.keyword) && !spec.exclude.is_some_and(|ex| h.contains(ex)));
        if present {
            section_findings.push(PlanFinding {
                level: PlanFindingLevel::Ok,
                msg: format!("{} section present", spec.label),
            });
        } else if spec.hard {
            section_findings.push(PlanFinding {
                level: PlanFindingLevel::Error,
                msg: format!("required section missing: {}", spec.label),
            });
        } else {
            section_findings.push(PlanFinding {
                level: PlanFindingLevel::Warn,
                msg: format!("recommended section missing: {}", spec.label),
            });
        }
    }

    // Critical Files completeness: every build-order file should also be
    // enumerated in the Critical Files section.
    for p in &files_section_paths {
        if !critical_section_paths.contains(p) {
            section_findings.push(PlanFinding {
                level: PlanFindingLevel::Warn,
                msg: format!("`{p}` is in Files but not enumerated in Critical Files"),
            });
        }
    }

    // --- File existence + line-ref pass (prose only, skip code fences
    // and HTML comment regions). ---
    let mut checked_paths: HashSet<String> = HashSet::new();
    let mut current_h3_file: Option<String> = None;
    in_fence = false;
    in_html_comment = false;

    for (idx, line) in lines.iter().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        if in_fence {
            continue;
        }
        if in_html_comment {
            if line.contains("-->") {
                in_html_comment = false;
            }
            continue;
        }
        if let Some(pos) = line.find("<!--") {
            if !line[pos..].contains("-->") {
                in_html_comment = true;
            }
            continue;
        }
        if let Some(h) = trimmed.strip_prefix("### ") {
            if let Some(cap) = bare_path_re.captures(h) {
                current_h3_file = Some(cap[1].to_string());
            }
        }

        let symbols = plan_symbols_on_line(line);

        // Bare file paths in backticks — existence check. Only repo-relative
        // paths (containing `/`) are checked; a slashless `foo.rs` is prose
        // shorthand for a file fully named elsewhere, not a path claim.
        for cap in bare_path_re.captures_iter(line) {
            let tok = cap[1].to_string();
            if is_plan_placeholder_path(&tok) || !has_plan_source_ext(&tok) || !tok.contains('/') {
                continue;
            }
            if !checked_paths.insert(tok.clone()) {
                continue;
            }
            if root.join(&tok).exists() {
                file_findings.push(PlanFinding {
                    level: PlanFindingLevel::Ok,
                    msg: tok,
                });
            } else {
                file_findings.push(PlanFinding {
                    level: PlanFindingLevel::Error,
                    msg: format!("{tok} — file not found (plan line {})", idx + 1),
                });
            }
        }

        // `path.ext:NNN` refs — existence + drift.
        for cap in path_ref_re.captures_iter(line) {
            let path = cap[1].to_string();
            let claimed: usize = cap[2].parse().unwrap_or(0);
            if is_plan_placeholder_path(&path) || !has_plan_source_ext(&path) {
                continue;
            }
            let full = root.join(&path);
            if !full.exists() {
                // A slashless `main.rs:NNN` is shorthand — the file may exist
                // under some directory; warn rather than fail the build. A
                // path with a directory that doesn't resolve is a real break.
                if path.contains('/') {
                    ref_findings.push(PlanFinding {
                        level: PlanFindingLevel::Error,
                        msg: format!("{path}:{claimed} — file not found (plan line {})", idx + 1),
                    });
                } else {
                    ref_findings.push(PlanFinding {
                        level: PlanFindingLevel::Warn,
                        msg: format!(
                            "{path}:{claimed} — bare filename does not resolve; use a \
                             repo-relative path (plan line {})",
                            idx + 1
                        ),
                    });
                }
                continue;
            }
            let body = std::fs::read_to_string(&full).unwrap_or_default();
            let mut resolved = false;
            for sym in &symbols {
                if let Some(actual) = locate_symbol_line(&body, sym) {
                    resolved = true;
                    if actual == claimed {
                        ref_findings.push(PlanFinding {
                            level: PlanFindingLevel::Ok,
                            msg: format!("{path}:{claimed} — `{sym}` confirmed"),
                        });
                    } else {
                        let delta = actual as i64 - claimed as i64;
                        ref_findings.push(PlanFinding {
                            level: PlanFindingLevel::Warn,
                            msg: format!(
                                "{path}:{claimed} — `{sym}` is at line {actual} (drift {delta:+}); \
                                 prefer symbol form `{sym}` or update to {path}:{actual} (plan line {})",
                                idx + 1
                            ),
                        });
                        fixes.push(PlanRefFix {
                            line_idx: idx,
                            old: format!("{path}:{claimed}"),
                            new: format!("{path}:{actual}"),
                        });
                    }
                    break;
                }
            }
            if !resolved {
                ref_findings.push(PlanFinding {
                    level: PlanFindingLevel::Warn,
                    msg: format!(
                        "{path}:{claimed} — no named symbol on this line to verify the \
                         line number against (plan line {})",
                        idx + 1
                    ),
                });
            }
        }

        // `symbol:NNN` refs (no path) — resolve against the current
        // build-order file header, if any.
        for cap in sym_ref_re.captures_iter(line) {
            let sym = cap[1].to_string();
            let claimed: usize = cap[2].parse().unwrap_or(0);
            // Skip if this match is the tail of a longer token (a
            // `path.ext:line` ref or a `dir/seg:line` fragment) rather
            // than a standalone `symbol:line` ref.
            let mstart = cap.get(0).unwrap().start();
            if mstart > 0 {
                let prev = line.as_bytes()[mstart - 1];
                if prev == b'.' || prev == b'/' || prev == b'-' || prev.is_ascii_alphanumeric() {
                    continue;
                }
            }
            let Some(file) = &current_h3_file else {
                continue;
            };
            if is_plan_placeholder_path(file) {
                continue;
            }
            let full = root.join(file);
            let Ok(body) = std::fs::read_to_string(&full) else {
                continue;
            };
            if let Some(actual) = locate_symbol_line(&body, &sym) {
                if actual == claimed {
                    ref_findings.push(PlanFinding {
                        level: PlanFindingLevel::Ok,
                        msg: format!("{sym}:{claimed} — confirmed in {file}"),
                    });
                } else {
                    let delta = actual as i64 - claimed as i64;
                    ref_findings.push(PlanFinding {
                        level: PlanFindingLevel::Warn,
                        msg: format!(
                            "{sym}:{claimed} — `{sym}` is at line {actual} in {file} \
                             (drift {delta:+}); prefer symbol form `{sym}` (plan line {})",
                            idx + 1
                        ),
                    });
                    fixes.push(PlanRefFix {
                        line_idx: idx,
                        old: format!("{sym}:{claimed}"),
                        new: format!("{sym}:{actual}"),
                    });
                }
            }
        }
    }

    // --- Report. ---
    let plan_label = plan_file.display();
    println!("{} {}", "Verifying plan:".bold(), plan_label);
    println!();

    let print_group = |title: &str, findings: &[PlanFinding]| {
        if findings.is_empty() {
            return;
        }
        println!("{}", title.cyan().bold());
        for f in findings {
            if quiet && f.level == PlanFindingLevel::Ok {
                continue;
            }
            let tag = match f.level {
                PlanFindingLevel::Ok => "  OK   ".green(),
                PlanFindingLevel::Warn => "  WARN ".yellow(),
                PlanFindingLevel::Error => "  ERROR".red().bold(),
            };
            println!("{} {}", tag, f.msg);
        }
        println!();
    };

    print_group("Sections", &section_findings);
    print_group("Files", &file_findings);
    print_group("Line refs", &ref_findings);

    let count = |findings: &[PlanFinding], level: &PlanFindingLevel| {
        findings.iter().filter(|f| &f.level == level).count()
    };
    let errors = count(&section_findings, &PlanFindingLevel::Error)
        + count(&file_findings, &PlanFindingLevel::Error)
        + count(&ref_findings, &PlanFindingLevel::Error);
    let warns = count(&section_findings, &PlanFindingLevel::Warn)
        + count(&file_findings, &PlanFindingLevel::Warn)
        + count(&ref_findings, &PlanFindingLevel::Warn);

    if fix && !fixes.is_empty() {
        let mut patched = lines.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        let mut applied = 0;
        for f in &fixes {
            if let Some(line) = patched.get_mut(f.line_idx) {
                if line.contains(&f.old) {
                    *line = line.replacen(&f.old, &f.new, 1);
                    applied += 1;
                }
            }
        }
        let trailing_nl = content.ends_with('\n');
        let mut new_content = patched.join("\n");
        if trailing_nl {
            new_content.push('\n');
        }
        std::fs::write(plan_file, new_content)?;
        println!(
            "{} rewrote {} drifted ref(s) in place",
            "fix:".green().bold(),
            applied
        );
        println!();
    } else if !fixes.is_empty() {
        println!(
            "{} re-run with {} to rewrite {} drifted ref(s) automatically",
            "hint:".bold(),
            "--fix".cyan(),
            fixes.len()
        );
        println!();
    }

    let verdict = if errors > 0 {
        format!("{} error(s), {} warning(s) — FAIL", errors, warns)
            .red()
            .bold()
            .to_string()
    } else if warns > 0 {
        format!("0 errors, {warns} warning(s) — PASS")
            .yellow()
            .to_string()
    } else {
        "all checks passed — PASS".green().bold().to_string()
    };
    println!("{} {}", "Verdict:".bold(), verdict);

    if errors > 0 {
        std::process::exit(1);
    }
    Ok(())
}

// ============================================================================
// TASK-94 — `aida plan helpers <spec>`. Derive a "Reusable helpers" section
// by walking the requirement graph (sibling / same-feature / same-tag specs)
// and harvesting those specs' `// trace:` comments from the codebase, so the
// implementer reuses existing helpers instead of re-inventing them.
// trace:TASK-94 | ai:claude
// ============================================================================

/// One harvested trace comment: a related spec touches `file`, and (when a
/// definition sits on or just below the comment) the named `symbol`.
struct TraceHit {
    file: String,
    symbol: Option<String>,
}

/// Recursively collect source files under `dir`, skipping hidden dirs and
/// the usual build/vendor trees.
fn collect_source_files(dir: &std::path::Path, exts: &[&str], out: &mut Vec<std::path::PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
            if name.starts_with('.')
                || name == "target"
                || name == "node_modules"
                || name == "vendor"
            {
                continue;
            }
        }
        if path.is_dir() {
            collect_source_files(&path, exts, out);
        } else if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if exts.contains(&ext) {
                out.push(path);
            }
        }
    }
}

/// Scan the codebase for `trace:<SPEC-ID>` comments whose id is in `wanted`,
/// returning spec_id → the trace hits found. The symbol on each hit is the
/// first definition on the trace line or the two lines below it (comment
/// lines are skipped so the comment's own prose can't false-match).
/// trace:TASK-94 | ai:claude
pub(crate) fn scan_trace_graph(
    project_root: &std::path::Path,
    wanted: &HashSet<String>,
) -> std::collections::HashMap<String, Vec<TraceHit>> {
    use regex::Regex;
    // Capture the full spec id — including the optional third segment of a
    // node-aware id (`FR-1-042`), or `trace:FR-1-042` would bucket under a
    // bogus `FR-1`.
    let trace_re = Regex::new(r"\btrace:([A-Z]+-[0-9]+(?:-[0-9]+)?)").unwrap();
    let sym_re = Regex::new(
        r"\b(?:fn|struct|enum|trait|type|mod|const|static|function|class|interface)\s+([A-Za-z_][A-Za-z0-9_]*)",
    )
    .unwrap();
    let exts = ["rs", "ts", "tsx", "js", "jsx", "py", "sh"];
    let mut files = Vec::new();
    collect_source_files(project_root, &exts, &mut files);

    let mut out: std::collections::HashMap<String, Vec<TraceHit>> =
        std::collections::HashMap::new();
    for path in &files {
        let Ok(content) = std::fs::read_to_string(path) else {
            continue;
        };
        let lines: Vec<&str> = content.lines().collect();
        for (i, line) in lines.iter().enumerate() {
            for cap in trace_re.captures_iter(line) {
                let id = cap[1].to_string();
                if !wanted.contains(&id) {
                    continue;
                }
                // Symbol: first definition on this line or the next two,
                // skipping pure comment lines.
                let mut symbol = None;
                for probe in lines.iter().skip(i).take(3) {
                    let t = probe.trim_start();
                    if t.starts_with("//") || t.starts_with('#') || t.starts_with('*') {
                        continue;
                    }
                    if let Some(m) = sym_re.captures(probe) {
                        symbol = Some(m[1].to_string());
                        break;
                    }
                }
                let rel = path
                    .strip_prefix(project_root)
                    .unwrap_or(path)
                    .display()
                    .to_string();
                out.entry(id)
                    .or_default()
                    .push(TraceHit { file: rel, symbol });
            }
        }
    }
    out
}

/// TASK-241: extract the PR number from a GitHub squash-merge commit
/// subject, which ends with `(#NN)`. Returns None when the subject has
/// no such suffix. trace:TASK-241 | ai:claude
fn parse_squash_pr_number(subject: &str) -> Option<u64> {
    subject
        .trim_end()
        .rsplit_once("(#")
        .and_then(|(_, tail)| tail.strip_suffix(')'))
        .and_then(|n| n.parse::<u64>().ok())
}

/// TASK-238/STORY-442: the inline tag-chip body for an `aida queue list`
/// row. `batch:*` and `lifecycle:*` tags come first and are always shown
/// (they alter pickup/routing behavior); plain tags are sorted, capped at
/// 3, and any remainder collapses to a `+N` overflow marker. Returns None
/// when the requirement carries no tags. trace:TASK-238 STORY-442
pub(crate) fn format_tag_chip(tags: &std::collections::HashSet<String>) -> Option<String> {
    if tags.is_empty() {
        return None;
    }
    const MAX_PLAIN: usize = 3;
    let mut batch_tags: Vec<&str> = Vec::new();
    let mut lifecycle_tags: Vec<&str> = Vec::new();
    let mut plain_tags: Vec<&str> = Vec::new();
    for t in tags {
        if t.to_ascii_lowercase().starts_with("batch:") {
            batch_tags.push(t.as_str());
        } else if t.to_ascii_lowercase().starts_with("lifecycle:") {
            lifecycle_tags.push(t.as_str());
        } else {
            plain_tags.push(t.as_str());
        }
    }
    batch_tags.sort_unstable();
    lifecycle_tags.sort_unstable();
    plain_tags.sort_unstable();
    let mut shown: Vec<String> = batch_tags.iter().map(|s| s.to_string()).collect();
    shown.extend(lifecycle_tags.iter().map(|s| s.to_string()));
    shown.extend(plain_tags.iter().take(MAX_PLAIN).map(|s| s.to_string()));
    if plain_tags.len() > MAX_PLAIN {
        shown.push(format!("+{}", plain_tags.len() - MAX_PLAIN));
    }
    Some(shown.join(", "))
}

/// TASK-238: does the tag set contain `want` (case-insensitive)? The
/// predicate behind `aida queue list --tag`. trace:TASK-238 | ai:claude
pub(crate) fn tag_matches_exact(tags: &std::collections::HashSet<String>, want: &str) -> bool {
    tags.iter().any(|t| t.eq_ignore_ascii_case(want))
}

/// TASK-238: does any tag start with `prefix` (case-insensitive)? The
/// predicate behind `aida queue list --tag-prefix`. trace:TASK-238
pub(crate) fn tag_matches_prefix(tags: &std::collections::HashSet<String>, prefix: &str) -> bool {
    let lp = prefix.to_ascii_lowercase();
    tags.iter().any(|t| t.to_ascii_lowercase().starts_with(&lp))
}

/// TASK-238: the `batch:*` tag a requirement carries (lowest-sorting
/// when several), used as the group key for `aida queue list
/// --by-batch`. None when the requirement is un-batched.
/// trace:TASK-238 | ai:claude
pub(crate) fn batch_tag_of(tags: &std::collections::HashSet<String>) -> Option<&str> {
    let mut found: Vec<&str> = tags
        .iter()
        .filter(|t| t.to_ascii_lowercase().starts_with("batch:"))
        .map(|s| s.as_str())
        .collect();
    found.sort_unstable();
    found.into_iter().next()
}

/// TASK-270: strip a redundant leading `batch:` prefix off a string,
/// returning `Some(rest)` only when the prefix was present
/// (case-insensitive). `batch:` is the literal tag printed by `aida
/// queue list`; first-users reflexively copy that whole token back into
/// `--batch` or a positional id. trace:TASK-270 | ai:claude
fn strip_batch_prefix(s: &str) -> Option<&str> {
    let prefix = "batch:";
    s.get(..prefix.len())
        .filter(|p| p.eq_ignore_ascii_case(prefix))
        .map(|_| &s[prefix.len()..])
}

/// TASK-270: normalize a `--batch` flag value so `--batch NAME` and the
/// redundant `--batch batch:NAME` (the literal tag from `aida queue
/// list`) both resolve to `NAME`. trace:TASK-270 | ai:claude
pub(crate) fn normalize_batch_name(s: &str) -> &str {
    strip_batch_prefix(s).unwrap_or(s)
}

/// TASK-310: parse comma-separated batch-chain names. Names are kept in the
/// caller's declared order; `batch:` prefixes are tolerated per TASK-270.
fn parse_batch_chain(raw: &str) -> Result<Vec<String>> {
    let mut names = Vec::new();
    for part in raw.split(',') {
        let name = normalize_batch_name(part.trim()).trim();
        if name.is_empty() {
            anyhow::bail!(
                "batch list contains an empty name — use comma-separated names like `--batches A,B,C`"
            );
        }
        names.push(name.to_string());
    }
    if names.is_empty() {
        anyhow::bail!("batch list is empty — use comma-separated names like `--batches A,B,C`");
    }
    Ok(names)
}

/// TASK-270: resolve the effective positional id and batch name for
/// `aida queue work`. Accepts `batch:NAME` as a positional id
/// (equivalent to `--batch NAME`) and strips a redundant `batch:`
/// prefix off the `--batch` flag value. At most one element of the
/// returned `(id, batch)` pair is `Some` — clap's
/// `conflicts_with(batch, id)` already rejects passing both, and a
/// `batch:`-prefixed positional is rerouted to the batch slot.
/// trace:TASK-270 | ai:claude
/// TASK-322: true when a `queue work` positional is a `next` / `nextN`
/// head-pickup keyword (vs a SPEC-ID or `batch:NAME`). Used to catch the
/// `--batch` + `nextN` collision that otherwise silently dropped the keyword.
/// trace:TASK-322 | ai:claude
fn is_next_keyword_id(id: &str) -> bool {
    id.to_ascii_lowercase()
        .strip_prefix("next")
        .map(|suffix| suffix.is_empty() || suffix.chars().all(|c| c.is_ascii_digit()))
        .unwrap_or(false)
}

fn resolve_queue_work_batch<'a>(
    id: Option<&'a str>,
    batch: Option<&'a str>,
) -> (Option<&'a str>, Option<&'a str>) {
    if let Some(b) = batch {
        return (None, Some(normalize_batch_name(b)));
    }
    if let Some(i) = id {
        if let Some(name) = strip_batch_prefix(i) {
            return (None, Some(name));
        }
        return (Some(i), None);
    }
    (None, None)
}

/// TASK-234: the three in-flight buckets, split out of
/// [`render_in_flight_grouped`] so the classification — which only ever
/// touches git (`log` / `merge-base` / `branch --contains`), never gh —
/// is unit-testable against a temp repo. trace:TASK-234 | ai:claude
struct InFlightBuckets {
    /// (spec_id, squash-merge PR number if any, relative time) — the
    /// referencing commit is already on main but the spec never bumped
    /// to Completed (auto-bump missed).
    stuck: Vec<(String, Option<u64>, String)>,
    /// branch → spec_ids — the commit is on a feature branch, awaiting
    /// merge.
    awaiting: std::collections::BTreeMap<String, Vec<String>>,
    /// Done specs with no commit referencing the id yet.
    no_commit: Vec<String>,
}

/// TASK-234: bucket Done specs by git state. gh-free by design — the
/// PR-state lookup happens later, in [`render_in_flight_grouped`]. A
/// referencing commit on main → `stuck`; on a feature branch →
/// `awaiting`; no commit at all → `no_commit`. trace:TASK-234 | ai:claude
fn classify_in_flight_specs(
    specs: &[&aida_core::Requirement],
    project_root: &std::path::Path,
) -> InFlightBuckets {
    use std::collections::BTreeMap;
    use std::process::Command as PCmd;

    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim_end().to_string())
    };
    // BUG-380: capture stderr via output() so an invalid `target` ref
    // cannot leak `fatal: Not a valid object name <X>` to the user's
    // terminal — paired with `resolve_default_branch_ref`, which
    // returns a refname known to exist (or None to skip the check).
    let is_ancestor = |sha: &str, target: &str| -> bool {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(["merge-base", "--is-ancestor", sha, target])
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    };
    let main_ref = resolve_default_branch_ref(project_root);

    let mut stuck: Vec<(String, Option<u64>, String)> = Vec::new();
    let mut awaiting: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut no_commit: Vec<String> = Vec::new();

    for req in specs {
        let id = req
            .agreed_id
            .as_deref()
            .or(req.spec_id.as_deref())
            .unwrap_or("???")
            .to_string();
        // Newest commit referencing the AIDA `(SPEC-ID)` format.
        let pattern = format!("({})", id);
        let line = git(&[
            "log",
            "--all",
            "-F",
            "-1",
            "--grep",
            pattern.as_str(),
            "--pretty=format:%H\u{1f}%s\u{1f}%cr",
        ])
        .unwrap_or_default();
        let mut parts = line.splitn(3, '\u{1f}');
        let (Some(full), subject, ago) = (
            parts.next().filter(|s| !s.is_empty()),
            parts.next().unwrap_or(""),
            parts.next().unwrap_or("recently"),
        ) else {
            no_commit.push(id);
            continue;
        };
        let on_default = main_ref
            .as_deref()
            .map(|m| is_ancestor(full, m))
            .unwrap_or(false);
        if on_default {
            stuck.push((id, parse_squash_pr_number(subject), ago.to_string()));
        } else {
            let contains = git(&[
                "branch",
                "--all",
                "--contains",
                full,
                "--format=%(refname:short)",
            ])
            .unwrap_or_default();
            let candidates: Vec<String> = contains
                .lines()
                .map(|b| b.trim().trim_start_matches("origin/"))
                .filter(|b| !b.is_empty() && *b != "HEAD" && *b != "main" && *b != "master")
                .map(|b| b.to_string())
                .collect();
            // BUG-229: `pr-N` (and `mr-N` / `github-N` / `gitlab-N`) are
            // reviewer-worktree *snapshot* branches — `aida` fetches them
            // via `git fetch origin pull/N/head:pr-N` for headless review.
            // The spec's actual PR-source branch is named after the spec
            // (e.g. `task-282`). When the referencing commit lands on both,
            // a plain alphabetical `.next()` picks `pr-N` (it sorts first),
            // and the later `gh pr list --head pr-N` finds nothing — the
            // row then mis-renders as "no PR opened yet" for a PR that is
            // open and under review. Prefer a non-review-session branch so
            // the PR lookup keys off the real head. trace:BUG-229 | ai:claude
            let branch = candidates
                .iter()
                .find(|b| !is_review_session_branch(b))
                .or_else(|| candidates.first())
                .cloned()
                .unwrap_or_else(|| "(branch unknown)".to_string());
            awaiting.entry(branch).or_default().push(id);
        }
    }

    InFlightBuckets {
        stuck,
        awaiting,
        no_commit,
    }
}

/// TASK-250: a PR's review sub-state, derived from AIDA-local signals
/// only — session leases and the `Review PR-N:` story status. The gh
/// `reviewDecision` probe that promotes a row to State 3 (Approved)
/// layers on top in the render path. trace:TASK-250 | ai:claude
#[derive(Debug, PartialEq)]
enum LocalReviewState {
    /// State 1: no reviewer lease, no In-Progress review story.
    NotStarted,
    /// State 2: a reviewer session lease owns this PR — carries the
    /// short session id + a humanized start time for the hint.
    InProgressLease { session_id: String, since: String },
    /// State 2 (no scoped session): the `Review PR-N:` story is
    /// In Progress — a reviewer picked the queue item up.
    InProgressStory { story_id: String },
}

/// TASK-250: classify a PR's review state from session leases + the
/// `Review PR-N:` story. gh-free by design — it only reads lease TOML
/// and the in-memory requirement set, so it is unit-testable against a
/// temp project root. The render path adds the gh `reviewDecision`
/// probe (State 3) on top. trace:TASK-250 | ai:claude
fn detect_local_review_state(
    project_root: &std::path::Path,
    all_reqs: &[aida_core::Requirement],
    pr_number: u64,
) -> LocalReviewState {
    // Leg 1 — an active session lease scoped to this PR. The strongest
    // signal: a reviewer shell is open on it right now. `list_leases`
    // returns oldest-first, so the last match is the most recent.
    let mut lease_hit: Option<(String, String)> = None;
    for lease in list_leases(project_root) {
        if let Some((ReviewForge::GitHub, n)) = parse_review_scope(&lease.scope) {
            if n == pr_number {
                lease_hit = Some((lease.id.clone(), humanize_relative(lease.started_at)));
            }
        }
    }
    if let Some((session_id, since)) = lease_hit {
        return LocalReviewState::InProgressLease { session_id, since };
    }
    // Leg 2 — an In-Progress `Review PR-N:` story: the reviewer picked
    // the queue item up but isn't in a PR-scoped session.
    for r in all_reqs {
        if r.status == RequirementStatus::InProgress
            && parse_review_story_pr_number(&r.title) == Some(pr_number)
        {
            let story_id = r
                .agreed_id
                .as_deref()
                .or(r.spec_id.as_deref())
                .unwrap_or("")
                .to_string();
            return LocalReviewState::InProgressStory { story_id };
        }
    }
    LocalReviewState::NotStarted
}

/// TASK-250: gh's `reviewDecision` for a PR plus the approving
/// reviewer's login — the State 3 ("reviewed + approved") signal.
/// trace:TASK-250 | ai:claude
struct PrReviewDecision {
    /// gh `reviewDecision`: "APPROVED" / "CHANGES_REQUESTED" /
    /// "REVIEW_REQUIRED" / "" (no reviews).
    decision: String,
    /// login of the most recent APPROVED review, when resolvable.
    approver: Option<String>,
}

/// TASK-250: parse `gh pr view --json reviewDecision,latestReviews`
/// output. Pure — unit-tested against captured gh JSON without
/// spawning gh. trace:TASK-250 | ai:claude
fn parse_review_decision_json(stdout: &str) -> Option<PrReviewDecision> {
    let json: serde_json::Value = serde_json::from_str(stdout).ok()?;
    let decision = json
        .get("reviewDecision")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let approver = json
        .get("latestReviews")
        .and_then(|v| v.as_array())
        .and_then(|reviews| {
            reviews
                .iter()
                .filter(|r| r.get("state").and_then(|s| s.as_str()) == Some("APPROVED"))
                .filter_map(|r| {
                    r.get("author")
                        .and_then(|a| a.get("login"))
                        .and_then(|l| l.as_str())
                })
                .last()
                .map(|s| s.to_string())
        });
    Some(PrReviewDecision { decision, approver })
}

/// TASK-250: probe gh for a PR's review decision. `None` when gh is
/// missing or the call fails — the caller degrades to the local review
/// state. trace:TASK-250 | ai:claude
fn detect_pr_review_decision(
    project_root: &std::path::Path,
    pr_number: u64,
) -> Option<PrReviewDecision> {
    let gh_bin = resolve_gh_binary()?;
    let out = std::process::Command::new(&gh_bin)
        .current_dir(project_root)
        .args([
            "pr",
            "view",
            &pr_number.to_string(),
            "--json",
            "reviewDecision,latestReviews",
        ])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    parse_review_decision_json(&String::from_utf8_lossy(&out.stdout))
}

/// TASK-250: parse `gh pr list --state merged --json number,mergedAt`
/// output into (pr_number, humanized merge time). Pure — unit-tested
/// against captured gh JSON. trace:TASK-250 | ai:claude
fn parse_merged_pr_json(stdout: &str) -> Option<(u64, Option<String>)> {
    let json: serde_json::Value = serde_json::from_str(stdout).ok()?;
    let first = json.as_array()?.first()?;
    let number = first.get("number")?.as_u64()?;
    let merged = first
        .get("mergedAt")
        .and_then(|v| v.as_str())
        .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
        .map(|dt| humanize_relative(dt.with_timezone(&chrono::Utc)));
    Some((number, merged))
}

/// TASK-250: State-4 probe — was `branch` the head of a now-MERGED PR,
/// and when did it merge? Distinct from `detect_merged_pr_for_branch`
/// because it also pulls `mergedAt` for the "Merged {time}" hint.
/// `None` when gh is missing / fails / reports no merged PR.
/// trace:TASK-250 | ai:claude
fn detect_merged_pr_with_time(
    project_root: &std::path::Path,
    branch: &str,
) -> Option<(u64, Option<String>)> {
    let gh_bin = resolve_gh_binary()?;
    let out = std::process::Command::new(&gh_bin)
        .current_dir(project_root)
        .args([
            "pr",
            "list",
            "--head",
            branch,
            "--state",
            "merged",
            "--limit",
            "1",
            "--json",
            "number,mergedAt",
        ])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    parse_merged_pr_json(&String::from_utf8_lossy(&out.stdout))
}

/// TASK-250: unit coverage for the four-state classification behind
/// `aida queue list`'s "Done — awaiting merge" section. The lease /
/// review-story leg (`detect_local_review_state`) is exercised against
/// a temp project root; the gh-JSON parsers are exercised against
/// captured `gh` output. trace:TASK-250 | ai:claude
#[cfg(test)]
mod task_250_review_state_tests {
    use super::*;

    fn write_lease(project_root: &std::path::Path, id: &str, scope: &str) {
        let dir = project_root.join(".aida").join("sessions");
        std::fs::create_dir_all(&dir).unwrap();
        let lease = SessionLease {
            id: id.to_string(),
            scope: scope.to_string(),
            slug: scope.to_ascii_lowercase(),
            owner: "tester".into(),
            worktree_path: project_root.to_path_buf(),
            branch: scope.to_ascii_lowercase(),
            started_at: chrono::Utc::now(),
            hostname: "h".into(),
            role: Some("reviewer".into()),
            creator_pid: None,
            cargo_target_dir: None,
            parent_project_root: None,
            pr_head_sha: None,
            pr_base_sha: None,
            pr_base_ref: None,
            zen_intent_token: None,
            escalated_to_human: None,
            parent_branch: None,
            parent_branch_sha: None,
        };
        std::fs::write(
            dir.join(format!("{}.toml", id)),
            toml::to_string_pretty(&lease).unwrap(),
        )
        .unwrap();
    }

    fn review_story(pr: u64, status: RequirementStatus) -> aida_core::Requirement {
        let mut r =
            aida_core::Requirement::new(format!("Review PR-{}: some batch", pr), String::new());
        r.spec_id = Some(format!("STORY-{}", 900 + pr));
        r.status = status;
        r
    }

    /// State 1: no lease, no In-Progress review story → NotStarted.
    #[test]
    fn local_state_not_started_with_no_signals() {
        let tmp = tempfile::tempdir().unwrap();
        assert_eq!(
            detect_local_review_state(tmp.path(), &[], 42),
            LocalReviewState::NotStarted
        );
    }

    /// State 1: a `Review PR-42:` story still at Approved (queued, not
    /// picked up) does NOT count as in-progress — the status the
    /// auto-queue files it at is "ready to work", not a verdict.
    #[test]
    fn local_state_approved_review_story_is_not_in_progress() {
        let tmp = tempfile::tempdir().unwrap();
        let reqs = [review_story(42, RequirementStatus::Approved)];
        assert_eq!(
            detect_local_review_state(tmp.path(), &reqs, 42),
            LocalReviewState::NotStarted
        );
    }

    /// State 2: an active session lease scoped to PR-42 → InProgressLease.
    #[test]
    fn local_state_in_progress_via_lease() {
        let tmp = tempfile::tempdir().unwrap();
        write_lease(tmp.path(), "abc123def456", "PR-42");
        match detect_local_review_state(tmp.path(), &[], 42) {
            LocalReviewState::InProgressLease { session_id, .. } => {
                assert_eq!(session_id, "abc123def456");
            }
            other => panic!("expected InProgressLease, got {:?}", other),
        }
    }

    /// State 2: a lease scoped to a DIFFERENT PR is ignored.
    #[test]
    fn local_state_lease_for_other_pr_ignored() {
        let tmp = tempfile::tempdir().unwrap();
        write_lease(tmp.path(), "abc123def456", "PR-99");
        assert_eq!(
            detect_local_review_state(tmp.path(), &[], 42),
            LocalReviewState::NotStarted
        );
    }

    /// State 2: an In-Progress `Review PR-42:` story (no scoped session)
    /// → InProgressStory carrying the story id.
    #[test]
    fn local_state_in_progress_via_review_story() {
        let tmp = tempfile::tempdir().unwrap();
        let reqs = [review_story(42, RequirementStatus::InProgress)];
        match detect_local_review_state(tmp.path(), &reqs, 42) {
            LocalReviewState::InProgressStory { story_id } => {
                assert_eq!(story_id, "STORY-942");
            }
            other => panic!("expected InProgressStory, got {:?}", other),
        }
    }

    /// State 2: the lease leg wins over the review-story leg when both
    /// fire — a live scoped session is the stronger signal.
    #[test]
    fn local_state_lease_takes_precedence_over_story() {
        let tmp = tempfile::tempdir().unwrap();
        write_lease(tmp.path(), "abc123def456", "PR-42");
        let reqs = [review_story(42, RequirementStatus::InProgress)];
        assert!(matches!(
            detect_local_review_state(tmp.path(), &reqs, 42),
            LocalReviewState::InProgressLease { .. }
        ));
    }

    /// State 3: gh `reviewDecision` APPROVED with a latestReviews entry
    /// → decision + approver login parsed.
    #[test]
    fn parse_review_decision_approved_with_reviewer() {
        let json = r#"{
            "reviewDecision": "APPROVED",
            "latestReviews": [
                {"author": {"login": "alice"}, "state": "APPROVED"}
            ]
        }"#;
        let d = parse_review_decision_json(json).expect("parses");
        assert_eq!(d.decision, "APPROVED");
        assert_eq!(d.approver.as_deref(), Some("alice"));
    }

    /// State 1/edge: a PR with no reviews → empty decision, no approver.
    #[test]
    fn parse_review_decision_no_reviews() {
        let json = r#"{"reviewDecision": "", "latestReviews": []}"#;
        let d = parse_review_decision_json(json).expect("parses");
        assert_eq!(d.decision, "");
        assert!(d.approver.is_none());
    }

    /// CHANGES_REQUESTED parses but is not APPROVED — the render path
    /// treats it as "not State 3" and falls back to the local state.
    #[test]
    fn parse_review_decision_changes_requested() {
        let json = r#"{
            "reviewDecision": "CHANGES_REQUESTED",
            "latestReviews": [
                {"author": {"login": "bob"}, "state": "CHANGES_REQUESTED"}
            ]
        }"#;
        let d = parse_review_decision_json(json).expect("parses");
        assert_eq!(d.decision, "CHANGES_REQUESTED");
        assert!(d.approver.is_none(), "no APPROVED review → no approver");
    }

    /// State 4: a merged PR with a `mergedAt` timestamp → number + a
    /// humanized merge time.
    #[test]
    fn parse_merged_pr_with_timestamp() {
        let json = r#"[{"number": 43, "mergedAt": "2026-05-15T10:00:00Z"}]"#;
        let (number, merged) = parse_merged_pr_json(json).expect("parses");
        assert_eq!(number, 43);
        assert!(merged.is_some(), "mergedAt → humanized time");
    }

    /// State 4: a merged PR row missing `mergedAt` still yields the
    /// number — the hint just drops the time.
    #[test]
    fn parse_merged_pr_without_timestamp() {
        let json = r#"[{"number": 43}]"#;
        let (number, merged) = parse_merged_pr_json(json).expect("parses");
        assert_eq!(number, 43);
        assert!(merged.is_none());
    }

    /// No merged PR (empty gh array) → None, so the render path keeps
    /// the "no PR opened yet" hint.
    #[test]
    fn parse_merged_pr_empty_is_none() {
        assert!(parse_merged_pr_json("[]").is_none());
    }
}

/// BUG-229: the in-flight display state for a branch with an open PR —
/// one variant per drain-pipeline stage. Derived purely from the three
/// signals the render path already gathers (`gh reviewDecision`, the
/// local review state, the CI probe) so the mapping is unit-testable
/// without spawning `gh`. trace:BUG-229 | ai:claude
#[derive(Debug, PartialEq)]
enum InFlightPrDisplay {
    /// gh `reviewDecision` == APPROVED — review done, awaiting merge.
    ReviewApproved { approver: Option<String> },
    /// A reviewer session lease owns the PR — review running now.
    UnderReviewLease { session_id: String, since: String },
    /// An In-Progress `Review PR-N:` story — a reviewer picked it up
    /// without a PR-scoped session.
    UnderReviewStory { story_id: String },
    /// PR open, no review started yet, CI still running — the
    /// orchestrator is in its CI-wait window; "start review" would be
    /// premature.
    CiRunning,
    /// PR open, no review started, CI not blocking — ready for a
    /// reviewer to pick up.
    AwaitingReview,
}

/// BUG-229: map the three already-probed signals onto an
/// [`InFlightPrDisplay`] stage. Pure — no `gh`, no `git` — so the full
/// drain-pipeline matrix is unit-testable from synthesized inputs.
///
/// Precedence mirrors the pipeline: an APPROVED `reviewDecision` is the
/// authoritative "safe to merge" signal and supersedes a lingering
/// reviewer lease; an active reviewer lease / story means review is
/// running; only when no review has started does the CI probe decide
/// between "CI still running" and "ready for review".
/// trace:BUG-229 | ai:claude
fn classify_open_pr_display(
    approved: Option<PrReviewDecision>,
    local_state: LocalReviewState,
    ci: &CiProbe,
) -> InFlightPrDisplay {
    if let Some(d) = approved {
        if d.decision == "APPROVED" {
            return InFlightPrDisplay::ReviewApproved {
                approver: d.approver,
            };
        }
    }
    match local_state {
        LocalReviewState::InProgressLease { session_id, since } => {
            InFlightPrDisplay::UnderReviewLease { session_id, since }
        }
        LocalReviewState::InProgressStory { story_id } => {
            InFlightPrDisplay::UnderReviewStory { story_id }
        }
        LocalReviewState::NotStarted => {
            if matches!(ci, CiProbe::InProgress { .. }) {
                InFlightPrDisplay::CiRunning
            } else {
                InFlightPrDisplay::AwaitingReview
            }
        }
    }
}

/// BUG-229: the open-PR display matrix — `classify_open_pr_display` maps
/// the three drain-pipeline signals onto one [`InFlightPrDisplay`] stage
/// per row of the spec's state machine. Synthesized inputs, no `gh` /
/// `git`. trace:BUG-229 | ai:claude
#[cfg(test)]
mod bug_229_display_matrix_tests {
    use super::*;

    fn approved_decision(login: Option<&str>) -> PrReviewDecision {
        PrReviewDecision {
            decision: "APPROVED".to_string(),
            approver: login.map(|s| s.to_string()),
        }
    }

    /// PR open, CI still running, no review started → CI-running stage,
    /// so the row says "wait for CI" instead of a premature "start
    /// review" (the orchestrator's CI-wait window).
    #[test]
    fn open_pr_ci_running() {
        let d = classify_open_pr_display(
            None,
            LocalReviewState::NotStarted,
            &CiProbe::InProgress { pr_number: 71 },
        );
        assert_eq!(d, InFlightPrDisplay::CiRunning);
    }

    /// PR open, CI finished (green / no-checks / no-signal), no review
    /// started → ready for a reviewer to pick up.
    #[test]
    fn open_pr_ci_done_awaits_review() {
        for ci in [
            CiProbe::Green { pr_number: 71 },
            CiProbe::PrNoChecks { pr_number: 71 },
            CiProbe::NoSignal(String::new()),
        ] {
            assert_eq!(
                classify_open_pr_display(None, LocalReviewState::NotStarted, &ci),
                InFlightPrDisplay::AwaitingReview,
            );
        }
    }

    /// PR open, a reviewer session lease owns it → under-review stage.
    /// A still-running CI probe does not override an active lease.
    #[test]
    fn open_pr_under_review_by_lease() {
        let d = classify_open_pr_display(
            None,
            LocalReviewState::InProgressLease {
                session_id: "abc12345".to_string(),
                since: "30m ago".to_string(),
            },
            &CiProbe::InProgress { pr_number: 71 },
        );
        assert_eq!(
            d,
            InFlightPrDisplay::UnderReviewLease {
                session_id: "abc12345".to_string(),
                since: "30m ago".to_string(),
            }
        );
    }

    /// PR open, an In-Progress `Review PR-N:` story (no PR-scoped
    /// session) → under-review stage.
    #[test]
    fn open_pr_under_review_by_story() {
        let d = classify_open_pr_display(
            None,
            LocalReviewState::InProgressStory {
                story_id: "STORY-9".to_string(),
            },
            &CiProbe::NoSignal(String::new()),
        );
        assert_eq!(
            d,
            InFlightPrDisplay::UnderReviewStory {
                story_id: "STORY-9".to_string()
            }
        );
    }

    /// PR open, review complete (gh `reviewDecision` APPROVED) →
    /// review-complete stage, carrying the approver login.
    #[test]
    fn open_pr_review_approved() {
        let d = classify_open_pr_display(
            Some(approved_decision(Some("octocat"))),
            LocalReviewState::NotStarted,
            &CiProbe::NoSignal(String::new()),
        );
        assert_eq!(
            d,
            InFlightPrDisplay::ReviewApproved {
                approver: Some("octocat".to_string())
            }
        );
    }

    /// An APPROVED decision is authoritative — it supersedes a reviewer
    /// lease still on disk (a lingering session after approval).
    #[test]
    fn approved_supersedes_lingering_lease() {
        let d = classify_open_pr_display(
            Some(approved_decision(None)),
            LocalReviewState::InProgressLease {
                session_id: "abc12345".to_string(),
                since: "1h ago".to_string(),
            },
            &CiProbe::NoSignal(String::new()),
        );
        assert_eq!(d, InFlightPrDisplay::ReviewApproved { approver: None });
    }
}

/// TASK-234: render the "Done — awaiting merge" body grouped by PR +
/// state instead of as a flat list. [`classify_in_flight_specs`] does
/// the git-only bucketing; this adds the `gh` PR-state lookups and
/// prints each bucket with a concrete `▶ Next` action.
///
/// BUG-366: the "start review" hint must name a command that survives an
/// operator's reflexive flags. Bare `aida queue work PR-N` resolves to the
/// review story (TASK-85), but operators habitually append implementer-drain
/// flags (`--auto-complete --no-human`) — and the auto-complete preflight
/// can't resolve a PR number into a spec. Naming `--for reviewer` makes the
/// reviewer intent explicit so the implementer-drain flags don't get bolted
/// on to a review pickup. trace:BUG-366 | ai:claude
fn review_pickup_hint(pr_number: u64) -> String {
    format!("aida queue work PR-{pr_number} --for reviewer")
}

/// TASK-250: each open-PR branch is sub-classified into one of four
/// PR-lifecycle states — review not started / in progress / approved /
/// merged-awaiting-pull — so the next-action hint matches reality
/// instead of a blanket "merge PR-N". trace:TASK-234 TASK-250 | ai:claude
fn render_in_flight_grouped(
    specs: &[&aida_core::Requirement],
    all_reqs: &[aida_core::Requirement],
    project_root: &std::path::Path,
) {
    let InFlightBuckets {
        stuck,
        awaiting,
        no_commit,
    } = classify_in_flight_specs(specs, project_root);

    // ---- Awaiting merge, grouped by branch ----
    // TASK-250: an open-PR branch is sub-classified into State 1/2/3
    // (review not started / in progress / approved); a branch with no
    // open PR is checked for a merged PR (State 4) before falling back
    // to the "no PR opened yet" hint. trace:TASK-250 | ai:claude
    for (branch, ids) in &awaiting {
        let count = ids.len();
        let plural = if count == 1 { "" } else { "s" };
        let ids_line = ids
            .iter()
            .map(|s| s.as_str())
            .collect::<Vec<_>>()
            .join("  ");

        // STORY-516: forge-routed; reconstruct OpenPrInfo so the Found block is
        // unchanged. The `_` arm already covers every non-Found state.
        // trace:STORY-516 | ai:claude
        match change_lookup_for_branch(project_root, branch) {
            crate::forge::ChangeLookup::Found(c) => {
                let pr = OpenPrInfo {
                    number: c.id,
                    title: c.title.unwrap_or_default(),
                    url: c.url,
                };
                println!(
                    "  {} {} — {} spec{}:",
                    format!("PR-{}", pr.number).cyan().bold(),
                    "(open)".dimmed(),
                    count,
                    plural
                );
                println!("    {} {}", "◐".bright_green(), ids_line);

                // BUG-229: gather the three drain-pipeline signals, then
                // let `classify_open_pr_display` pick the stage. gh's
                // `reviewDecision` (State: approved) is the authoritative
                // "safe to merge" signal and supersedes a lingering
                // reviewer lease. The CI probe is only consulted when no
                // review has started — an extra `gh` round-trip we skip
                // once a lease / APPROVED decision already settles the
                // stage. trace:BUG-229 | ai:claude
                let approved = detect_pr_review_decision(project_root, pr.number)
                    .filter(|d| d.decision == "APPROVED");
                let local_state = detect_local_review_state(project_root, all_reqs, pr.number);
                let ci =
                    if approved.is_none() && matches!(local_state, LocalReviewState::NotStarted) {
                        ci_probe_via_forge(branch) // STORY-516: forge-routed
                    } else {
                        CiProbe::NoSignal(String::new())
                    };
                match classify_open_pr_display(approved, local_state, &ci) {
                    InFlightPrDisplay::ReviewApproved { approver } => {
                        let by = approver.map(|a| format!(" by {}", a)).unwrap_or_default();
                        println!(
                            "    {} Review complete{}, awaiting merge — Next: merge (`{}`)",
                            "▶".bold(),
                            by,
                            format!("gh pr merge {} --squash", pr.number).cyan()
                        );
                    }
                    InFlightPrDisplay::UnderReviewLease { session_id, since } => println!(
                        "    {} {}",
                        "⏳".yellow(),
                        format!(
                            "Under review (reviewer session {} since {})",
                            session_id, since
                        )
                        .yellow()
                    ),
                    InFlightPrDisplay::UnderReviewStory { story_id } => println!(
                        "    {} {}",
                        "⏳".yellow(),
                        format!("Under review (review story {})", story_id).yellow()
                    ),
                    InFlightPrDisplay::CiRunning => println!(
                        "    {} {}",
                        "◐".yellow(),
                        "CI running — Next: wait for CI to finish, then review".yellow()
                    ),
                    InFlightPrDisplay::AwaitingReview => println!(
                        "    {} start review (`{}`)",
                        "▶ Next:".bold(),
                        review_pickup_hint(pr.number).cyan()
                    ),
                }
            }
            _ => {
                // No open PR for this branch. Either it merged and the
                // local clone hasn't pulled yet (State 4), or no PR was
                // ever opened.
                match detect_merged_pr_with_time(project_root, branch) {
                    Some((number, merged_at)) => {
                        println!(
                            "  {} {} — {} spec{}:",
                            format!("PR-{}", number).cyan().bold(),
                            "(merged)".dimmed(),
                            count,
                            plural
                        );
                        println!("    {} {}", "◐".bright_green(), ids_line);
                        let when = merged_at
                            .map(|t| format!("Merged {}", t))
                            .unwrap_or_else(|| "Merged".to_string());
                        println!(
                            "    {} {} — Next: `{}` (auto-bumps {} spec{} to Completed)",
                            "▶".bold(),
                            when,
                            "aida pull".cyan(),
                            count,
                            plural
                        );
                    }
                    None => {
                        println!(
                            "  {} {} — {} spec{}:",
                            branch.cyan().bold(),
                            "(no PR opened yet)".dimmed(),
                            count,
                            plural
                        );
                        println!("    {} {}", "◐".bright_green(), ids_line);
                        println!(
                            "    {} open a PR (`{}`), then merge → `{}`",
                            "▶ Next:".bold(),
                            "/aida-pr".cyan(),
                            "aida pull".cyan()
                        );
                    }
                }
            }
        }
    }

    // ---- Stuck — auto-bump missed ----
    if !stuck.is_empty() {
        if !awaiting.is_empty() {
            println!();
        }
        println!(
            "  {} ({} spec{}):",
            "Stuck — PR merged, auto-bump missed".yellow().bold(),
            stuck.len(),
            if stuck.len() == 1 { "" } else { "s" }
        );
        for (id, pr, ago) in &stuck {
            let pr_note = pr
                .map(|n| format!("(#{}, {})", n, ago))
                .unwrap_or_else(|| format!("(merged {})", ago));
            println!("    {} {}  {}", "◐".yellow(), id.bold(), pr_note.dimmed());
        }
        println!(
            "    {} `{}` replays the missed bumps to Completed",
            "▶ Next:".bold(),
            "aida db reconcile-status".cyan()
        );
    }

    // ---- Awaiting commit ----
    if !no_commit.is_empty() {
        if !awaiting.is_empty() || !stuck.is_empty() {
            println!();
        }
        println!(
            "  {} ({} spec{}):",
            "Awaiting commit — no commit references the spec yet"
                .dimmed()
                .bold(),
            no_commit.len(),
            if no_commit.len() == 1 { "" } else { "s" }
        );
        println!("    {} {}", "◐".dimmed(), no_commit.join("  "));
        // TASK-671: name the real SPEC-ID (it's the payload the user must type
        // into the commit trailer — an allowed user-facing id use per TASK-268),
        // be remote-aware (no "open a PR" for a local-only project with no
        // origin), and show a literal commit example so the trailer isn't
        // dropped — the exact mistake that strands a spec in this state.
        // trace:TASK-671 | ai:claude
        let has_origin = aida_core::git_ops::has_remote(project_root, "origin");
        if no_commit.len() == 1 {
            let id = &no_commit[0];
            if has_origin {
                println!(
                    "    {} commit your change with `({})` in the message, then open a PR — the merge auto-completes it.",
                    "▶ Next:".bold(),
                    id.cyan()
                );
            } else {
                println!(
                    "    {} commit your change with `({})` in the message — that auto-completes it on the next `{}`.",
                    "▶ Next:".bold(),
                    id.cyan(),
                    "aida pull".cyan()
                );
            }
            println!(
                "            e.g.  {}",
                format!("git commit -m \"... ({})\"", id).dimmed()
            );
        } else {
            if has_origin {
                println!(
                    "    {} commit each with its own `({})` trailer in the message, then open a PR — the merge auto-completes each.",
                    "▶ Next:".bold(),
                    "SPEC-ID".cyan()
                );
            } else {
                println!(
                    "    {} commit each with its own `({})` trailer — that auto-completes each on the next `{}`.",
                    "▶ Next:".bold(),
                    "SPEC-ID".cyan(),
                    "aida pull".cyan()
                );
            }
            println!(
                "            e.g.  {}",
                "git commit -m \"... (SPEC-ID)\"".dimmed()
            );
        }
    }
}

/// TASK-241: surface git linkage for a spec inside `aida show` — the
/// commits that reference it (AIDA commit format puts `(SPEC-ID)` in
/// the message), the files carrying its `trace:` comments, the branch +
/// worktree the work lives on, and PR state. Every sub-probe is
/// best-effort: a missing `gh`, an absent `origin/main`, or zero
/// matches degrades to a dim note rather than failing the show.
/// `--no-git` skips the whole section; `--verbose` un-caps the commit
/// list and adds per-commit diff stats. trace:TASK-241 | ai:claude
/// Resolve a refname for the default branch that is **known to exist**
/// in `project_root`, so callers can pass it to `git merge-base
/// --is-ancestor` without risking a `fatal: Not a valid object name <X>`
/// stderr splice when the repo's default branch is not `main`.
///
/// Resolution order:
///   1. `origin/HEAD` symbolic ref (the actual default branch on origin)
///   2. `init.defaultBranch` config — `origin/<name>` then bare `<name>`
///   3. The `"main"` / `"master"` literals — `origin/<name>` then bare
///
/// Returns `None` when no candidate ref exists; callers should then
/// skip the ancestor check rather than guess (the prior code passed
/// `"main"` as a literal, which leaked stderr on master-default repos).
/// trace:BUG-380 | ai:claude
fn resolve_default_branch_ref(project_root: &std::path::Path) -> Option<String> {
    use std::process::Command as PCmd;
    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim_end().to_string())
            .filter(|s| !s.is_empty())
    };

    if let Some(short) = git(&[
        "symbolic-ref",
        "--quiet",
        "--short",
        "refs/remotes/origin/HEAD",
    ]) {
        return Some(short);
    }

    let mut candidates: Vec<String> = Vec::new();
    if let Some(cfg) = git(&["config", "--get", "init.defaultBranch"]) {
        candidates.push(cfg);
    }
    for lit in ["main", "master"] {
        if !candidates.iter().any(|c| c == lit) {
            candidates.push(lit.to_string());
        }
    }

    for name in candidates {
        let origin = format!("origin/{}", name);
        if git(&["rev-parse", "--verify", "--quiet", &origin]).is_some() {
            return Some(origin);
        }
        if git(&["rev-parse", "--verify", "--quiet", &name]).is_some() {
            return Some(name);
        }
    }
    None
}

/// TASK-241: the git-linkage data for a spec — extracted from
/// [`print_git_linkage`] so the collection (git-only, never gh) is
/// unit-testable against a temp repo. trace:TASK-241 | ai:claude
struct GitLinkage {
    /// (full_sha, short_sha, subject), newest first.
    commits: Vec<(String, String, String)>,
    /// (file, symbol) per trace comment — deduped and sorted.
    files: Vec<(String, Option<String>)>,
    /// The newest referencing commit is an ancestor of main.
    shipped: bool,
    /// Feature branch holding the work (in-flight case only).
    branch: Option<String>,
    /// Worktree path checked out at `branch`, if any.
    worktree: Option<String>,
    /// PR number parsed from a squash-merge subject (shipped case only).
    shipped_pr: Option<u64>,
}

/// TASK-241: collect the git linkage for `ids` — commits referencing the
/// AIDA `(SPEC-ID)` format, files carrying `trace:` comments, and
/// branch/worktree/shipped state. gh-free by design: the in-flight
/// open-PR lookup happens later, in [`print_git_linkage`].
/// trace:TASK-241 | ai:claude
fn collect_git_linkage(project_root: &std::path::Path, ids: &[String]) -> GitLinkage {
    use std::process::Command as PCmd;

    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim_end().to_string())
    };
    // BUG-380: capture stderr via output() so an invalid `target` ref
    // cannot leak `fatal: Not a valid object name <X>` to the user's
    // terminal — belt-and-braces alongside `resolve_default_branch_ref`,
    // which already filters `target` to a ref that exists.
    let is_ancestor = |sha: &str, target: &str| -> bool {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(["merge-base", "--is-ancestor", sha, target])
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
    };

    // ---- Commits referencing the spec (across all refs) ----
    // Match the AIDA commit format `(SPEC-ID)` as a fixed string: the
    // parens exclude the orphan `aida-store` branch's bookkeeping
    // commits ("update TASK-92"), which mention the bare id.
    let patterns: Vec<String> = ids.iter().map(|id| format!("({})", id)).collect();
    let mut args: Vec<&str> = vec![
        "log",
        "--all",
        "-F",
        "--date-order",
        "--pretty=format:%H\u{1f}%h\u{1f}%s",
    ];
    for p in &patterns {
        args.push("--grep");
        args.push(p.as_str());
    }
    let log = git(&args).unwrap_or_default();
    let commits: Vec<(String, String, String)> = log
        .lines()
        .filter_map(|l| {
            let mut p = l.splitn(3, '\u{1f}');
            Some((
                p.next()?.to_string(),
                p.next()?.to_string(),
                p.next()?.to_string(),
            ))
        })
        .collect();

    // ---- Files carrying trace comments for the spec ----
    let wanted: HashSet<String> = ids.iter().cloned().collect();
    let trace_hits = scan_trace_graph(project_root, &wanted);
    let mut files: Vec<(String, Option<String>)> = trace_hits
        .values()
        .flatten()
        .map(|h| (h.file.clone(), h.symbol.clone()))
        .collect();
    files.sort();
    files.dedup();

    // ---- Branch / worktree / shipped state (anchored on newest commit) ----
    let mut shipped = false;
    let mut branch: Option<String> = None;
    let mut worktree: Option<String> = None;
    let mut shipped_pr: Option<u64> = None;
    if let Some((full, _, _)) = commits.first() {
        // BUG-380: resolve a ref that exists rather than passing a
        // literal "main"; on master-default repos the literal leaks
        // `fatal: Not a valid object name 'main'` from git through
        // is_ancestor's inherited stderr.
        shipped = resolve_default_branch_ref(project_root)
            .map(|main_ref| is_ancestor(full, &main_ref))
            .unwrap_or(false);
        if shipped {
            // A squash-merge subject ends with `(#NN)` — the cheapest,
            // most reliable PR pointer for shipped work.
            shipped_pr = commits
                .iter()
                .find_map(|(_, _, s)| parse_squash_pr_number(s));
        } else {
            // In flight: find the feature branch that holds the work.
            let contains = git(&[
                "branch",
                "--all",
                "--contains",
                full,
                "--format=%(refname:short)",
            ])
            .unwrap_or_default();
            branch = contains
                .lines()
                .map(|b| b.trim().trim_start_matches("origin/"))
                .filter(|b| !b.is_empty() && *b != "HEAD" && *b != "main" && *b != "master")
                .map(|b| b.to_string())
                .next();
            if let (Some(b), Some(wt)) =
                (branch.as_deref(), git(&["worktree", "list", "--porcelain"]))
            {
                let mut cur_path: Option<String> = None;
                for line in wt.lines() {
                    if let Some(p) = line.strip_prefix("worktree ") {
                        cur_path = Some(p.to_string());
                    } else if let Some(r) = line.strip_prefix("branch ") {
                        if r.trim_start_matches("refs/heads/") == b {
                            worktree = cur_path.clone();
                        }
                    }
                }
            }
        }
    }

    GitLinkage {
        commits,
        files,
        shipped,
        branch,
        worktree,
        shipped_pr,
    }
}

fn print_git_linkage(project_root: &std::path::Path, ids: &[String], verbose: bool) {
    use std::process::Command as PCmd;

    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim_end().to_string())
    };

    let GitLinkage {
        commits,
        files,
        shipped,
        branch,
        worktree,
        shipped_pr,
    } = collect_git_linkage(project_root, ids);

    if commits.is_empty() && files.is_empty() {
        println!(
            "\n{}: {}",
            "Git linkage".green().bold(),
            "no commits or trace comments reference this spec yet".dimmed()
        );
        return;
    }

    println!("\n{}:", "Git linkage".green().bold());

    // ---- Branch / worktree / PR (anchored on the newest commit) ----
    if !commits.is_empty() {
        if shipped {
            println!("  {}     {}", "Branch".bold(), "merged to main".green());
            if let Some(num) = shipped_pr {
                println!("  {}         {}", "PR".bold(), format!("PR-{}", num).cyan());
            }
        } else {
            match branch.as_deref() {
                Some(b) => {
                    let wt = worktree
                        .map(|p| format!(" (worktree: {})", p))
                        .unwrap_or_default();
                    println!(
                        "  {}     {}{} · {}",
                        "Branch".bold(),
                        b.cyan(),
                        wt,
                        "in flight".yellow()
                    );
                    // STORY-516: forge-routed. trace:STORY-516 | ai:claude
                    match change_lookup_for_branch(project_root, b) {
                        crate::forge::ChangeLookup::Found(c) => println!(
                            "  {}         {} {}",
                            "PR".bold(),
                            format!("PR-{}", c.id).cyan(),
                            c.url.dimmed()
                        ),
                        crate::forge::ChangeLookup::NoChange => {
                            println!("  {}         {}", "PR".bold(), "no PR opened yet".dimmed())
                        }
                        crate::forge::ChangeLookup::CliMissing => println!(
                            "  {}         {}",
                            "PR".bold(),
                            "gh not installed — PR state unknown".dimmed()
                        ),
                        crate::forge::ChangeLookup::CliFailed(_) => println!(
                            "  {}         {}",
                            "PR".bold(),
                            "gh lookup failed — PR state unknown".dimmed()
                        ),
                        crate::forge::ChangeLookup::Unreachable(_) => println!(
                            "  {}         {}",
                            "PR".bold(),
                            "GH API unreachable — PR state unknown (transient)".dimmed()
                        ),
                    }
                }
                None => println!(
                    "  {}     {}",
                    "Branch".bold(),
                    "work committed but branch not found locally".yellow()
                ),
            }
        }
    }

    // ---- Commits list ----
    if !commits.is_empty() {
        let cap = if verbose {
            commits.len()
        } else {
            5.min(commits.len())
        };
        println!(
            "  {} ({}{})",
            "Commits".bold(),
            commits.len(),
            if !verbose && commits.len() > cap {
                format!(", showing {}", cap)
            } else {
                String::new()
            }
        );
        for (full, short, subject) in commits.iter().take(cap) {
            println!("    {} {}", short.yellow(), subject);
            if verbose {
                if let Some(stat) =
                    git(&["show", "--shortstat", "--format=", full]).filter(|s| !s.is_empty())
                {
                    if let Some(last) = stat.lines().last() {
                        println!("      {}", last.trim().dimmed());
                    }
                }
            }
        }
        if !verbose && commits.len() > cap {
            println!(
                "    {}",
                format!("… {} more (--verbose to expand)", commits.len() - cap).dimmed()
            );
        }
    }

    // ---- Files traced ----
    if !files.is_empty() {
        println!("  {} ({})", "Files traced".bold(), files.len());
        for (file, symbol) in &files {
            match symbol {
                Some(sym) => println!("    {} — {}", file, sym.dimmed()),
                None => println!("    {}", file),
            }
        }
    }
}

/// `aida plan helpers <spec>` — render a `## Reusable helpers` section
/// derived from the trace graph. trace:TASK-94 | ai:claude
fn plan_helpers(spec_arg: &str, append: Option<&std::path::Path>) -> Result<()> {
    let project_root = find_project_root()?;
    let store = load_store_for_lookup(&project_root)
        .ok_or_else(|| anyhow::anyhow!("could not load the AIDA requirements store"))?;
    let target = if let Ok(uuid) = uuid::Uuid::parse_str(spec_arg) {
        store.requirements.iter().find(|r| r.id == uuid)
    } else {
        store.get_requirement_by_spec_id(spec_arg)
    }
    .ok_or_else(|| anyhow::anyhow!("requirement `{spec_arg}` not found"))?;
    let target_display = target.display_id();

    let Some(mut md) = build_reusable_helpers_section(&store, &project_root, target) else {
        println!(
            "No reusable helpers derived for {target_display} — no related spec (sibling / \
             tag-mate / same-feature) carries a `trace:` comment that names a helper."
        );
        return Ok(());
    };
    md.push_str(&format!(
        "\n_Generated by `aida plan helpers {target_display}` — verify before relying on it._\n"
    ));

    if let Some(path) = append {
        let mut existing = std::fs::read_to_string(path)
            .with_context(|| format!("could not read plan file {}", path.display()))?;
        if !existing.ends_with('\n') {
            existing.push('\n');
        }
        existing.push('\n');
        existing.push_str(&md);
        std::fs::write(path, existing)
            .with_context(|| format!("could not write {}", path.display()))?;
        println!(
            "{} appended Reusable helpers section to {}",
            "✓".green(),
            path.display()
        );
    } else {
        print!("{md}");
    }
    Ok(())
}

/// Build the `## Reusable helpers` markdown section for `target` by walking
/// the requirement graph (siblings / tag-mates / same-feature specs) and
/// harvesting their `trace:` comments. Returns `None` when no related spec
/// contributes a named helper. Shared by `aida plan helpers` and the
/// `aida ultraplan` prompt assembler. trace:TASK-94 TASK-113 | ai:claude
fn build_reusable_helpers_section(
    store: &aida_core::RequirementsStore,
    project_root: &std::path::Path,
    target: &aida_core::models::Requirement,
) -> Option<String> {
    // ── Related-spec discovery ── first reason wins (sibling beats
    // feature beats tag) so each spec appears once with its strongest tie.
    let parent_uuids: Vec<uuid::Uuid> = target
        .relationships
        .iter()
        .filter(|r| r.rel_type == aida_core::RelationshipType::Child)
        .map(|r| r.target_id)
        .collect();
    let target_feature = target.feature.trim().to_string();
    let target_tags = target.tags.clone();

    let mut related: Vec<(&aida_core::models::Requirement, &'static str)> = Vec::new();
    let mut seen: HashSet<uuid::Uuid> = HashSet::new();
    seen.insert(target.id);

    if !parent_uuids.is_empty() {
        for req in &store.requirements {
            if seen.contains(&req.id) {
                continue;
            }
            let is_sibling = req.relationships.iter().any(|r| {
                r.rel_type == aida_core::RelationshipType::Child
                    && parent_uuids.contains(&r.target_id)
            });
            if is_sibling {
                seen.insert(req.id);
                related.push((req, "sibling"));
            }
        }
    }
    // Shared tags before feature: a shared tag is a deliberate grouping
    // (a `batch:`, a topic) and a stronger signal than `feature`, which
    // is often a coarse project-wide bucket.
    if !target_tags.is_empty() {
        for req in &store.requirements {
            if seen.contains(&req.id) {
                continue;
            }
            if req.tags.iter().any(|t| target_tags.contains(t)) {
                seen.insert(req.id);
                related.push((req, "shared tag"));
            }
        }
    }
    if !target_feature.is_empty() {
        let feature_matches: Vec<&aida_core::models::Requirement> = store
            .requirements
            .iter()
            .filter(|r| !seen.contains(&r.id) && r.feature.trim() == target_feature)
            .collect();
        // A feature shared by dozens of specs is a project-wide bucket,
        // not a meaningful relation — skip it rather than flood the
        // section with weakly-related noise.
        const FEATURE_DISCRIMINATION_CAP: usize = 25;
        if feature_matches.len() <= FEATURE_DISCRIMINATION_CAP {
            for req in feature_matches {
                seen.insert(req.id);
                related.push((req, "same feature"));
            }
        }
    }

    let target_display = target.display_id();
    if related.is_empty() {
        return None;
    }

    // Every id-string a trace comment might use (canonical spec_id or the
    // agreed short id) → index into `related`.
    let mut id_to_idx: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for (idx, (req, _)) in related.iter().enumerate() {
        if let Some(s) = &req.spec_id {
            id_to_idx.insert(s.clone(), idx);
        }
        if let Some(a) = &req.agreed_id {
            id_to_idx.insert(a.clone(), idx);
        }
    }
    let wanted: HashSet<String> = id_to_idx.keys().cloned().collect();

    let hits = scan_trace_graph(&project_root, &wanted);

    // Fold hits onto each related spec, deduped by (file, symbol).
    let mut per_spec: Vec<(usize, std::collections::BTreeMap<String, Vec<String>>)> = Vec::new();
    for (idx, _) in related.iter().enumerate() {
        per_spec.push((idx, std::collections::BTreeMap::new()));
    }
    for (id, id_hits) in &hits {
        let Some(&idx) = id_to_idx.get(id) else {
            continue;
        };
        let by_file = &mut per_spec[idx].1;
        for hit in id_hits {
            let syms = by_file.entry(hit.file.clone()).or_default();
            if let Some(sym) = &hit.symbol {
                if !syms.contains(sym) {
                    syms.push(sym.clone());
                }
            }
        }
    }

    // Keep only specs that introduce at least one *named* helper — the
    // section is "reusable helpers", and a bare file-touched hit (every
    // spec touches main.rs) carries no reuse signal. Rank by tier
    // (siblings are the closest relatives, then tag-mates, then the
    // coarse same-feature set) and within a tier by helper count, then
    // cap so the section stays a focused brief.
    const HELPERS_SPEC_CAP: usize = 12;
    const HELPERS_PER_FILE_CAP: usize = 8;
    let tier = |reason: &str| -> u8 {
        match reason {
            "sibling" => 0,
            "shared tag" => 1,
            _ => 2, // same feature — project-wide, weakest signal
        }
    };
    let mut ranked: Vec<(usize, u8, usize)> = per_spec
        .iter()
        .filter_map(|(idx, by_file)| {
            let symbols: usize = by_file.values().map(Vec::len).sum();
            (symbols > 0).then_some((*idx, tier(related[*idx].1), symbols))
        })
        .collect();
    ranked.sort_by(|a, b| a.1.cmp(&b.1).then(b.2.cmp(&a.2)).then(a.0.cmp(&b.0)));
    let truncated = ranked.len().saturating_sub(HELPERS_SPEC_CAP);
    ranked.truncate(HELPERS_SPEC_CAP);

    // No related spec names a helper → nothing worth a section.
    if ranked.is_empty() {
        return None;
    }

    // ── Render the section ──
    let mut md = String::new();
    md.push_str("## Reusable helpers (do not reimplement)\n\n");
    md.push_str(&format!(
        "Derived from the trace graph for {target_display} — related specs that already \
         touch this area. Call these rather than re-implementing.\n\n"
    ));

    for (idx, _, _) in &ranked {
        let (req, reason) = related[*idx];
        let by_file = &per_spec[*idx].1;
        md.push_str(&format!(
            "**{}** — {} · {} · {}\n\n",
            req.display_id(),
            req.title,
            reason,
            req.status
        ));
        for (file, syms) in by_file {
            if syms.is_empty() {
                md.push_str(&format!("- `{file}`\n"));
            } else {
                let mut sorted = syms.clone();
                sorted.sort();
                let extra = sorted.len().saturating_sub(HELPERS_PER_FILE_CAP);
                sorted.truncate(HELPERS_PER_FILE_CAP);
                let mut joined = sorted
                    .iter()
                    .map(|s| format!("`{s}`"))
                    .collect::<Vec<_>>()
                    .join(", ");
                if extra > 0 {
                    joined.push_str(&format!(", …+{extra}"));
                }
                md.push_str(&format!("- `{file}` — {joined}\n"));
            }
        }
        md.push('\n');
    }
    if truncated > 0 {
        md.push_str(&format!(
            "_…and {truncated} more related spec(s) — narrow the scope or inspect with \
             `aida list`._\n"
        ));
    }
    Some(md)
}

// ============================================================================
// TASK-113 — `aida ultraplan <SPEC>`. Assemble a rich, structured planning
// prompt from a spec's full context (description, acceptance, related specs,
// the AIDA plan template, trace-graph reusable helpers) so `/ultraplan`'s
// explorers anchor on concrete requirements instead of a terse user prompt.
// trace:TASK-113 | ai:claude
// ============================================================================

/// Copy `text` to the system clipboard, trying the platform tools in turn.
/// Returns false when none is available (caller falls back to stdout).
fn copy_to_clipboard(text: &str) -> bool {
    use std::io::Write;
    use std::process::{Command, Stdio};
    // Linux (Wayland then X11), macOS, Windows.
    let tools: &[(&str, &[&str])] = &[
        ("wl-copy", &[]),
        ("xclip", &["-selection", "clipboard"]),
        ("xsel", &["--clipboard", "--input"]),
        ("pbcopy", &[]),
        ("clip", &[]),
    ];
    for (cmd, args) in tools {
        let Ok(mut child) = Command::new(cmd)
            .args(*args)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        else {
            continue;
        };
        let write_ok = match child.stdin.take() {
            Some(mut stdin) => stdin.write_all(text.as_bytes()).is_ok(),
            None => false,
        };
        // stdin dropped above → EOF; now wait for the tool to finish.
        match child.wait() {
            Ok(status) if write_ok && status.success() => return true,
            _ => continue,
        }
    }
    false
}

// ────────────────────────────────────────────────────────────────────
// TASK-242: `aida goal` — derive machine-checkable completion conditions
// from AIDA metadata for /goal, /schedule, and autonomous-mode runs.
// trace:TASK-242 | ai:claude
// ────────────────────────────────────────────────────────────────────

/// One clause of a `/goal` completion condition: a human-readable
/// statement plus an explicit, deterministic command to verify it.
struct GoalClause {
    description: String,
    verify: String,
}

/// Build the ordered list of `GoalClause`s from the `aida goal` flags.
/// Pure — no store/IO — so the condition vocabulary is unit-testable.
/// Bails when no condition flag is given. trace:TASK-242 | ai:claude
fn build_goal_clauses(
    batch: Option<&str>,
    epic: Option<&str>,
    spec: Option<&str>,
    pr: Option<u64>,
    queue_empty: Option<&str>,
) -> Result<Vec<GoalClause>> {
    let mut clauses: Vec<GoalClause> = Vec::new();

    if let Some(name) = batch {
        let name = name.strip_prefix("batch:").unwrap_or(name);
        clauses.push(GoalClause {
            description: format!(
                "all specs tagged `batch:{}` are resolved (Completed or Rejected)",
                name
            ),
            verify: format!("`aida list --tags batch:{}` returns no rows", name),
        });
    }
    if let Some(id) = epic {
        clauses.push(GoalClause {
            description: format!(
                "all direct children of {} are resolved (Completed or Rejected)",
                id
            ),
            verify: format!("`aida list --parent {}` returns no rows", id),
        });
    }
    if let Some(id) = spec {
        clauses.push(GoalClause {
            description: format!("spec {} is status Completed", id),
            verify: format!("`aida show {}` reports `Status: Completed`", id),
        });
    }
    if let Some(n) = pr {
        clauses.push(GoalClause {
            description: format!("PR #{} is merged", n),
            verify: format!(
                "`gh pr view {} --json state --jq .state` prints `MERGED`",
                n
            ),
        });
    }
    if let Some(role) = queue_empty {
        let role = role.strip_prefix("role:").unwrap_or(role);
        clauses.push(GoalClause {
            description: format!("the {} queue is empty", role),
            verify: format!(
                "`aida queue list --for {} --no-in-flight` shows no queued items",
                role
            ),
        });
    }

    if clauses.is_empty() {
        anyhow::bail!(
            "no condition flags given — pass at least one of \
             --batch / --epic / --spec / --pr / --queue-empty"
        );
    }
    Ok(clauses)
}

/// EPIC-26: launch the AIDA TUI shell. Gated behind the `tui` feature
/// (default-on as of STORY-137) — the `aida tui` subcommand stays visible
/// in `--help` either way, but a binary built without the feature errors
/// clearly instead of half-running.
///
/// STORY-244 added launcher mode. With `--launcher` (or
/// `[tui] mode = "launcher"` in `.aida/config.toml`, the default), the
/// TUI is a dashboard that exits emitting one intent line on the
/// configured fd; without it (and with `mode = "pty-host"`), the legacy
/// STORY-132 PTY-host shell runs.
/// trace:STORY-132 STORY-137 STORY-244 | ai:claude
#[cfg(feature = "tui")]
fn handle_tui_command(
    scope: Option<String>,
    no_recover: bool,
    launcher: bool,
    intent_fd: Option<u32>,
) -> Result<()> {
    let cwd = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
    let cfg = aida_tui::TuiConfig::load(&cwd);
    let use_launcher = launcher || cfg.mode == aida_tui::TuiMode::Launcher;
    if use_launcher {
        aida_tui::run_launcher(aida_tui::LauncherOptions {
            scope,
            intent_fd: intent_fd.unwrap_or(3),
        })
    } else {
        aida_tui::run(aida_tui::TuiOptions { scope, no_recover })
    }
}

/// Stub for binaries built without the `tui` feature.
/// trace:STORY-132 | ai:claude
#[cfg(not(feature = "tui"))]
fn handle_tui_command(
    _scope: Option<String>,
    _no_recover: bool,
    _launcher: bool,
    _intent_fd: Option<u32>,
) -> Result<()> {
    anyhow::bail!(
        "the `aida tui` shell is not compiled into this binary — rebuild \
         aida-cli with the default features (the `tui` feature ships \
         default-on as of STORY-137; a --no-default-features build omits it)"
    )
}

/// Join clauses into a single `/goal`-pasteable condition string. Each
/// clause inlines its verification command so a Haiku-class evaluator
/// can check it deterministically. trace:TASK-242 | ai:claude
fn assemble_goal_condition(clauses: &[GoalClause]) -> String {
    clauses
        .iter()
        .map(|c| format!("{} (verify: {})", c.description, c.verify))
        .collect::<Vec<_>>()
        .join(" AND ")
}

/// `aida goal` handler — emit the condition framed, bare (`--invoke`),
/// or to the clipboard (`--copy`). trace:TASK-242 | ai:claude
fn handle_goal_command(
    batch: Option<&str>,
    epic: Option<&str>,
    spec: Option<&str>,
    pr: Option<u64>,
    queue_empty: Option<&str>,
    copy: bool,
    invoke: bool,
    as_deep_link: bool,
) -> Result<()> {
    let clauses = build_goal_clauses(batch, epic, spec, pr, queue_empty)?;
    let condition = assemble_goal_condition(&clauses);
    let goal_line = format!("/goal {}", condition);

    // --invoke: bare line only, for `$(aida goal --invoke ...)`.
    if invoke {
        println!("{}", goal_line);
        return Ok(());
    }

    // SPIKE-33: emit a claude-cli:// deep link whose `q=` is the assembled
    // /goal line. Opens Claude Code in the current dir with the prompt
    // pre-filled (inert until Enter). trace:SPIKE-33 | ai:claude
    if as_deep_link {
        let cwd = std::env::current_dir().ok();
        let mut link = deep_link::DeepLink::new().with_prompt(&goal_line);
        if let Some(c) = cwd {
            link = link.with_cwd(c);
        }
        let rendered = link.render();
        if rendered.exceeds {
            println!(
                "{} the assembled /goal line exceeds Claude Code's 5000-char URL ceiling — \
                 emitting anyway, but the link may fail to open",
                "⚠".yellow()
            );
        }
        println!("{}", rendered.url);
        return Ok(());
    }

    if copy {
        if copy_to_clipboard(&goal_line) {
            println!(
                "{} copied the /goal condition to the clipboard",
                "✓".green()
            );
        } else {
            println!(
                "{} no clipboard tool found (wl-copy/xclip/xsel/pbcopy/clip) — printing instead",
                "⚠".yellow()
            );
        }
        println!();
        println!("  {}", goal_line.cyan());
        return Ok(());
    }

    // Default: framed output with the per-clause verification recipe.
    println!(
        "{} machine-checkable completion condition ({} clause{}):",
        "▶".green().bold(),
        clauses.len(),
        if clauses.len() == 1 { "" } else { "s" }
    );
    println!();
    println!("  {}", goal_line.cyan());
    println!();
    println!("  {}", "verify each clause:".dimmed());
    for c in &clauses {
        println!("    {} {}", "·".dimmed(), c.verify);
    }
    println!();
    println!(
        "  {}",
        "paste into /goal or /schedule — or re-run with --copy / --invoke".dimmed()
    );
    Ok(())
}

#[cfg(test)]
mod goal_command_tests {
    use super::{assemble_goal_condition, build_goal_clauses};

    #[test]
    fn batch_clause_strips_prefix_and_emits_verify() {
        let c = build_goal_clauses(Some("batch:plan-tooling"), None, None, None, None).unwrap();
        assert_eq!(c.len(), 1);
        assert!(c[0].description.contains("`batch:plan-tooling`"));
        assert!(c[0].verify.contains("aida list --tags batch:plan-tooling"));
        // Bare name (no prefix) behaves identically.
        let c2 = build_goal_clauses(Some("plan-tooling"), None, None, None, None).unwrap();
        assert_eq!(c2[0].verify, c[0].verify);
    }

    #[test]
    fn epic_spec_pr_clauses() {
        let c = build_goal_clauses(None, Some("EPIC-23"), None, None, None).unwrap();
        assert!(c[0].verify.contains("aida list --parent EPIC-23"));

        let c = build_goal_clauses(None, None, Some("TASK-9"), None, None).unwrap();
        assert!(c[0].verify.contains("aida show TASK-9"));

        let c = build_goal_clauses(None, None, None, Some(42), None).unwrap();
        assert!(c[0].verify.contains("gh pr view 42"));
    }

    #[test]
    fn queue_empty_clause_strips_role_prefix() {
        let c = build_goal_clauses(None, None, None, None, Some("role:implementer")).unwrap();
        assert!(c[0].verify.contains("aida queue list --for implementer"));
        let c2 = build_goal_clauses(None, None, None, None, Some("implementer")).unwrap();
        assert_eq!(c2[0].verify, c[0].verify);
    }

    #[test]
    fn multiple_flags_compose_with_and() {
        let clauses = build_goal_clauses(Some("lifecycle"), None, None, Some(30), None).unwrap();
        assert_eq!(clauses.len(), 2);
        let condition = assemble_goal_condition(&clauses);
        assert!(condition.contains(" AND "));
        assert!(condition.contains("batch:lifecycle"));
        assert!(condition.contains("PR #30"));
    }

    #[test]
    fn no_flags_is_an_error() {
        assert!(build_goal_clauses(None, None, None, None, None).is_err());
    }
}

/// The AIDA plan-template section list, inlined into the ultraplan prompt
/// so `/ultraplan`'s output already matches `docs/plans/_TEMPLATE.md`
/// (TASK-92) and `aida plan verify` (TASK-93) passes on the saved plan.
const ULTRAPLAN_STRUCTURE: &str = "\
Produce the plan in AIDA's structured format — a header line with Date / \
Specs / Status / Complexity, then these sections in order:

1. **Approach** — one-paragraph executive summary, plus an ASCII diagram \
where a state machine or control flow would compress prose.
2. **Decisions** — each significant choice resolved, with rationale (not an \
open-questions list).
3. **Files (in build-order)** — symbol-anchored edits per file, ordered so \
each commit builds clean.
4. **Critical Files** — flat list of every must-touch path.
5. **Reusable helpers** — existing helpers to call rather than re-invent \
(seeded below).
6. **Risks + gotchas** — numbered, each with a mitigation.
7. **Tests** — named test functions, not \"add tests\".
8. **Verification** — an executable bash smoke test (positive + negative).
9. **Followups** — out-of-scope items to file as TASKs at completion time.
10. **Related** — builds-on / blocks / see-also links.";

/// One-line summary of a related requirement for the prompt's context block.
fn ultraplan_spec_line(req: &aida_core::models::Requirement) -> String {
    format!("{} — {} [{}]", req.display_id(), req.title, req.status)
}

/// Build the `## Comments` section for the ultraplan prompt — the spec's
/// enrichment comments, most recent first. `None` when the spec has no
/// non-empty comments. Caps both the comment count and the total
/// characters so a spec with a long discussion thread can't blow the
/// prompt budget; the richest planning context (long enrichment
/// comments) is exactly what TASK-247 exists to surface, so the budget
/// is deliberately generous. trace:TASK-247 | ai:claude
fn ultraplan_comments_section(comments: &[aida_core::models::Comment]) -> Option<String> {
    const COMMENT_COUNT_CAP: usize = 20;
    const COMMENTS_CHAR_CAP: usize = 16_000;

    let non_empty = comments
        .iter()
        .filter(|c| !c.content.trim().is_empty())
        .count();
    if non_empty == 0 {
        return None;
    }

    let mut s = String::from(
        "## Comments\n\nPlanning context captured on the spec as comments, most recent first.\n\n",
    );
    let mut used = 0usize;
    let mut shown = 0usize;
    for c in comments.iter().rev() {
        let content = c.content.trim();
        if content.is_empty() {
            continue;
        }
        if shown >= COMMENT_COUNT_CAP || used >= COMMENTS_CHAR_CAP {
            break;
        }
        let reply_note = match c.replies.len() {
            0 => String::new(),
            n => format!(" · {n} repl{}", if n == 1 { "y" } else { "ies" }),
        };
        s.push_str(&format!(
            "### {} · {}{}\n\n",
            c.author,
            c.created_at.format("%Y-%m-%d"),
            reply_note
        ));
        let budget = COMMENTS_CHAR_CAP - used;
        if content.chars().count() > budget {
            let trimmed: String = content.chars().take(budget).collect();
            s.push_str(&trimmed);
            s.push_str("\n\n_(comment truncated to fit the prompt budget)_\n\n");
            used = COMMENTS_CHAR_CAP;
        } else {
            s.push_str(content);
            s.push_str("\n\n");
            used += content.chars().count();
        }
        shown += 1;
    }
    if shown < non_empty {
        s.push_str(&format!(
            "_(+{} older comment(s) omitted to fit the prompt budget)_\n\n",
            non_empty - shown
        ));
    }
    Some(s)
}

/// Assemble the `/ultraplan` prompt for `target`. `helpers_section` is the
/// pre-built trace-graph reusable-helpers markdown (None when there is
/// none — see TASK-94). `include_comments` pulls the spec's enrichment
/// comments into a `## Comments` section (TASK-247). Returns the prompt
/// and any warnings to surface. Pure over its inputs so it is
/// unit-testable. trace:TASK-113 TASK-247 | ai:claude
/// Assemble the rich, ultraplan-grade punt payload (STORY-306) a headless
/// advisor judges. The structured fork fields come from the punted spec's
/// recorded [`AttentionReason`](aida_core::AttentionReason) — what `aida
/// punt` captured — and the `context_markdown` body reuses the `aida
/// ultraplan` machinery (`assemble_ultraplan_prompt` + the trace-graph
/// `build_reusable_helpers_section`), so an advisor with **no session
/// context** has everything the implementer's `/ultraplan` would have.
/// Split out as a deterministic, unit-testable transform — no session, no
/// subprocess. trace:STORY-306 | ai:claude
fn assemble_punt_payload(
    store: &aida_core::RequirementsStore,
    target: &aida_core::models::Requirement,
    project_root: &std::path::Path,
    attention: &aida_core::AttentionReason,
) -> punt::PuntRequest {
    let helpers = build_reusable_helpers_section(store, project_root, target);
    let (reservations, _reservation_warnings) = read_reserved_paths(project_root);
    let (context_markdown, _warnings) =
        assemble_ultraplan_prompt(store, target, helpers.as_deref(), true, &reservations);
    punt::PuntRequest {
        spec: target.display_id(),
        category: attention.category,
        question: attention.detail.clone(),
        // `aida punt` records the fork as free-form `detail` + `lean`; it
        // does not enumerate options / code-area / stakes separately, so
        // those structured fields stay empty until a future punt does.
        options: Vec::new(),
        code_area: None,
        stakes: None,
        lean: attention.lean.clone(),
        context_markdown,
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ReservedPath {
    path: String,
    reason: String,
}

#[derive(Debug, Default, Deserialize)]
struct ReservedPathsFile {
    #[serde(default)]
    reservations: Vec<ReservedPath>,
}

fn read_reserved_paths(project_root: &std::path::Path) -> (Vec<ReservedPath>, Vec<String>) {
    let path = project_root.join(".aida").join("reserved-paths.toml");
    let Ok(body) = std::fs::read_to_string(&path) else {
        return (
            Vec::new(),
            vec![format!(
                "{} not found — reserved namespace guidance omitted",
                path.display()
            )],
        );
    };

    match toml::from_str::<ReservedPathsFile>(&body) {
        Ok(parsed) => (parsed.reservations, Vec::new()),
        Err(err) => (
            Vec::new(),
            vec![format!(
                "failed to parse {} — reserved namespace guidance omitted: {err}",
                path.display()
            )],
        ),
    }
}

fn reserved_paths_section(reservations: &[ReservedPath]) -> Option<String> {
    if reservations.is_empty() {
        return None;
    }

    let mut out = String::from("## Reserved namespaces and conventions\n\n");
    out.push_str(
        "Before proposing new files, check these project-reserved paths and avoid \
         collisions unless the plan explicitly updates the owning convention.\n\n",
    );
    for reservation in reservations {
        out.push_str(&format!(
            "- `{}` — {}\n",
            reservation.path.trim(),
            reservation.reason.trim()
        ));
    }
    out.push('\n');
    Some(out)
}

fn ultraplan_json_value(
    display: &str,
    title: &str,
    prompt: &str,
    token_estimate: usize,
    warnings: &[String],
    reservations: &[ReservedPath],
) -> serde_json::Value {
    serde_json::json!({
        "spec_id": display,
        "title": title,
        "prompt": prompt,
        "token_estimate": token_estimate,
        "warnings": warnings,
        "reservations": reservations,
    })
}

fn assemble_ultraplan_prompt(
    store: &aida_core::RequirementsStore,
    target: &aida_core::models::Requirement,
    helpers_section: Option<&str>,
    include_comments: bool,
    reservations: &[ReservedPath],
) -> (String, Vec<String>) {
    // TASK-247: raised from 1800 — a truncated description dropped the
    // densest planning context. Comments now carry the long-form
    // enrichment, but the description still deserves real room.
    const DESC_CHAR_CAP: usize = 16_000;
    const SIBLING_CAP: usize = 12;
    let mut warnings: Vec<String> = Vec::new();
    let display = target.display_id();
    let resolve = |id: &uuid::Uuid| store.requirements.iter().find(|r| &r.id == id);

    let mut p = String::new();
    p.push_str(&format!(
        "Plan the implementation of {display}: {}.\n\n",
        target.title
    ));

    // ── Requirement body ──
    p.push_str("## Requirement\n\n");
    let desc = target.description.trim();
    if desc.is_empty() {
        p.push_str("_(no description on the spec)_\n\n");
        warnings.push("spec has no description — the plan will be weakly grounded".to_string());
    } else if desc.chars().count() > DESC_CHAR_CAP {
        let truncated: String = desc.chars().take(DESC_CHAR_CAP).collect();
        p.push_str(&truncated);
        p.push_str("\n\n_(description truncated to fit the prompt budget)_\n\n");
    } else {
        p.push_str(desc);
        p.push_str("\n\n");
    }

    // ── Acceptance criteria ──
    p.push_str("## Acceptance criteria\n\n");
    match extract_acceptance_section(&target.description) {
        Some(acc) if !acc.trim().is_empty() => {
            p.push_str(acc.trim());
            p.push('\n');
        }
        _ => {
            p.push_str(
                "_(none specified — add a `## Acceptance` section to the spec for a sharper plan)_\n",
            );
            warnings.push(
                "spec has no `## Acceptance` section — the plan will be weaker without \
                 explicit acceptance criteria"
                    .to_string(),
            );
        }
    }
    p.push('\n');

    // ── Comments (enrichment context) ──
    // TASK-247: a spec's comments accumulate the densest planning
    // context (anti-patterns, design forks, reusable helpers). Pull them
    // in unless the caller opted out with `--no-comments`.
    if include_comments {
        if let Some(section) = ultraplan_comments_section(&target.comments) {
            p.push_str(&section);
        }
    }

    // TASK-517: surface reserved namespaces before the plan proposes files.
    // This catches likely collisions (notably docs/aida/) while the model is
    // still choosing the implementation shape.
    if let Some(section) = reserved_paths_section(reservations) {
        p.push_str(&section);
    }

    // ── Related-spec context ──
    let parents: Vec<&aida_core::models::Requirement> = target
        .relationships
        .iter()
        .filter(|r| r.rel_type == aida_core::RelationshipType::Child)
        .filter_map(|r| resolve(&r.target_id))
        .collect();
    let children: Vec<&aida_core::models::Requirement> = target
        .relationships
        .iter()
        .filter(|r| r.rel_type == aida_core::RelationshipType::Parent)
        .filter_map(|r| resolve(&r.target_id))
        .collect();
    // Other typed relationships (verifies / references / custom) — the
    // "composes / depends-on" signal the prompt should anchor on.
    let other_rels: Vec<(String, &aida_core::models::Requirement)> = target
        .relationships
        .iter()
        .filter(|r| {
            !matches!(
                r.rel_type,
                aida_core::RelationshipType::Parent | aida_core::RelationshipType::Child
            )
        })
        .filter_map(|r| resolve(&r.target_id).map(|req| (r.rel_type.to_string(), req)))
        .collect();
    let parent_ids: HashSet<uuid::Uuid> = parents.iter().map(|r| r.id).collect();
    let siblings: Vec<&aida_core::models::Requirement> = if parent_ids.is_empty() {
        Vec::new()
    } else {
        store
            .requirements
            .iter()
            .filter(|r| {
                r.id != target.id
                    && r.relationships.iter().any(|rel| {
                        rel.rel_type == aida_core::RelationshipType::Child
                            && parent_ids.contains(&rel.target_id)
                    })
            })
            .collect()
    };

    if !parents.is_empty() || !children.is_empty() || !siblings.is_empty() || !other_rels.is_empty()
    {
        p.push_str("## Related specs\n\n");
        for parent in &parents {
            p.push_str(&format!("- Parent: {}\n", ultraplan_spec_line(parent)));
        }
        for (rel, req) in &other_rels {
            p.push_str(&format!("- {}: {}\n", rel, ultraplan_spec_line(req)));
        }
        if !children.is_empty() {
            p.push_str("- Children:\n");
            for child in &children {
                p.push_str(&format!("  - {}\n", ultraplan_spec_line(child)));
            }
        }
        if !siblings.is_empty() {
            p.push_str(&format!(
                "- Siblings (share a parent — {} total):\n",
                siblings.len()
            ));
            for sib in siblings.iter().take(SIBLING_CAP) {
                p.push_str(&format!("  - {}\n", ultraplan_spec_line(sib)));
            }
            if siblings.len() > SIBLING_CAP {
                p.push_str(&format!(
                    "  - _(+{} more siblings omitted to fit the prompt budget)_\n",
                    siblings.len() - SIBLING_CAP
                ));
            }
        }
        p.push('\n');
    }

    // ── Plan structure ──
    p.push_str("## Plan structure\n\n");
    p.push_str(ULTRAPLAN_STRUCTURE);
    p.push_str("\n\n");

    // ── Reusable helpers (trace-graph derived) ──
    match helpers_section {
        Some(section) => {
            p.push_str(section);
            if !section.ends_with('\n') {
                p.push('\n');
            }
            p.push('\n');
        }
        None => {
            warnings.push(
                "no trace-graph reusable helpers found — Reusable helpers section omitted"
                    .to_string(),
            );
        }
    }

    // ── Style notes ──
    p.push_str("## Style notes\n\n");
    p.push_str(
        "- Prefer symbol refs (`fn handle_pull_command`) over line refs (`main.rs:19713`) — \
         line refs drift fast.\n\
         - Order the Files section so each commit builds clean.\n\
         - The Verification section must be an executable bash smoke test.\n\
         - Keep the Followups section to one TASK-title-sized line per item.\n",
    );

    (p, warnings)
}

// trace:TASK-514 | ai:antigravity
pub(crate) fn ultraplan_copy_success_message(display: &str, token_estimate: usize) -> String {
    format!(
        "assembled /ultraplan prompt for {} (~{} tokens) — copied to clipboard (use --stdout to print, --json for machine consumption)",
        display,
        token_estimate
    )
}

/// `aida ultraplan <SPEC>` — assemble + deliver the planning prompt.
fn handle_ultraplan_command(
    spec_arg: &str,
    stdout: bool,
    json: bool,
    no_comments: bool,
) -> Result<()> {
    let project_root = find_project_root()?;
    // TASK-304: `[ultraplan] mode = "never"` disables the integration for
    // this project — refuse with a message and write nothing to the
    // clipboard. Printed to stderr so `--json` / `--stdout` consumers see a
    // clean (empty) stdout. trace:TASK-304 | ai:claude
    if read_ultraplan_config(&project_root).mode == UltraplanMode::Never {
        eprintln!(
            "{} `aida ultraplan` is disabled for this project \
             (`[ultraplan] mode = \"never\"` in .aida/config.toml).",
            "Note:".yellow().bold()
        );
        eprintln!(
            "  {}",
            "Set mode = \"on-demand\" or \"suggested\" to re-enable.".dimmed()
        );
        return Ok(());
    }
    let store = load_store_for_lookup(&project_root)
        .ok_or_else(|| anyhow::anyhow!("could not load the AIDA requirements store"))?;
    let target = if let Ok(uuid) = uuid::Uuid::parse_str(spec_arg) {
        store.requirements.iter().find(|r| r.id == uuid)
    } else {
        store.get_requirement_by_spec_id(spec_arg)
    }
    .ok_or_else(|| anyhow::anyhow!("requirement `{spec_arg}` not found"))?;

    let helpers = build_reusable_helpers_section(&store, &project_root, target);
    let (reservations, reservation_warnings) = read_reserved_paths(&project_root);
    let (prompt, warnings) = assemble_ultraplan_prompt(
        &store,
        target,
        helpers.as_deref(),
        !no_comments,
        &reservations,
    );
    let mut warnings = warnings;
    warnings.extend(reservation_warnings);
    let token_estimate = prompt.chars().count() / 4;
    let display = target.display_id();

    if json {
        let out = ultraplan_json_value(
            &display,
            &target.title,
            &prompt,
            token_estimate,
            &warnings,
            &reservations,
        );
        println!("{}", serde_json::to_string_pretty(&out)?);
        return Ok(());
    }

    if stdout {
        print!("{prompt}");
        for w in &warnings {
            eprintln!("{} {}", "Warning:".yellow().bold(), w);
        }
        return Ok(());
    }

    // Default: copy to clipboard, falling back to stdout when no tool exists.
    // trace:TASK-514 | ai:antigravity
    if copy_to_clipboard(&prompt) {
        println!(
            "{} {}",
            "✓".green(),
            ultraplan_copy_success_message(&display.bold().to_string(), token_estimate)
        );
        println!(
            "  {}",
            "paste it into a Claude Code session, prefixed with /ultraplan".dimmed()
        );
    } else {
        eprintln!(
            "{} no clipboard tool found (wl-copy/xclip/xsel/pbcopy/clip) — printing instead",
            "Note:".bold()
        );
        print!("{prompt}");
    }
    for w in &warnings {
        eprintln!("{} {}", "Warning:".yellow().bold(), w);
    }
    Ok(())
}

