                // trace:TASK-285 | ai:claude
                if max.is_some() {
                    anyhow::bail!(
                        "`--max` bounds a batch drain — pair it with `--batch NAME` \
                         (e.g. `aida queue work --batch NAME --auto-complete --max 3`)"
                    );
                }
                // TASK-292: with no positional SPEC, inherit the no-arg
